e2cbf77c947","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":233,"contenido_md5":"c135537cec8b0e1b9d396def3c03d99f"},{"identificador":"Transitorio Décimo Octavo","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"3c626412-3bcb-452d-a6bb-a5b6788060ef","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":234,"contenido_md5":"65d70e00451abbf6da799bfa4be12ad9"},{"identificador":"Transitorio Décimo Noveno","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"88e2a81e-a10a-4a97-99de-3941abccdd7f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":235,"contenido_md5":"51545e739100fd4e7fbac417dc3e10f0"},{"identificador":"Transitorio Vigésimo","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"f10bb70f-0076-48ef-85e3-7f88d6b60ad5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":236,"contenido_md5":"201368ca39e057988a35b7c4ff342fa3"},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"76a754ac-f657-5a89-82f0-475075494e93","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":237,"contenido_md5":"0503a5ed5037376db9c19ee54e179df2"}],"after":[{"id":"d79154ae-bb28-4bb9-87e1-94078136a2ea","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Preámbulo","contenido":"LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN Secretaría General Secretaría de Servicios Parlamenta rios Nueva Ley DOF 20 - 03 - 2025 1 de 64 LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA TEXTO VIGENTE Nueva Ley publicada en el Diario Oficial de la Federación el 20 de marzo de 2025 Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos. - Presidencia de la República . CLAUDIA SHEINBAUM PARDO , Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed: Que el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente DECRETO \" EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, DECRETA: SE EXPIDEN LA LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA; LA LEY GENERAL DE PROTECCIÓN DE DATOS PERSONALES EN POSESIÓN DE SUJETOS OBLIGADOS; LA LEY FEDERAL DE PROTECCIÓN DE DATOS PERSONALES EN POSESIÓN DE LOS PARTICULARES; Y SE REFORMA EL ARTÍCULO 37 , FRACCIÓN XV, DE LA LEY ORGÁNICA DE LA ADMINISTRACIÓN PÚBLICA FEDERAL Artículo Primero. - Se expide la Ley General de Transparencia y Acceso a la Información Pública, para quedar como sigue: LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA TÍ TULO PRIMERO DISPOSICIONES GENERALES Capítulo I Disposiciones Preliminares","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":0},{"id":"b1bcab9d-b628-4b63-afe8-68e5bca1d862","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 1.","contenido":"La presente Ley es reglamentaria del artículo 6o. de la Constitución Política de los Estados Unidos \n Mexicanos, en materia de transparencia y acceso a la información públ ica y sus disposiciones son de orden público, \n de interés social y de observancia general en todo el territorio nacional, con el fin de garantizar el derecho humano al \n acceso a la información y promover la transparencia y rendición de cuentas.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":1},{"id":"007e8b3f-bb93-407b-83f4-65ea4347936d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 2.","contenido":"E sta Ley tiene por objeto: \n I. Establecer los principios, bases generales y procedimientos para garantizar el derecho de acceso a la \n información pública en posesión de cualquier autoridad, agencia, comisión, comité, corporación, ente, \n entidad, institución, ó rgano, organismo o equivalente de los poderes Ejecutivo, Legislativo y Judicial de \n los tres niveles de gobierno, órganos constitucionalmente autónomos, partidos políticos, fideicomisos y \n fondos públicos, así como de cualquier persona física, moral o sindic ato que reciba y ejerza recursos \n públicos o realice actos de autoridad de la Federación, de las entidades federativas, de los municipios \n o demarcaciones territoriales de Ciudad de México; \n II. Distribuir las competencias de las Autoridades garantes en mater ia de transparencia y acceso a la \n información pública, conforme a sus respectivos ámbitos de responsabilidad; \n III. Establecer las bases mínimas que regirán los procedimientos para garantizar el ejercicio del derecho \n de acceso a la información pública; \n IV. Establecer procedimientos sencillos y expeditos para el ejercicio del derecho de acceso a la \n información pública, que permitan garantizar condiciones homogéneas y accesibles para las personas \n solicitantes; \n V. Regular los medios de impugnación por parte de las Autoridades garantes; \n VI. Establecer las bases y la información de interés público que deben ser difundidos proactivamente por \n los sujetos obligados; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 2 de 64 \n VII. Regular la organización y funcionamiento del Sistema Nacional de Acceso a la Información, así com o \n establecer las bases de coordinación entre sus integrantes; \n VIII. Promover, fomentar y difundir la cultura de la transparencia en el ejercicio de la función pública, el \n acceso a la información pública, la participación ciudadana y la rendición de cuentas , mediante \n políticas públicas y mecanismos que garanticen la difusión de información oportuna, verificable, \n comprensible, actualizada y completa, en los formatos más adecuados y accesibles para el público, \n tomando en cuenta las condiciones sociales, económ icas y culturales de cada región; \n IX. Propiciar la participación ciudadana en los procesos de toma de decisiones públicas, con el fin de \n fortalecer la democracia, y \n X. Establecer los mecanismos necesarios para garantizar el cumplimiento de las disposicione s de esta \n Ley, a través de la aplicación efectiva de medidas de apremio y sanciones que correspondan.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":2},{"id":"c96ec9f3-6203-4a52-9638-1f5b3a675dcc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 3.","contenido":"Para los efectos de la presente Ley se entiende por: \n I. Ajustes Razonables: Modificaciones o adaptaciones necesarias y adecuadas que no impong an una \n carga desproporcionada o indebida, cuando se requieran en un caso particular, con el fin de garantizar \n a las personas con discapacidad el goce y ejercicio, en condiciones de igualdad, de los derechos \n humanos; \n II. Áreas: Instancias que disponen o pue den disponer de la información pública. En el sector público, \n serán aquellas que estén previstas en el reglamento interior, el estatuto orgánico respectivo o sus \n equivalentes; \n III. Autoridad garante federal: Transparencia para el Pueblo, órgano administrat ivo desconcentrado de \n la Secretaría Anticorrupción y Buen Gobierno; \n IV. Autoridad garante local: Órganos encargados de la contraloría u homólogos en el poder ejecutivo de \n las entidades federativas, quienes conocerán también de los asuntos en materia de tra nsparencia de \n sus municipios o demarcaciones territoriales de Ciudad de México, conforme a lo que establezcan sus \n respectivas leyes; \n V. Autoridades garantes: Autoridades garantes federal y local; el órgano de control y disciplina del \n Poder Judicial; los ór ganos internos de control o equivalentes de los órganos constitucionales \n autónomos, las contralorías internas del Congreso de la Unión; el Instituto Nacional Electoral, por \n cuanto hace al acceso a la información pública de los partidos políticos; el Centro Federal de \n Conciliación y Registro Laboral y el Tribunal Federal de Conciliación y Arbitraje, estos dos últimos por \n cuanto hace al acceso a la información pública de los sindicatos y los órganos encargados de la \n contraloría interna u homólogos de los pode res legislativo y judicial, así como los órganos \n constitucionales autónomos, de las entidades federativas; \n VI. Comité de Transparencia: Instancia a la que hace referencia el artículo 39 de la presente Ley; \n VII. Consejo Nacional: Consejo del Sistema Naciona l de Acceso a la Información Pública al que hace \n referencia el artículo 26 de la presente Ley; \n VIII. Datos Abiertos: Los datos digitales de carácter público que son accesibles en línea, que pueden ser \n usados, reutilizados y redistribuidos por cualquier per sona interesada, los cuales tienen las siguientes \n características: \n a ) Accesibles: Disponibles para la mayor cantidad de personas usuarias posibles, para cualquier \n propósito; \n b ) Integrales: Contienen el tema que describen a detalle y con metadatos necesario s; \n c ) Gratuitos: No requieren contraprestación alguna para su acceso; \n d ) No discriminatorios: Están disponibles para cualquier persona, sin necesidad de registro; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 3 de 64 \n e ) Oportunos: Son actualizados periódicamente, conforme se generen; \n f ) Permanentes: Se conser van en el tiempo, para lo cual, las versiones históricas relevantes para \n uso público se mantendrán disponibles con identificadores adecuados al efecto; \n g ) Primarios: Provienen directamente de la fuente de origen con el mayor nivel de desagregación \n posible; \n h ) Legibles por máquinas: Deberán estar estructurados, total o parcialmente, para ser procesados e \n interpretados por equipos electrónicos de manera automática; \n i ) En formatos abiertos: Estarán disponibles con el conjunto de características técnicas y de \n p resentación que corresponden a la estructura lógica usada para almacenar datos en un archivo \n digital, cuyas especificaciones técnicas están disponibles públicamente, que no suponen una \n dificultad de acceso y que su aplicación y reproducción no estén condic ionadas a \n contraprestación alguna, y \n j ) De libre uso: Requieren la cita de la fuente de origen como único requisito para su uso; \n IX. Documento: Expedientes, reportes, estudios, actas, resoluciones, oficios, correspondencia, acuerdos, \n directivas, directrice s, circulares, contratos, convenios, instructivos, notas, memorandos, estadísticas y, \n en general, cualquier registro que documente el ejercicio de las facultades, funciones y competencias \n de los sujetos obligados, sus personas servidoras públicas y demás i ntegrantes, sin importar su fuente \n o fecha de elaboración, ni el medio en el que se encuentren, ya sea escrito, impreso, sonoro, visual, \n electrónico, informático u holográfico; \n X. Entidades federativas: Partes integrantes de la Federación que son los Estad os de Aguascalientes, \n Baja California, Baja California Sur, Campeche, Coahuila de Zaragoza, Colima, Chiapas, Chihuahua, \n Durango, Guanajuato, Guerrero, Hidalgo, Jalisco, México, Michoacán de Ocampo, Morelos, Nayarit, \n Nuevo León, Oaxaca, Puebla, Querétaro, Q uintana Roo, San Luis Potosí, Sinaloa, Sonora, Tabasco, \n Tamaulipas, Tlaxcala, Veracruz de Ignacio de la Llave, Yucatán, Zacatecas y Ciudad de México; \n XI. Expediente: Unidad documental física o electrónica compuesta por documentos de archivo, \n ordenados y re lacionados por un mismo asunto, actividad o trámite de los sujetos obligados; \n XII. Formatos Abiertos: Conjunto de características técnicas y de presentación de la información que \n corresponden a la estructura lógica usada para almacenar datos de forma integ ral y que facilitan su \n procesamiento digital, cuyas especificaciones están disponibles públicamente y que permiten el \n acceso sin restricción de uso por parte de las personas usuarias; \n XIII. Formatos Accesibles: Cualquier manera o forma alternativa que dé a cceso a las personas \n solicitantes de información, en forma tan viable y cómoda como la de las personas sin discapacidad ni \n otras dificultades para acceder a cualquier texto impreso y/o cualquier otro formato convencional en el \n que la información pueda enco ntrarse; \n XIV. Información de Interés Público: Es aquella que resulta relevante o útil para la sociedad y no \n simplemente de interés individual, cuya divulgación contribuye a que el público conozca las actividades \n que realizan los sujetos obligados en el eje rcicio de sus funciones y como ejercen los recursos \n públicos, así como a exigir la rendición de cuentas y el combate a la corrupción; \n XV. Ley: Ley General de Transparencia y Acceso a la Información Pública; \n XVI. Personas servidoras públicas: Las mencionada s en el primer párrafo del artículo 108 de la \n Constitución Política de los Estados Unidos Mexicanos y sus correlativos en las Constituciones locales; \n XVII. Plataforma Nacional: Plataforma Nacional de Transparencia, a la que se hace referencia en el \n artícul o 44 de la presente Ley; \n XVIII. Sistema Nacional: Sistema Nacional de Acceso a la Información Pública; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 4 de 64 \n XIX. Sujetos obligados: Cualquier autoridad, agencia, comisión, comité, corporación, ente, entidad, \n institución, órgano, organismo o equivalente de los p oderes Ejecutivo, Legislativo y Judicial de los tres \n niveles de gobierno, órganos constitucionalmente autónomos, partidos políticos, fideicomisos y fondos \n públicos, así como cualquier persona física, moral o sindicato que reciba y ejerza recursos públicos o \n realice actos de autoridad en los referidos niveles de gobierno; \n XX. Unidad de Transparencia: Instancia a la que hace referencia el artículo 41 de esta Ley, y \n XXI. Versión Pública: Documento o expediente en el que se otorga acceso a la información públic a, previa \n eliminación u omisión de aquellas partes o secciones que se encuentren clasificadas conforme a la \n Ley.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":3},{"id":"661f7e14-fabb-4085-8053-cdc69a2bc2a1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 4.","contenido":"El derecho humano de acceso a la información comprende solicitar, investigar, difundir, buscar y \n recibir información. \n Toda la infor mación generada, obtenida, adquirida, transformada o en posesión de los sujetos obligados es \n pública y accesible a cualquier persona, en los términos y condiciones que se establezcan en la presente Ley, en los \n tratados internacionales de los que el Estado mexicano sea parte, las leyes de las entidades federativas y en las \n disposiciones jurídicas aplicables dentro de sus respectivas competencias. \n La información podrá ser clasificada como reservada temporalmente por razones de interés público o seguridad \n naci onal conforme a los términos establecidos por esta Ley.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":4},{"id":"f297730b-d5b4-47f4-9506-229f7fc083ff","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 5.","contenido":"No podrá clasificarse como reservada aquella información relacionada con violaciones graves a los \n derechos humanos o con delitos de lesa humanidad, conforme al derecho nacional o a los tra tados internacionales \n de los que el Estado mexicano sea parte. \n Ninguna persona podrá ser objeto de inquisición judicial o administrativa derivado del ejercicio del derecho de \n acceso a la información, ni se podrá restringir este derecho mediante vías o medi os, directos o indirectos.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":5},{"id":"ddd66d18-5a35-471b-938f-f88aefb53a75","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 6.","contenido":"El Estado garantizará el efectivo acceso de toda persona a la información en posesión de cualquier \n autoridad, agencia, comisión, comité, corporación, ente, entidad, institución, órgano, organismo o equivalente de los \n poderes Ejecutivo, Legislativo y Judicial de los tres niveles de gobierno, órganos constitucionalmente autónomos, \n partidos políticos, fideicomisos y fondos públicos, así como de cualquier persona física, moral o sindicato que reciba \n y ejerza recursos públi cos o realice actos de autoridad de la Federación, de las entidades federativas, de los \n municipios o demarcaciones territoriales de la Ciudad de México.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":6},{"id":"3dd045ff-a152-457a-90bf-da19526481a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 7.","contenido":"El derecho de acceso a la información y la clasificación de la información se interpretarán conforme a \n los principios establecidos en la Constitución Política de los Estados Unidos Mexicanos, en los tratados \n internacionales de los que el Estado mexicano sea parte, y en la presente Ley. \n En la aplicación e interpretación de la presente Ley, deberá prevalecer el principio de máxima publicidad, \n conforme a lo dispuesto en la Constitución Política de los Estados Unidos Mexicanos, en los tratados internacionales \n de los que el Estado mexicano sea parte, así como en las resoluciones y sentencias vinculant es que emitan los \n órganos nacionales e internacionales especializados. En todo momento, se deberá favorecer la protección más \n amplia de los derechos de las personas. \n Para el caso de la interpretación, se podrán considerar los criterios, determinaciones y o piniones de las \n Autoridades garantes y los organismos internacionales en dicha materia. \n Capítulo II \n De los Principios Generales \n Sección Primera \n De los principios rectores de las Autoridades garantes","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"Disposiciones Preliminares","seccion_nombre":null,"orden":7},{"id":"94859d98-c0c0-444e-953f-9d22358445d7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 8.","contenido":"Las Autoridades garantes deberán regir su fun cionamiento de acuerdo a los siguientes principios: \n I. Certeza: Otorga seguridad y certidumbre jurídica a las personas particulares, ya que permite conocer \n si las acciones que realizan se ajustan a derecho y garantizan que los procedimientos sean \n verificab les, fidedignos y confiables; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 5 de 64 \n II. Congruencia: Implica que exista concordancia entre el requerimiento formulado por el particular y la \n respuesta proporcionada por el sujeto obligado; \n III. Documentación: Consiste en que los sujetos obligados deberán otorgar acceso a los documentos que \n se encuentren en sus archivos o que estén obligados a documentar, de acuerdo con sus facultades, \n competencias o funciones, conforme a las características físicas de la información o del lugar donde se \n encuentre, sin que ello im plique la elaboración de documentos ad hoc para atender las solicitudes de \n información; \n IV. Eficacia: Tutela de manera efectiva el derecho de acceso a la información pública; \n V. Excepcionalidad: Implica que la información podrá ser clasificada como reserva da o confidencial \n únicamente si se actualizan los supuestos que esta Ley expresamente señala; \n VI. Exhaustividad: Significa que la respuesta se refiera expresamente a cada uno de los puntos \n solicitados, con las limitantes del principio de documentación; \n VII . Imparcialidad: Deben en sus actuaciones, ser ajenos o extraños a los intereses de las partes en \n controversia, sin inclinaciones hacia ninguna de las partes involucradas; \n VIII. Independencia: Deben actuar sin influencias que puedan afectar la imparcialida d o la eficacia del \n derecho de acceso a la información; \n IX. Legalidad: Ajustar su actuación a las disposiciones jurídicas aplicables, fundamentando y motivando \n sus resoluciones y actos; \n X. Máxima publicidad: Promover que toda la información en posesión de los sujetos obligados \n documentada sea pública y accesible, salvo en los casos expresamente establecidos en esta Ley o en \n otras disposiciones jurídicas aplicables, en los que podrá ser clasificada como reservada o confidencial \n por razones de interés público o seguridad nacional; \n XI. Objetividad: Ajustar su actuación a los supuestos de ley que deben ser aplicados al analizar el caso \n en concreto para resolver, sin considerar juicios personales; \n XII. Profesionalismo: Deben sujetar su actuación a conocimientos t écnicos, teóricos y metodológicos, que \n garanticen un desempeño eficiente y eficaz en el ejercicio de su actuar, y \n XIII. Transparencia: Dar publicidad a los actos relacionados con sus atribuciones, así como dar acceso a \n la información que tengan la obligaci ón de documentar. \n Sección Segunda \n De los Principios en Materia de Transparencia y Acceso a la Información Pública","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":8},{"id":"dc1c54ef-4150-421b-8d03-db646fc2ed91","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 9.","contenido":"Las Autoridades garantes, así como los sujetos obligados, en el ejercicio, tramitación e interpretación \n de la presente Ley, las co rrespondientes de las entidades federativas y demás disposiciones relacionadas con la \n referida materia, deberán atender a los principios establecidos en la presente sección.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":9},{"id":"86e0dc67-8072-4757-9bce-35c7ae9529a2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   10.","contenido":"Las Autoridades garantes otorgarán las medidas pertinentes para asegu rar el acceso a la \n información a todas las personas, en igualdad de condiciones con las demás. \n Está prohibida toda forma de discriminación que limite o impida el ejercicio del derecho de acceso a la \n información pública en posesión de los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":10},{"id":"95690938-84f6-49b7-8994-982d06378afc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 11.","contenido":"Toda la información pública documentada, obtenida, adquirida, transformada o en posesión de los \n sujetos obligados es pública y debe ser accesible a cualquier persona. Para ello, se deberán habilitar los medios y \n acciones disponibles, conforme a los términos y condiciones establecidos en esta Ley y demás disposiciones \n jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":11},{"id":"012b9deb-1dcb-48b6-9862-dafaab9ddfd4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 12.","contenido":"Los sujetos obligados en la generación, publicación y entrega de información, deberán: \n I. Garantizar que esta sea accesible, confiable, completa , verificable, veraz y oportuna, atendiendo las \n necesidades del derecho de acceso a la información de toda persona, sin embargo, estará sujeta a un \n régimen de excepciones claramente definido, y \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 6 de 64 \n II. Procurar que se utilice un lenguaje inclusivo, claro y com prensible para cualquier persona, y en la \n medida de lo posible, su accesibilidad y traducción a lenguas indígenas.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":12},{"id":"095078d0-b6d9-4b90-ade5-ad9bd7e5166d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 13.","contenido":"Las Autoridades garantes, en el ámbito de sus atribuciones, deberán suplir cualquier deficiencia para \n garantizar el ejercicio de l derecho de acceso a la información, sin que ello implique variar la solicitud, atendiendo al \n principio de congruencia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":13},{"id":"679f6a45-d45e-4419-8ac4-06bcebccbac1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 14.","contenido":"El ejercicio del derecho de acceso a la información no podrá ser restringido ni estará condicionado a \n que la persona solic itante acredite interés alguno, ni a que justifique el uso que hará de la información solicitada.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":14},{"id":"94ae9a04-09b8-4065-b7c0-abc7c8f927d5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 15.","contenido":"El ejercicio del derecho de acceso a la información es gratuito y solo podrá requerirse el cobro \n correspondiente a la modalidad de reproducción y entrega solicitada. \n En ningún caso los ajustes razonables que se realicen para garantizar el acceso a la información a personas \n solicitantes con discapacidad, será con algún costo.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":15},{"id":"48e0e949-90f8-4e28-9182-dec0757a8c56","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 16.","contenido":"Se presume que la información debe existir cuando se refiere a las facultades, competencias y \n funciones que los ordenamientos jurídicos aplicables otorgan a los sujetos obligados y se tenga la obligación jurídica \n de documentarla. \n En los casos en que ciertas facultades, competencias o funciones no se hayan ejercido, el sujeto obligado deberá \n motivar la respuesta que lo justifique.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":16},{"id":"f95feb58-b823-48d5-917e-8b281b4c0680","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 17.","contenido":"Ante la negativa de acceso a la información o inexistencia, el sujeto obligado deberá indicar que la \n información solicitada se encuentra comprendida dentro de alguna de las exce pciones previstas en esta Ley o, en su \n caso, que no corresponde a sus facultades, competencias o funciones, o bien, no existe la obligación jurídica de \n documentarla.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":17},{"id":"b79832ea-3335-4611-918f-5e5f0649c013","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 18.","contenido":"Todo procedimiento relacionado con el derecho de acceso, entrega y publicació n a la información \n deberá: \n I. Sustanciarse de manera sencilla, clara y expedita, conforme a las disposiciones establecidas en esta \n Ley, y \n II. Propiciar las condiciones necesarias para garantizar que este sea accesible a cualquier persona, de \n conformidad co n el artículo 1o. de la Constitución Política de los Estados Unidos Mexicanos. \n Capítulo III \n De los Sujetos Obligados","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Principios Generales","seccion_nombre":null,"orden":18},{"id":"8f13295a-8263-41e9-add5-e367fbd28e24","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 19.","contenido":"Los sujetos obligados deberán transparentar y garantizar el acceso a la información documentada en \n su poder, de conformidad co n las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Sujetos Obligados","seccion_nombre":null,"orden":19},{"id":"4bafdc47-7853-430e-a036-a3858256876a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 20.","contenido":"Para el cumplimiento de los objetos de esta Ley, los sujetos obligados deberán cumplir con las \n siguientes obligaciones, según corresponda, de acuerdo con su naturaleza: \n I. Constituir el Comité de Trans parencia y las Unidades de Transparencia, así como velar por su correcto \n funcionamiento conforme a su normativa interna; \n II. Designar en las Unidades de Transparencia a las personas titulares que dependan directamente de la \n persona titular del sujeto oblig ado y que preferentemente cuenten con experiencia en la materia; \n III. Proporcionar capacitación continua y especializada al personal que forme parte de los Comités y las \n Unidades de Transparencia; \n IV. Constituir y mantener actualizados sus sistemas de arch ivo y gestión documental, conforme a las \n disposiciones jurídicas aplicables; \n V. Promover la generación, documentación y publicación de la información en formatos abiertos y \n accesibles; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 7 de 64 \n VI. Proteger y resguardar la información clasificada como reservada o c onfidencial, conforme a las \n disposiciones aplicables; \n VII. Reportar a las Autoridades garantes competentes sobre las acciones de implementación de las \n disposiciones aplicables en la materia, en los términos que estos determinen; \n VIII. Atender los requerimi entos, observaciones, recomendaciones y criterios en materia de transparencia y \n acceso a la información emitidos por las Autoridades garantes y el Sistema Nacional; \n IX. Fomentar el uso de tecnologías de la información para garantizar la transparencia, el e jercicio del \n derecho de acceso a la información y la accesibilidad a estos; \n X. Cumplir con las resoluciones emitidas por las Autoridades garantes; \n XI. Publicar y mantener actualizada la información relativa a las obligaciones de transparencia, integrando \n l os archivos o ligas correspondientes en la Plataforma Nacional según los procedimientos que para ello \n se establezcan; \n XII. Difundir proactivamente la información de interés público; \n XIII. Dar atención a las recomendaciones de las Autoridades garantes; \n XIV. Promover acuerdos con instituciones públicas especializadas que pudieran auxiliarles a entregar las \n respuestas a solicitudes de información en lengua indígena, braille o cualquier otro ajuste razonable \n con el formato accesible correspondiente, en la forma más eficiente; \n XV. Promover la digitalización de la información en su posesión y la utilización de las tecnologías de \n información y comunicación, de conformidad con las políticas que al efecto establezca el Sistema \n Nacional; \n XVI. Responder las solicitudes en materia de acceso a la información a través de la Plataforma Nacional en \n los términos y plazos establecidos en la presente Ley, sin perjuicio del medio en que se hayan \n presentado o la modalidad de reproducción y entrega solicitada, y \n XVII. Las demás qu e resulten de las disposiciones aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Sujetos Obligados","seccion_nombre":null,"orden":20},{"id":"127f77af-9240-4195-85de-02d5f88b304c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 21.","contenido":"Los sujetos obligados serán responsables del cumplimiento de las obligaciones, procedimientos y \n responsabilidades establecidas en esta Ley y las correspondientes de las entidades federativas, en los términos que \n las mismas determinen.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Sujetos Obligados","seccion_nombre":null,"orden":21},{"id":"9aafd115-1c5d-4124-a9f4-e7ea86447d76","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 22.","contenido":"Los fideicomisos y fondos públicos que no cuenten con estructura orgánica y, por lo tanto, no sean \n considerados una entidad paraestatal, así como de los mandatos públicos y demás contratos análogos, deberán \n cumplir con las obligaciones de esta Ley a través de la unidad administrativa responsable de coordinar su operación. \n TÍTULO SEGUNDO \n RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN \n Capítulo I \n Del Sistema Nacional","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"De los Sujetos Obligados","seccion_nombre":null,"orden":22},{"id":"418a44fc-614d-4178-95ee-222985a79668","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   23.","contenido":"El Sistema N acional se integra por el conjunto orgánico y articulado de sus miembros, \n procedimientos, instrumentos y políticas, con el objeto de fortalecer la rendición de cuentas del Estado mexicano. \n Tiene como finalidad coordinar y evaluar las acciones relativas a l a política pública transversal de transparencia y \n acceso a la información pública, así como establecer e implementar los criterios y lineamientos correspondientes, de \n conformidad con lo señalado en la presente Ley y demás disposiciones jurídicas aplicables .","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Sistema Nacional","seccion_nombre":null,"orden":23},{"id":"2ede7b49-d729-4de3-8a79-04f3046c694d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 24.","contenido":"El Sistema Nacional se conformará a partir de la coordinación que se realice entre las distintas \n instancias que, en razón de sus ámbitos de competencia, contribuyen a la transparencia a nivel nacional, en los tres \n niveles de gobierno. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 8 de 64 \n Este S istema que favorecerá a la generación de información de calidad, a la gestión de la información, al \n procesamiento de la misma como un medio para facilitar el conocimiento, a la evaluación de la gestión pública, a la \n promoción del derecho de acceso a la inf ormación, a la difusión de una cultura de la transparencia y a su \n accesibilidad, así como, a una fiscalización y rendición de cuentas efectivas.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Sistema Nacional","seccion_nombre":null,"orden":24},{"id":"d70f0654-8dbf-4909-b30c-374d613fafca","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 25.","contenido":"El Sistema Nacional, que funcionará por conducto de un Consejo Nacional, tiene las siguientes \n func iones: \n I. Establecer lineamientos, instrumentos, objetivos, indicadores, metas, estrategias, códigos de buenas \n prácticas, modelos y políticas integrales, sistemáticas, continuas y evaluables, tendientes a cumplir con \n los objetos de la presente Ley; \n II. Pro mover e implementar acciones para garantizar condiciones de accesibilidad para que los grupos de \n atención prioritaria puedan ejercer, en igualdad de condiciones, el derecho de acceso a la información \n pública; \n III. Desarrollar y establecer programas comunes de alcance nacional, para la promoción, investigación, \n diagnóstico y difusión en materia de transparencia, acceso a la información pública y apertura \n gubernamental en el país; \n IV. Establecer los criterios para la publicación de los indicadores que permita n a los sujetos obligados \n rendir cuentas del cumplimiento de sus objetivos y resultados obtenidos; \n V. Coadyuvar en la elaboración, fomento y difusión entre los sujetos obligados de los criterios para la \n sistematización y conservación de archivos que permit an localizar eficientemente la información \n pública de acuerdo a las disposiciones jurídicas aplicables en la materia; \n VI. Establecer políticas en cuanto a la digitalización de la información pública en posesión de los sujetos \n obligados, el uso de tecnologí as de información y la implementación de Ajustes Razonables, que \n garanticen el pleno acceso a esta; \n VII. Diseñar e implementar políticas en materia de generación, actualización, organización, clasificación, \n publicación, difusión, conservación y accesibilid ad de la información pública, de conformidad con las \n disposiciones jurídicas aplicables; \n VIII. Promover la participación ciudadana a través de mecanismos eficaces en la planeación, \n implementación y evaluación de políticas en la materia; \n IX. Establecer prog ramas de profesionalización, actualización y capacitación de las personas servidoras \n públicas e integrantes de los sujetos obligados en materia de transparencia y acceso a la información \n pública; \n X. Emitir acuerdos y resoluciones generales para el funciona miento del Sistema Nacional; \n XI. Aprobar, promover, evaluar y modificar la política nacional en materia de transparencia y acceso a la \n información pública; \n XII. Promover el ejercicio del derecho de acceso a la información pública en toda la República mexic ana; \n XIII. Promover la coordinación efectiva de las instancias que integran el Sistema Nacional y dar \n seguimiento a las acciones que para tal efecto se establezcan; \n XIV. Emitir los acuerdos que autoricen y legitimen a la Autoridad garante federal para reso lver los recursos \n de inconformidad que interpongan las personas particulares en contra de las resoluciones emitidas por \n las Autoridades garantes locales distintas a las señaladas en el artículo 163 de esta Ley; \n XV. Emitir las reglas de operación y funciona miento del Sistema Nacional, y \n XVI. Las demás que se desprendan de esta Ley y demás disposiciones jurídicas aplicables. \n Capítulo II \n Del Consejo Nacional","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Sistema Nacional","seccion_nombre":null,"orden":25},{"id":"8e4de1df-49c6-4040-81eb-3ebbd067c6e2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 26.","contenido":"El Consejo Nacional estará integrado por las personas titulares de: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 9 de 64 \n I. La Secretaría Antic orrupción y Buen Gobierno, quien lo presidirá; \n II. La Agencia de Transformación Digital y Telecomunicaciones; \n III. El Archivo General de la Nación; \n IV. El Centro Federal de Conciliación y Registro Laboral; \n V. El Tribunal Federal de Conciliación y Arbitraje ; \n VI. El Instituto Nacional Electoral, y \n VII. La presidencia de cada Comité de los Subsistemas de Transparencia a que se refiere el artículo 32 de \n la presente Ley. \n Las personas integrantes a que se refieren las fracciones I a VI del párrafo anterior, podrá n ser suplidas en sus \n ausencias por la persona servidora pública que al efecto designen, quien deberá tener el nivel jerárquico mínimo de \n Dirección General o equivalente. \n Las personas integrantes del Consejo Nacional contarán con voz y voto, y ejercerán su s cargos a título honorífico, \n por lo que no recibirán retribución, emolumento, ni compensación por su participación.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Consejo Nacional","seccion_nombre":null,"orden":26},{"id":"15e8ca64-cfce-406b-b378-9faff070b4ae","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 27.","contenido":"El Consejo Nacional podrá invitar, por la naturaleza de los asuntos a tratar, a las personas, \n instituciones, representantes de los sujetos obligados y de la sociedad para el desahogo de las reuniones del mismo. \n En todo caso, los sujetos obligados tendrán la potestad de solicitar ser invitados a estas reuniones.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Consejo Nacional","seccion_nombre":null,"orden":27},{"id":"56845a88-dd6d-41b4-b024-14ae66da0fc0","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 28.","contenido":"El Consejo Nacional se reunirá por lo menos cada seis me ses, previa convocatoria de la persona \n titular de la Presidencia o de la persona Secretaria Ejecutiva a indicación de esta, la que deberá ir acompañada del \n orden del día y de la documentación correspondiente. \n El Consejo Nacional sesionará válidamente con l a asistencia de por lo menos la mitad más uno de sus \n integrantes. Los acuerdos se tomarán por la mayoría de votos de los integrantes presentes, teniendo la persona \n titular de la Presidencia voto de calidad en caso de empate. \n Corresponde a la persona titula r de la Presidencia del Consejo Nacional, la facultad de promover en todo tiempo \n la efectiva coordinación y funcionamiento del Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Consejo Nacional","seccion_nombre":null,"orden":28},{"id":"78a1bd98-83ce-42f3-ae01-eedfbe399c86","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 29.","contenido":"En el desarrollo de los criterios a que se refiere el artículo 25, fracción IV, de esta Ley partic iparán \n los integrantes del Consejo Nacional, así como un representante del Consejo Nacional de Armonización Contable, \n previsto en el artículo 6 de la Ley General de Contabilidad Gubernamental, quien tendrá derecho a voz y podrá \n presentar observaciones por escrito a dichos criterios, las cuales no tendrán carácter obligatorio. Una vez que el \n Consejo Nacional apruebe los criterios, estos serán obligatorios para todos los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Consejo Nacional","seccion_nombre":null,"orden":29},{"id":"7e6ac207-9cf8-457d-8e3e-d7cde4496aba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 30.","contenido":"El Consejo Nacional contará con una Secretaría Ejecutiva designada por la persona titular de la \n Autoridad garante federal, que contará con las siguientes atribuciones: \n I. Dar seguimiento a los acuerdos y resoluciones del Sistema Nacional; \n II. Verificar el cumplimiento de los programas, estrategias, acciones, pol íticas y servicios que se adopten \n por el Sistema Nacional; \n III. Elaborar y publicar informes de actividades del Sistema Nacional; \n IV. Colaborar con los integrantes del Sistema Nacional, para fortalecer y garantizar la eficiencia de los \n mecanismos de coordi nación, y \n V. Las demás que le encomiende la persona titular de la Presidencia del Consejo Nacional. \n Capítulo III \n De los Subsistemas de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Del Consejo Nacional","seccion_nombre":null,"orden":30},{"id":"b655cd17-0aa0-45d9-ae75-a3fea16ed6ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 31.","contenido":"El Sistema Nacional contará con un Subsistema de Transparencia por cada entidad federativa, qu e \n funcionará por conducto de su respectivo Comité. \n Los Subsistemas de Transparencia tendrán las siguientes funciones: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 10 de 64 \n I. Dar a conocer al Consejo Nacional, a través de su Presidencia, las opiniones que tuvieren sobre el \n proyecto de política nacional en mat eria de transparencia y acceso a la información pública; \n II. Apoyar en la supervisión de la ejecución de la política nacional en materia de transparencia y acceso a \n la información pública; \n III. Presentar al Consejo Nacional un informe anual sobre sus activ idades; \n IV. Impulsar acciones de coordinación entre sus integrantes que promuevan el cumplimiento de \n obligaciones en materia de transparencia y acceso a la información pública; \n V. Opinar respecto de los demás asuntos que someta a su consideración el Consej o Nacional, y \n VI. Las demás que le confiera el Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De los Subsistemas de Transparencia","seccion_nombre":null,"orden":31},{"id":"b144f131-9863-4693-bec2-013a34ccc31e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 32.","contenido":"El Comité de cada Subsistema de Transparencia se integrará con una persona representante de los \n órganos encargados de la contraloría u homólogos de la entidad federativa de: \n I. E l poder ejecutivo, quien lo presidirá; \n II. El poder legislativo; \n III. El poder judicial, y \n IV. Cada uno de los órganos constitucionales autónomos. \n El Comité de cada Subsistema de Transparencia también tendrá como integrantes a los representantes de \n municip ios de la entidad federativa o demarcaciones territoriales de la Ciudad de México que se determine en la \n legislación local que corresponda. \n Las personas integrantes del Comité de cada Subsistema de Transparencia, podrán ser suplidas en sus \n ausencias por la persona servidora pública que al efecto designen, quienes deberán tener el nivel jerárquico \n inmediato inferior al de ellas. \n Las personas integrantes del Comité de cada Subsistema de Transparencia contarán con voz y voto, y ejercerán \n sus cargos a título ho norífico, por lo que no recibirán retribución, emolumento, ni compensación por su participación. \n Las decisiones del Comité de cada Subsistema de Transparencia se tomarán por mayoría de sus integrantes \n presentes. En caso de empate la persona que lo preside tendrá voto de calidad.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De los Subsistemas de Transparencia","seccion_nombre":null,"orden":32},{"id":"2b8d3b91-ea74-40d9-8d90-09e5e1840489","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 33.","contenido":"El Comité de cada Subsistema de Transparencia podrá invitar, por la naturaleza de los asuntos a \n tratar, a las personas, instituciones, representantes de los sujetos obligados y de la sociedad para el desahogo de las \n reu niones del mismo. En todo caso, los sujetos obligados tendrán la potestad de solicitar ser invitados a estas \n reuniones. \n Capítulo IV \n De las Autoridades garantes","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De los Subsistemas de Transparencia","seccion_nombre":null,"orden":33},{"id":"cb810fc2-dfd0-487f-9d3b-5f77af51232c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 34.","contenido":"Las Autoridades garantes serán responsables de garantizar, en el ámbito de su compe tencia, el \n ejercicio de los derechos de acceso a la información pública y la protección de datos personales, conforme a los \n principios y bases establecidos por el artículo 6o. de la Constitución Política de los Estados Unidos Mexicanos, así \n como por lo pre visto en esta Ley y demás disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Autoridades garantes","seccion_nombre":null,"orden":34},{"id":"c2c7547f-d11b-46c7-9e11-0ac9a0264868","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 35.","contenido":"Las Autoridades garantes tendrán las atribuciones siguientes: \n I. Interpretar, en el ámbito de sus atribuciones, los ordenamientos que les resulten aplicables, derivados \n de esta Ley y de la Constitución Política de los Estados Unidos Mexicanos; \n II. Conocer y resolver los recursos de revisión interpuestos por las personas particulares en contra de las \n resoluciones de los sujetos obligados en sus respectivos ámbitos de competencia, en t érminos de lo \n dispuesto en el Capítulo I del Título Octavo de la presente Ley; \n III. Imponer las medidas de apremio y sanciones, según corresponda, de conformidad con lo previsto en \n la presente Ley y demás disposiciones que deriven de la misma; \n IV. Promover y difundir el ejercicio de los derechos de acceso a la información, de conformidad con la \n política nacional en materia de transparencia y acceso a la información pública y las disposiciones \n jurídicas aplicables en la materia; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 11 de 64 \n V. Fomentar la cultura de la transparencia en el sistema educativo; \n VI. Brindar capacitación a las personas servidoras públicas y apoyo técnico a los sujetos obligados en \n materia de transparencia y acceso a la información; \n VII. Establecer políticas de transparencia con sentido social, atendiendo a las condiciones económicas, \n sociales y culturales; \n VIII. Suscribir convenios con los sujetos obligados que propicien la publicación de información en el marco \n de las políticas de transparencia con sentido social; \n IX. Suscribir convenios de co laboración con las personas particulares o con sectores de la sociedad \n cuando sus actividades o productos sean de interés público o de relevancia social; \n X. Suscribir convenios de colaboración con otras Autoridades garantes para el cumplimiento de sus \n atri buciones y promover mejores prácticas en la materia; \n XI. Promover la igualdad sustantiva; \n XII. Coordinarse con las autoridades competentes para que, en los procedimientos de acceso a la \n información y en los medios de impugnación, se contemple contar con la información en lenguas \n indígenas y en formatos accesibles para que sean sustanciados y atendidos en la misma lengua y en \n su caso, se promuevan los ajustes razonables necesarios si se tratara de personas con discapacidad; \n XIII. Garantizar condiciones de ac cesibilidad para que los grupos de atención prioritaria puedan ejercer su \n derecho de acceso a la información pública en igualdad de circunstancias; \n XIV. Informar a la instancia competente sobre la probable responsabilidad de los sujetos obligados que \n incum plan las obligaciones previstas en la presente Ley y en las demás disposiciones aplicables; \n XV. Promover la participación y colaboración con organismos internacionales, en el análisis y mejores \n prácticas en materia de acceso a la información pública; \n XVI. Fomentar los principios de transparencia, rendición de cuentas, participación ciudadana, accesibilidad \n e innovación tecnológica; \n XVII. Emitir recomendaciones a los sujetos obligados, con el propósito de diseñar, implementar y evaluar \n acciones de apertura g ubernamental que permitan orientar las políticas internas en la materia; \n XVIII. Promover la digitalización de la información pública en posesión de los sujetos obligados y la \n utilización de las tecnologías de información y comunicación, conforme a las polí ticas que establezca \n el Sistema Nacional, y \n XIX. Las demás atribuciones que les confiera esta Ley y otras disposiciones aplicables.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Autoridades garantes","seccion_nombre":null,"orden":35},{"id":"ffd70d10-e90c-4cc6-9732-0fb99bb504c5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 36.","contenido":"Las Autoridades garantes para el ejercicio y desempeño de las atribuciones que les otorga la \n presente Ley, tend rán la naturaleza jurídica, adscripción y estructura administrativa que se establezca en sus \n respectivos reglamentos interiores o análogos o acuerdos de carácter general, en el ámbito de sus respectivas \n competencias. \n Las Autoridades garantes locales podrán prever que su estructura será similar a la de la Autoridad garante federal \n en sus respectivas leyes.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Autoridades garantes","seccion_nombre":null,"orden":36},{"id":"46b3aadb-2b50-4447-8334-ec3b58791f90","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 37.","contenido":"La Autoridad garante federal, además de lo señalado en el artículo 35 de la presente Ley, tendrá las \n siguientes atribuciones: \n I. Conocer y re solver los recursos de inconformidad que interpongan las personas particulares en contra \n de las resoluciones emitidas por las Autoridades garantes locales cuando las mismas se encuentren \n vinculadas con recursos públicos federales; \n II. Encabezar y coordinar el Sistema Nacional, y \n III. Las demás que le confiera el Sistema Nacional por conducto del Consejo Nacional, esta Ley y otras \n disposiciones en la materia. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 12 de 64","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Autoridades garantes","seccion_nombre":null,"orden":37},{"id":"a7ca4010-9b2c-4368-9ae7-e908fe373de8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 38.","contenido":"La persona titular de la Autoridad garante federal será nombrada por la persona titular del Ejecutivo \n Federal. \n Capítulo V \n De los Comités de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Autoridades garantes","seccion_nombre":null,"orden":38},{"id":"0e9ba5cf-f80f-42f0-b9b9-8553bc43c0dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 39.","contenido":"En cada sujeto obligado se integrará un Comité de Transparencia colegiado e integrado por un \n número impar. \n El Comité de Transparencia adoptará sus resoluciones por mayoría de v otos, en caso de empate, quien presida \n el Comité tendrá voto de calidad. A sus sesiones podrán asistir como personas invitadas, aquéllas que sus \n integrantes consideren necesarias, quienes tendrán voz, pero no voto. \n Quienes integren el Comité de Transparenc ia no podrán depender jerárquicamente entre sí, tampoco podrán \n reunirse dos o más integrantes en una sola persona. Cuando se presente el caso, la persona titular del sujeto \n obligado tendrá que nombrar a la persona que supla al subordinado. Quienes integren los Comités de Transparencia \n contarán con suplentes cuya designación se realizará de conformidad con la normatividad interna de los respectivos \n sujetos obligados, y deberán corresponder a personas que ocupen cargos de la jerarquía inmediata inferior a la de \n las personas integrantes propietarias. \n En el caso de la Administración Pública Federal, los Comités de Transparencia de las dependencias y entidades, \n estarán conformados por: \n I. La persona responsable del área coordinadora de archivos o equivalente; \n II. La persona responsable de la Unidad de Transparencia, y \n III. La persona titular del Órgano Interno de Control u homólogo. \n Las personas integrantes del Comité de Transparencia tendrán acceso a la información para determinar su \n clasificación, conforme a las disposiciones jurídicas emitidas por los sujetos obligados para el resguardo o \n salvaguarda de la información. \n El Sistema Nacional de Investigación e Inteligencia en materia de Seguridad Pública, el Centro Nacional de \n Inteligencia, el Centro Federal de Pro tección a Personas, las Divisiones de Inteligencia e Investigación de la Policía \n Federal Ministerial y Guardia Nacional, la Agencia de Investigación Criminal, el Centro Federal de Investigación \n Criminal, la Fiscalía Especializada en materia de Delincuencia Organizada, la Unidad de Inteligencia Financiera, el \n Estado Mayor de la Defensa Nacional, el Estado Mayor General de la Armada, o bien las unidades administrativas \n que los sustituyan, no estarán sujetos a la autoridad de los Comités de Transparencia a que se refiere este artículo. \n Las funciones correspondientes serán responsabilidad exclusiva de la persona titular de la entidad o unidad \n administrativa. \n La clasificación, desclasificación y acceso a la información que generan o custodian las instancias de in teligencia \n e investigación deberán apegarse a los términos previstos en la presente Ley y a los protocolos de seguridad y \n resguardo establecidos para ello.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De los Comités de Transparencia","seccion_nombre":null,"orden":39},{"id":"e91fc27d-be52-4942-aaf1-4f0125f68d44","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 40.","contenido":"Cada Comité de Transparencia tendrá las siguientes atribuciones: \n I. Instituir, coordina r y supervisar las acciones y procedimientos para asegurar la mayor eficacia en la \n gestión de las solicitudes en materia de acceso a la información, en términos de las disposiciones \n aplicables; \n II. Confirmar, modificar o revocar las determinaciones en mate ria de ampliación del plazo de respuesta, \n clasificación de la información y declaración de inexistencia o incompetencia, que sean adoptadas por \n las personas titulares de las Áreas correspondientes de los sujetos obligados; \n III. Ordenar, en su caso, a las á reas competentes que generen la información que derivado de sus \n facultades, competencias y funciones deban tener en posesión o que previa acreditación de la \n imposibilidad de su generación, exponga, de forma fundada y motivada, las razones por las cuales, e n \n el caso particular, no ejercieron dichas facultades, competencias o funciones; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 13 de 64 \n IV. Establecer políticas para facilitar la obtención de información y el ejercicio del derecho de acceso a la \n información; \n V. Promover y establecer programas de capacitación e n materia de transparencia, acceso a la \n información y accesibilidad para todas las personas servidoras públicas o integrantes del sujeto \n obligado; \n VI. Recabar y enviar a las Autoridades garantes los datos necesarios para la elaboración del informe \n anual, c onforme a los lineamientos que dichas autoridades expidan; \n VII. Solicitar y autorizar la ampliación del plazo de reserva de la información, conforme a lo dispuesto en el \n artículo 104 de la presente Ley, y \n VIII. Las demás que se desprendan de las disposicio nes jurídicas aplicables. \n Capítulo VI \n De las Unidades de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De los Comités de Transparencia","seccion_nombre":null,"orden":40},{"id":"790dfadf-73e5-4db7-b2c8-b635858bbf08","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 41.","contenido":"Los sujetos obligados designarán a la persona responsable de la Unidad de Transparencia, quien \n tendrá las siguientes atribuciones: \n I. Recabar y difundir la información prev ista en los Capítulos II, III, IV y V del Título Quinto de esta Ley, y \n propiciar que las áreas la actualicen periódicamente, conforme las disposiciones jurídicas aplicables; \n II. Recibir y dar trámite a las solicitudes de acceso a la información; \n III. Auxil iar a las personas particulares en la elaboración de solicitudes de acceso a la información y, en su \n caso, orientarles sobre los sujetos obligados competentes conforme a las disposiciones jurídicas \n aplicables; \n IV. Realizar los trámites internos necesarios para la atención de las solicitudes de acceso a la información; \n V. Efectuar las notificaciones a las personas solicitantes; \n VI. Proponer al Comité de Transparencia los procedimientos internos que aseguren la mayor eficiencia en \n la gestión de las solicitude s de acceso a la información, conforme a las disposiciones jurídicas \n aplicables; \n VII. Proponer personal habilitado que sea necesario para recibir y dar trámite a las solicitudes de acceso a \n la información; \n VIII. Llevar un registro de las solicitudes de acc eso a la información, respuestas, resultados, costos de \n reproducción y envío; \n IX. Promover e implementar políticas de transparencia con sentido social procurando su accesibilidad; \n X. Fomentar la transparencia y accesibilidad al interior del sujeto obligado ; \n XI. Hacer del conocimiento de la instancia competente la probable responsabilidad por el incumplimiento \n de las obligaciones previstas en la presente Ley y en las demás disposiciones aplicables, y \n XII. Las demás que se desprendan de las disposiciones jurí dicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":41},{"id":"34eaabd8-8d8e-4d7f-a987-ec0aed6b4d48","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 42.","contenido":"En caso que alguna área de los sujetos obligados se negara a colaborar con la Unidad de \n Transparencia, esta informará a su superior jerárquico para que le ordene realizar sin demora las acciones \n conducentes. \n Si persiste la ne gativa de colaboración, la Unidad de Transparencia lo hará del conocimiento de la autoridad \n competente, quien podrá iniciar el procedimiento de responsabilidad respectivo.","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":42},{"id":"6737986c-f66a-43ad-98d7-38941870dc3e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 43.","contenido":"Las oficinas que ocupen las Unidades de Transparencia se deben ubicar e n lugares visibles al \n público en general y ser de fácil acceso. \n Las Unidades de Transparencia deben contar con las condiciones mínimas de operación que aseguren el \n cumplimiento de sus funciones. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 14 de 64 \n Los sujetos obligados deberán capacitar al personal que integ ra las Unidades de Transparencia, de conformidad \n con los lineamientos que para dicho efecto emita el Sistema Nacional. \n TÍTULO TERCERO \n PLATAFORMA NACIONAL DE TRANSPARENCIA \n Capítulo Único \n De la Plataforma Nacional de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":43},{"id":"68dab437-bf45-4a1a-b79b-a5bb1762beb4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   44.","contenido":"La Secretaría Anticorrupción y Buen Gobierno administrará, implementará y pondrá en \n funcionamiento la Plataforma Nacional que permita cumplir con los procedimientos, obligaciones y disposiciones \n señaladas en la presente Ley para los sujetos obligados y Autoridades garan tes atendiendo a las necesidades de \n accesibilidad de las personas usuarias, así como en otras disposiciones jurídicas.","tipo_articulo":"ordinario","titulo_nombre":"PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":44},{"id":"4bf87553-664a-44a9-a01a-bb3c9febe879","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 45.","contenido":"La Plataforma Nacional contará con los módulos siguientes: \n I. Solicitudes de acceso a la información; \n II. Gestión de medios de impugnación; \n III. Portales de obligaciones de transparencia; \n IV. Comunicación entre las Autoridades garantes y sujetos obligados, y \n V. Cualquier otro que determine el Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":45},{"id":"c295a168-6b2e-4f6f-b3c0-bb3ae4aa033a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 46.","contenido":"El Sistema Nacional establecerá las medidas necesarias para garantizar la estabilidad y seguridad \n de la Plataforma Nacional, promoviendo la homologación de procesos y la simplicidad del uso de los sistemas por \n parte de las personas usuarias. \n TÍTULO CUARTO \n CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL \n Capít ulo I \n De la Promoción de la Transparencia y el Derecho de Acceso a la Información","tipo_articulo":"ordinario","titulo_nombre":"PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":46},{"id":"37281b68-a09f-4258-8659-2207faa2c685","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 47.","contenido":"Los sujetos obligados en coordinación con las Autoridades garantes deberán capacitar y actualizar \n de forma permanente, a todas sus personas servidoras públicas e n materia del derecho de acceso a la información, \n a través de los medios que se considere pertinentes. \n Con el objeto de crear una cultura de la transparencia y acceso a la información entre las personas habitantes de \n los Estados Unidos Mexicanos, las Autor idades garantes podrán promover, en colaboración con instituciones \n educativas y culturales del sector público o privado, actividades, mesas de trabajo, exposiciones y concursos \n relativos a la transparencia y acceso a la información.","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":47},{"id":"cee7f361-e19b-4688-858a-bd29c6b93207","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 48.","contenido":"Las Autori dades garantes, en el ámbito de sus respectivas competencias o a través de los \n mecanismos de coordinación que al efecto establezcan, podrán: \n I. Proponer, a las autoridades educativas competentes que incluyan contenidos sobre la importancia \n social del derec ho de acceso a la información en los planes y programas de estudio de educación \n preescolar, primaria, secundaria, normal y para la formación de maestros de educación básica en sus \n respectivas jurisdicciones; \n II. Promover, entre las instituciones públicas y privadas de educación media superior y superior, la \n inclusión, dentro de sus programas de estudio, actividades académicas curriculares y extracurriculares, \n de temas que ponderen la importancia social del derecho de acceso a la información y rendición de \n c uentas; \n III. Promover, que en las bibliotecas y entidades especializadas en materia de archivos se prevea la \n instalación de módulos de información pública, que faciliten el ejercicio del derecho de acceso a la \n información y la consulta de la información de rivada de las obligaciones de transparencia a que se \n refiere esta Ley; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 15 de 64 \n IV. Proponer, entre las instituciones públicas y privadas de educación superior, la creación de centros de \n investigación, difusión y docencia sobre transparencia, derecho de acceso a la información y rendición \n de cuentas; \n V. Establecer, entre las instituciones públicas de educación, acuerdos para la elaboración y publicación \n de materiales que fomenten la cultura del derecho de acceso a la información y rendición de cuentas; \n VI. Promover, en coordinación con autoridades federales, estatales y municipales o de las demarcaciones \n territoriales de la Ciudad de México, la participación ciudadana y de organizaciones sociales en \n talleres, seminarios y actividades que tengan por objeto la difusión de los temas de transparencia y \n derecho de acceso a la información; \n VII. Desarrollar, programas de formación de personas usuarias de este derecho para incrementar su \n ejercicio y aprovechamiento, privilegiando a integrantes de grupos de atención prioritari a; \n VIII. Impulsar, estrategias que pongan al alcance de los diversos sectores de la sociedad los medios para el \n ejercicio del derecho de acceso a la información, acordes a su contexto sociocultural, y \n IX. Desarrollar, con el concurso de centros comunitario s digitales y bibliotecas públicas, universitarias, \n gubernamentales y especializadas, programas para la asesoría y orientación de sus personas usuarias \n en el ejercicio y aprovechamiento del derecho de acceso a la información.","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":48},{"id":"ca33a692-8dbb-430c-9812-09376bc99bd5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 49.","contenido":"Para el cumplimie nto de las obligaciones previstas en la presente Ley, los sujetos obligados podrán \n desarrollar o adoptar, en lo individual o en acuerdo con otros sujetos obligados, esquemas de mejores prácticas que \n tengan por objeto: \n I. Elevar el nivel de cumplimiento de las disposiciones previstas en la presente Ley; \n II. Armonizar el acceso a la información por sectores; \n III. Facilitar el ejercicio del derecho de acceso a la información a las personas, y \n IV. Procurar la accesibilidad de la información. \n Capítulo II \n De la T ransparencia con Sentido Social","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De las Unidades de Transparencia","seccion_nombre":null,"orden":49},{"id":"388f7524-69ed-4653-84c3-e6373716a59e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 50.","contenido":"Las Autoridades garantes emitirán políticas de transparencia con sentido social, en atención a los \n lineamientos generales definidos para ello por el Sistema Nacional, diseñadas para incentivar a los sujetos obli gados \n a publicar información de utilidad sobre temas prioritarios. Dichas políticas tendrán por objeto, entre otros, promover \n la reutilización y aprovechamiento de la información que generan los sujetos obligados, considerando la demanda de \n la sociedad, id entificada con base en las metodologías previamente establecidas.","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De la T ransparencia con Sentido Social","seccion_nombre":null,"orden":50},{"id":"9a874663-da58-4c60-9050-8bf0ec25b449","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 51.","contenido":"La información publicada por los sujetos obligados, en el marco de la política de transparencia con \n sentido social, se difundirá en los medios y formatos que más convengan al pú blico al que va dirigida.","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De la T ransparencia con Sentido Social","seccion_nombre":null,"orden":51},{"id":"c8d0700f-9f18-446a-af46-7815d41b8c97","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 52.","contenido":"El Sistema Nacional emitirá los criterios para evaluar la efectividad de la política de la transparencia \n con sentido social, considerando como base, la reutilización y aprovechamiento que la sociedad haga a la \n informa ción. \n La información que se publique, como resultado de las políticas de transparencia, deberá permitir la generación \n de conocimiento público útil, para disminuir asimetrías de la información, mejorar los accesos a trámites y servicios, \n optimizar la toma d e decisiones de autoridades o cualquier persona y deberá tener un objeto claro enfocado en las \n necesidades de sectores de la sociedad determinados o determinables. \n Capítulo III \n De la Apertura Institucional \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 16 de 64","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De la T ransparencia con Sentido Social","seccion_nombre":null,"orden":52},{"id":"ccf2b23c-4855-4c70-a9bb-3ac71b1bc0a9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 53.","contenido":"Las Autoridades garantes, en el ámbit o de sus atribuciones, coadyuvarán con los sujetos obligados y \n representantes de la sociedad civil en la construcción e implementación de mecanismos de colaboración para la \n promoción e implementación de políticas y mecanismos de apertura institucional. \n Art ículo 54. Los sujetos obligados, en el ámbito de su competencia, en materia de apertura deben: \n I. Garantizar el ejercicio y cumplimiento de los principios de transparencia con sentido social, la \n participación ciudadana, la rendición de cuentas, la innovaci ón y el aprovechamiento de la tecnología \n que privilegie su diseño centrado en el usuario; \n II. Implementar tecnología y datos abiertos incluyendo, en la digitalización de información relativa a \n servicios públicos, trámites y demás componentes del actuar gub ernamental, la publicidad de datos de \n interés para la población, principalmente de manera automática y sin incremento de la carga \n administrativa, de conformidad con su disponibilidad presupuestaria, y \n III. Procurar mecanismos que fortalezcan la participaci ón y la colaboración de las personas particulares en \n asuntos económicos, sociales, culturales y políticos de la Nación.","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De la T ransparencia con Sentido Social","seccion_nombre":null,"orden":53},{"id":"30417a7b-95dd-4a77-8562-6d1cc406eadd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 55.","contenido":"Las dependencias y entidades de la Administración Pública Federal deberán realizar acciones en \n materia de datos abiertos y gobierno abierto conforme a los lineamientos que al efecto emita la Agencia de \n Transformación Digital y Telecomunicaciones. \n TÍTULO QUINTO \n OBLIGACIONES DE TRANSPARENCIA \n Capítulo I \n De las Obligaciones Generales","tipo_articulo":"ordinario","titulo_nombre":"CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL Capít ulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","capitulo_nombre":"De la T ransparencia con Sentido Social","seccion_nombre":null,"orden":54},{"id":"b22119d4-d2c9-45ed-aab5-403ea0d773c4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 56.","contenido":"Los sujetos obligados deberán cump lir con las obligaciones de transparencia y poner a disposición \n del público y mantener actualizada, en los respectivos medios electrónicos, de acuerdo con sus facultades, \n atribuciones, funciones u objeto social, según corresponda, la información, por lo me nos, de los temas, documentos y \n políticas e información señalados en este Título. \n Aquella información particular de la referida en este Título que se ubique en alguno de los supuestos de \n clasificación señalados en los artículos 110 y 113 de la presente Ley , no será objeto de la publicación a que se \n refiere este mismo artículo, salvo que pueda ser elaborada una versión pública. En todo caso se aplicará la prueba \n de daño a que se refiere el artículo 107 de la presente Ley. \n En sus resoluciones las Autoridades garantes podrán señalar a los sujetos obligados que la información que \n deben proporcionar sea considerada como obligación de transparencia de conformidad con este Título, atendiendo a \n la relevancia de la información, la incidencia de las solicitudes sobre la misma y el sentido reiterativo de las \n resoluciones.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":55},{"id":"749bfca2-4241-4ccb-93ad-6b3e880d093f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 57.","contenido":"Los lineamientos que emita el Sistema Nacional establecerán los formatos de publicación de la \n información para asegurar que la información sea veraz, confiable, oportuna, congruente, integ ral, actualizada, \n accesible, comprensible, verificable. \n Los lineamientos a que se refiere el párrafo anterior procurarán la homologación en la presentación de la \n información a la que hace referencia este Título por parte de los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":56},{"id":"058f158e-715b-4a50-9831-b29df8284380","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   58.","contenido":"La información correspondiente a las obligaciones de transparencia deberá actualizarse por lo \n menos cada tres meses, salvo que en la presente Ley se establezca un plazo diverso. El Sistema Nacional emitirá \n los criterios para determinar el plazo mínimo que deberá permanecer disponible y accesible la información, \n atendiendo a las cualidades de la misma. \n La publicación de la información deberá indicar el sujeto obligado encargado de generarla, así como la fecha de \n su última actualización.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":57},{"id":"ffd3fcf4-b8c1-48fb-9087-a717e0745ad6","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   59.","contenido":"Las Autoridades garantes, de oficio o a petición de las personas particulares, verificarán el \n cumplimiento que los sujetos obligados den a las disposiciones previstas en este Título. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 17 de 64 \n Las denuncias presentadas por las personas particulares podrán realizarse en cualquier momento, de \n conformidad con el procedimiento señalado en la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":58},{"id":"e1558584-5cef-41de-8e28-e045e59ca1b5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 60.","contenido":"La página de inicio de los portales de Internet de los sujetos obligados tendrá un vínculo de acceso \n directo al sitio donde se encuentra la información pública a la que se refiere este Título, el cual deberá contar con un \n buscador. \n La información de obligaciones de transparencia deberá publicarse con perspectiva de género y discapacidad, \n cuando así corresponda a su naturaleza.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":59},{"id":"12cdd781-a160-42d5-812c-b690ddcfe200","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 61.","contenido":"Las Autoridades garant es y los sujetos obligados establecerán las medidas que faciliten el acceso y \n búsqueda de la información para personas con discapacidad y se procurará que la información publicada sea \n accesible de manera focalizada a personas que hablen alguna lengua indíg ena. \n Por lo que, por sí mismos o a través del Sistema Nacional, deberán promover y desarrollar de forma progresiva, \n políticas y programas tendientes a garantizar la accesibilidad de la información en la máxima medida posible. \n Se promoverá la homogeneidad y la estandarización de la información, a través de la emisión de lineamientos y \n de formatos por parte del Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":60},{"id":"91c5d5c3-d640-424c-9cff-e9b9c93ed346","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 62.","contenido":"Los sujetos obligados pondrán a disposición de las personas interesadas equipos de cómputo con \n acceso a Internet, que p ermitan a las personas particulares consultar la información o utilizar el sistema de \n solicitudes de acceso a la información en las oficinas de las Unidades de Transparencia. Lo anterior, sin perjuicio de \n que adicionalmente se utilicen medios alternativos de difusión de la información, cuando en determinadas \n poblaciones éstos resulten de más fácil acceso y comprensión.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":61},{"id":"a87b0879-b33a-4092-98a5-f3a35970870d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 63.","contenido":"La información publicada por los sujetos obligados, en términos del presente Título, no constituye \n propaganda gubernamental. Lo s sujetos obligados, incluso dentro de los procesos electorales, a partir del inicio de \n las precampañas y hasta la conclusión del proceso electoral, deberán mantener accesible la información en el portal \n de obligaciones de transparencia, salvo disposición expresa en contrario en las disposiciones jurídicas en materia \n electoral.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":62},{"id":"9e5172dd-4602-4070-b124-00c95d1a4e3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 64.","contenido":"Los sujetos obligados y las personas particulares serán responsables de los datos personales en su \n posesión de conformidad con las disposiciones jurídicas aplicables en la materia. \n Los sujetos obligados no podrán difundir, distribuir o comercializar los datos personales contenidos en los \n sistemas de información, desarrollados en el ejercicio de sus funciones, salvo que haya mediado el consentimiento \n expreso, por escrito o por un medio de autenticación similar, de las personas a que haga referencia la información de \n acuerdo a las disposiciones jurídicas aplicables. Lo anterior, sin perjuicio a lo establecido por el artículo 119 de esta \n Ley. \n Capítulo II \n De las Obligaciones d e Transparencia Comunes","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Generales","seccion_nombre":null,"orden":63},{"id":"a38a0b6d-54b2-4908-83dc-c8af6781a8c7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   65.","contenido":"Los sujetos obligados pondrán a disposición del público y mantendrán actualizada, en los \n respectivos medios electrónicos, de acuerdo con sus facultades, atribuciones, funciones u objeto social, según \n corresponda, la inf ormación, por lo menos, de los temas, documentos y políticas que a continuación se señalan: \n I. El marco normativo aplicable al sujeto obligado, en el que deberá incluirse leyes, códigos, \n reglamentos, decretos de creación, manuales administrativos, reglas d e operación, criterios, políticas, \n entre otros; \n II. Su estructura orgánica completa, en un formato que permita vincular cada parte de la estructura, las \n atribuciones y responsabilidades que le corresponden a cada persona servidora pública y/o persona \n prest adora de servicios profesionales miembro de los sujetos obligados, de conformidad con las \n disposiciones aplicables; \n III. Las facultades de cada área; \n IV. Las metas y objetivos de las áreas de conformidad con sus programas operativos; \n V. Los indicadores rel acionados con temas de interés público o trascendencia social que, conforme a sus \n funciones, deban establecer, así como los que permitan rendir cuenta de sus objetivos y resultados; \n VI. El directorio de todas las personas servidoras públicas, a partir del nivel de jefe de departamento o su \n equivalente, o de menor nivel, cuando se brinde atención al público; manejen o apliquen recursos \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 18 de 64 \n públicos; realicen actos de autoridad o presten servicios profesionales bajo el régimen de confianza u \n honorarios y personal de base. El directorio deberá incluir, al menos el nombre, cargo o nombramiento \n asignado, nivel del puesto en la estructura orgánica, fecha de alta en el cargo, número telefónico, \n domicilio para recibir correspondencia y dirección de correo electrónico of iciales; \n VII. La remuneración bruta y neta de todas las personas servidoras públicas de base o de confianza, de \n todas las percepciones, incluyendo sueldos, prestaciones, gratificaciones, primas, comisiones, dietas, \n bonos, estímulos, ingresos y sistemas de compensación, señalando la periodicidad de dicha \n remuneración; \n VIII. Los gastos de representación y viáticos, así como el objeto e informe de comisión correspondiente; \n IX. El número total de las plazas y del personal de base y confianza, especificando el t otal de las \n vacantes, por nivel de puesto, para cada unidad administrativa; \n X. Las contrataciones de servicios profesionales por honorarios, señalando los nombres de las personas \n prestadoras de servicios, los servicios contratados, el monto de los honorari os y el periodo de \n contratación; \n XI. La versión pública de las declaraciones patrimoniales de las personas servidoras públicas en términos \n de las disposiciones jurídicas aplicables, en los sistemas habilitados para ello; \n XII. El domicilio de la Unidad de T ransparencia, además de la dirección electrónica donde podrán recibirse \n las solicitudes para obtener la información; \n XIII. Las convocatorias a concursos para ocupar cargos públicos y los resultados de los mismos, en los \n sistemas habilitados para ello, de c onformidad con las disposiciones jurídicas aplicables; \n XIV. Los programas, subsidios, estímulos y apoyos, en el que se deberá informar respecto de los \n programas de transferencia, de servicios, de infraestructura social y de subsidio, en los que se deberá \n c ontener lo siguiente: \n a ) Área; \n b ) Denominación del programa; \n c ) Periodo de vigencia; \n d ) Diseño, objetivos y alcances; \n e ) Metas físicas; \n f ) Población beneficiada estimada; \n g ) Monto aprobado, modificado y ejercido, así como los calendarios de su programación \n presupuestal; \n h ) Requisitos y procedimientos de acceso; \n i ) Procedimiento de queja o inconformidad ciudadana; \n j ) Mecanismos de exigibilidad; \n k ) Mecanismos de evaluación, informes de evaluación y seguimiento de recomendaciones; \n l ) Indicadores con nombre, de finición, método de cálculo, unidad de medida, dimensión, frecuencia \n de medición, nombre de las bases de datos utilizadas para su cálculo; \n m ) Formas de participación social; \n n ) Articulación con otros programas sociales; \n o ) Vínculo a las reglas de operación o documento equivalente; \n p ) Informes periódicos sobre la ejecución y los resultados de las evaluaciones realizadas, y \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 19 de 64 \n q ) Padrón de personas beneficiarias mismo que deberá contener los siguientes datos: nombre de la \n persona física o denominación social de las personas morales beneficiarias, el monto, recurso, \n beneficio o apoyo otorgado para cada una de ellas, unidad territorial, en su caso, edad y sexo; \n XV. Las condiciones generales de trabajo, contratos o convenios que regulen las relaciones laborales del \n personal de base o de confianza, así como los recursos públicos económicos, en especie o donativos, \n que sean entregados a los sindicatos y ejerzan como recursos públicos; \n XVI. La información curricular, desde el nivel de jefatura de departamento o equivale nte, hasta la titularidad \n del sujeto obligado; \n XVII. El listado de personas servidoras públicas con sanciones administrativas firmes, especificando la \n causa de sanción y la disposición, de conformidad a lo establecido en las disposiciones jurídicas \n aplicab les; \n XVIII. Los servicios y trámites que ofrecen, incluyendo sus requisitos, en los sistemas habilitados para ello, \n de conformidad con las disposiciones jurídicas aplicables; \n XIX. La información financiera sobre el presupuesto asignado, así como los inform es del ejercicio trimestral \n del gasto, en términos de la Ley General de Contabilidad Gubernamental y demás disposiciones \n jurídicas aplicables; \n XX. La información relativa a la deuda pública, en términos de las disposiciones jurídicas aplicables; \n XXI. Los m ontos destinados a gastos relativos a comunicación social y publicidad oficial que permita \n identificar el tipo de medio, proveedores, número de contrato y concepto o campaña; \n XXII. Los informes de resultados de las auditorías al ejercicio presupuestal de c ada sujeto obligado que se \n realicen y, en su caso, las aclaraciones que correspondan; \n XXIII. El resultado de la dictaminación de los estados financieros; \n XXIV. Los montos, criterios, convocatorias y listado de personas físicas o morales a quienes, por cual quier \n motivo, se les asigne o permita usar recursos públicos o, en los términos de las disposiciones \n aplicables, realicen actos de autoridad. Asimismo, los informes que dichas personas les entreguen \n sobre el uso y destino de dichos recursos; \n XXV. Las conce siones, contratos, convenios, permisos, licencias o autorizaciones otorgados, especificando \n las personas titulares de aquéllos, debiendo publicarse su objeto, nombre o razón social de la persona \n titular, vigencia, tipo, términos, condiciones, monto y modif icaciones, así como si el procedimiento \n involucra el aprovechamiento de bienes, servicios y/o recursos públicos; \n XXVI. Los resultados de los procedimientos de adjudicación directa, invitación restringida y licitación de \n cualquier naturaleza, incluyendo la versión pública del Expediente respectivo y de los contratos \n celebrados, que deberá contener, por lo menos, lo siguiente: \n a ) De licitaciones públicas o procedimientos de invitación restringida: \n 1. La convocatoria o invitación emitida, así como los fundamen tos legales aplicados para \n llevarla a cabo; \n 2. Los nombres de las personas participantes o invitadas; \n 3. El nombre de la persona ganadora y las razones que lo justifican; \n 4. El Área solicitante y la responsable de su ejecución; \n 5. Las convocatorias e invit aciones emitidas; \n 6. Los dictámenes y fallo de adjudicación; \n 7. El contrato y, en su caso, sus anexos; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 20 de 64 \n 8. Los mecanismos de vigilancia y supervisión, incluyendo, en su caso, los estudios de \n impacto urbano y ambiental, según corresponda; \n 9. La partida presu puestal, de conformidad con el clasificador por objeto del gasto, en el caso \n de ser aplicable; \n 10. Origen de los recursos especificando si son federales, estatales o municipales, así como el \n tipo de fondo de participación o aportación respectiva; \n 11. Los c onvenios modificatorios que, en su caso, sean firmados, precisando el objeto y la \n fecha de celebración; \n 12. Los informes de avance físico y financiero sobre las obras o servicios contratados; \n 13. El convenio de terminación, y \n 14. El finiquito, y \n b ) De las adjudicaciones directas: \n 1. La propuesta enviada por el participante; \n 2. Los motivos y fundamentos legales aplicados para llevarla a cabo; \n 3. La autorización del ejercicio de la opción; \n 4. En su caso, las cotizaciones consideradas, especificando los nombre s de proveedores y los \n montos; \n 5. El nombre de la persona física o moral adjudicada; \n 6. La unidad administrativa solicitante y la responsable de su ejecución; \n 7. El número, fecha, el monto del contrato y el plazo de entrega o de ejecución de los servicios \n u obra; \n 8. Los mecanismos de vigilancia y supervisión, incluyendo, en su caso, los estudios de \n impacto urbano y ambiental, según corresponda; \n 9. Los informes de avance sobre las obras o servicios contratados; \n 10. El convenio de terminación, y \n 11. El finiqu ito; \n XXVII. Los informes que generen de conformidad con las disposiciones jurídicas; \n XXVIII. Las estadísticas que generen en cumplimiento de sus facultades, competencias o funciones; \n XXIX. Los informes de avances programáticos o presupuestales, balances ge nerales y su estado financiero; \n XXX. El Padrón de proveedores y contratistas en los sistemas habilitados para ello, de conformidad con las \n disposiciones jurídicas aplicables; \n XXXI. Los convenios de coordinación de concertación con los sectores social y pri vado; \n XXXII. El inventario de bienes muebles e inmuebles en posesión y propiedad; \n XXXIII. Las recomendaciones emitidas por los órganos públicos del Estado mexicano u organismos \n internacionales garantes de los derechos humanos, así como las acciones que han llevado a cabo \n para su atención; \n XXXIV. Las resoluciones que se emitan en procesos o procedimientos seguidos en forma de juicio; \n XXXV. Los mecanismos de participación ciudadana; \n XXXVI. Los programas que ofrecen, incluyendo información sobre la población, objetivo y destino, así como \n los trámites, tiempos de respuesta, requisitos y formatos para acceder a los mismos; \n XXXVII. Las actas y resoluciones del Comité de Transparencia de los sujetos obligados; \n XXXVIII. Las evaluaciones y encuestas que hagan los suj etos obligados a programas financiados con recursos \n públicos; \n XXXIX. Los estudios financiados con recursos públicos; \n XL. El listado de personas jubiladas y pensionadas, así como el monto que reciben; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 21 de 64 \n XLI. Los ingresos recibidos por cualquier concepto señal ando el nombre de las personas responsables de \n recibirlos, administrarlos y ejercerlos, así como su destino; \n XLII. Las donaciones hechas a terceros en dinero o en especie; \n XLIII. El catálogo de disposición y guía de archivo documental; \n XLIV. Las actas de s esiones ordinarias y extraordinarias, así como las opiniones y recomendaciones que, en \n su caso, emitan los consejos consultivos; \n XLV. El listado de solicitudes a las empresas concesionarias de telecomunicaciones y proveedores de \n servicios o aplicaciones de Internet para la intervención de comunicaciones privadas, el acceso al \n registro de comunicaciones y la localización geográfica en tiempo real de equipos de comunicación, \n que contenga exclusivamente el objeto, el alcance temporal y los fundamentos legales del \n requerimiento, así como, en su caso, la mención de que cuenta con la autorización judicial \n correspondiente, y \n XLVI. Cualquier otra información que sea de utilidad o se considere relevante, y la que se encuentre prevista \n en otras disposiciones jurídicas aplicables. \n Los sujetos obligados deberán informar a las Autoridades garantes de forma fundada y motivada cuáles son las \n fracciones de este artículo que les resultan aplicables, para efecto de que las Autoridades las validen. \n Una vez que cuenten con la va lidación de referencia los sujetos obligados procederán a publicarlas en la \n Plataforma Nacional. \n Capítulo III \n De las Obligaciones Específicas","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones d e Transparencia Comunes","seccion_nombre":null,"orden":64},{"id":"af482582-71dd-4a6f-af39-61f207d3980b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 66.","contenido":"Los sujetos obligados de los Poderes Ejecutivos Federal, de las entidades federativas y municipales \n o de las demarcaciones territoriales de la Ciudad de México, además de lo señalado en el artículo anterior, deberán \n poner a disposición del público y actualizar, conforme al ámbito de su competencia la información siguiente: \n I. El Plan Nacional de Desarroll o y los planes de desarrollo de las entidades federativas, según \n corresponda; \n II. El presupuesto de egresos y las fórmulas de distribución de los recursos otorgados; \n III. Las expropiaciones decretadas y ejecutadas, que incluya, cuando menos, la fecha de ex propiación, el \n domicilio y la causa de utilidad pública y las ocupaciones superficiales; \n IV. El nombre, denominación o razón social y clave del registro federal de contribuyentes a quienes se les \n hubiera cancelado o condonado algún crédito fiscal, así como los montos respectivos; \n V. Los nombres de las personas a quienes se les habilitó para ejercer como corredores y notarios \n públicos, así como sus datos de contacto, la información relacionada con el proceso de otorgamiento \n de la patente y las sanciones que se les hubieran aplicado; \n VI. Los planes de desarrollo urbano, ordenamiento territorial y ecológico, los tipos y usos de suelo, \n licencias de uso y construcción otorgadas por los gobiernos municipales; \n VII. Los proyectos de disposiciones administrativas, sa lvo que su difusión pueda comprometer los efectos \n que se pretenden lograr con la disposición o se trate de situaciones de emergencia, en términos de lo \n previsto en la Ley General de Mejora Regulatoria; \n VIII. Las gacetas municipales, las cuales se deberán c omprender los resolutivos y acuerdos aprobados por \n los ayuntamientos, y \n IX. Las actas de sesiones de cabildo, los controles de asistencia de las personas integrantes del \n Ayuntamiento a las sesiones de cabildo y el sentido de votación de las y los miembros del cabildo \n sobre las iniciativas o acuerdos.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":65},{"id":"5e3cfcff-c633-400b-8e9f-726554881d6c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 67.","contenido":"Los sujetos obligados del Poder Ejecutivo Federal, además de lo señalado en el artículo anterior, \n deberán poner a disposición del público y actualizar la siguiente información: \n I. A las fuerzas arm adas: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 22 de 64 \n a ) Las estadísticas sobre indultos, juicios en trámite, resoluciones ejecutorias, por delito, por grado \n de los sentenciados, por año y sentencias cumplidas, y \n b ) La estadística de las licencias de armas de fuego por tipo; \n II. En materia hacendaria: \n a ) La cartera de programas y proyectos de inversión; \n b ) Para efectos estadísticos, la lista de estímulos fiscales establecidos en las leyes fiscales, \n identificados por acreditamientos, devoluciones, disminuciones, y deducciones, tanto de personas \n físicas, c omo morales, así como su porcentaje; \n c ) El nombre, denominación o razón social y clave del registro federal de contribuyentes a quienes \n se les hubiera cancelado o condonado algún crédito fiscal, ya determinado y exigible, así como \n los montos respectivos; d ebiendo vincular tales actos con los datos de identificación de \n contribuyentes señalados en este párrafo. Asimismo, la información estadística sobre las \n exenciones previstas en las disposiciones fiscales, y \n d ) Agentes aduanales con patente autorizada; \n III. En materia de población: \n a ) El número de centros penitenciarios o centros de tratamiento para adolescentes, indicando su \n capacidad instalada, así como su ubicación y la función de los espacios físicos de infraestructura \n con los que cuentan; \n b ) La estadíst ica migratoria de entradas de extranjeros con legal estancia en México y condición de \n estancia, eventos de extranjeros presentados y devueltos; desagregada por sexo, grupo de edad \n y nacionalidad, y \n c ) La estadística de los grupos de protección a migrantes, por acciones de atención; \n IV. En materia de seguridad pública y procuración de justicia: \n a ) Para efectos estadísticos, el listado de solicitudes a las empresas concesionarias de \n telecomunicaciones y proveedores de servicios o aplicaciones de Internet para la intervención de \n comunicaciones privadas, el acceso al registro de comunicaciones y la localización geográfica en \n tiempo real de equipos de comunicación, que contenga exclusivamente el objeto, el alcance \n temporal y los fundamentos legales del requerimie nto, así como, en su caso, la mención de que \n cuenta con la autorización judicial correspondiente; \n b ) La estadística de los procesos de control de confianza desagregada por entidad federativa e \n institución; \n c ) La incidencia delictiva del fuero federal, desa gregada por tipo de delito, así como el número de \n víctimas desagregado por sexo y rango de edad; \n d ) La estadística desagregada de procesos, denuncias e investigaciones relacionadas a las \n conductas consideradas como delitos en materia de justicia para adole scentes, y \n e ) La estadística relativa a la solución de controversias realizadas a través de los mecanismos \n alternativos de solución de controversias en materia penal, desagregada por medios de \n mediación, conciliación y junta restaurativa; \n V. En materia de política exterior: \n a ) El listado de asuntos de protección a mexicanos en el exterior, que contenga sexo, rango de \n edad, país, tipo de apoyo y, en su caso, monto; \n b ) El número de constancias de suscripción del Convenio a que hace referencia la fracción I de l \n artículo 27 de la Constitución Política de los Estados Unidos Mexicanos para obtener \n concesiones para la exploración y explotación de minas y aguas en territorio nacional, indicando \n la entidad federativa y la nacionalidad de la persona solicitante y para la adquisición de bienes \n inmuebles fuera de la zona restringida, indicando la entidad federativa y la nacionalidad de la \n persona solicitante, así como el número de permisos otorgados para la constitución de \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 23 de 64 \n fideicomisos, señalando la fiduciaria, nacionali dad del fideicomisario y la entidad federativa donde \n se localiza el inmueble; \n c ) El número de cartas de naturalización, identificadas por modalidad, fecha de expedición, sexo, \n rango de edad y país de origen; \n d ) Las determinaciones o resoluciones emitidas p or órganos u organismos jurisdiccionales \n internacionales en los que México haya sido parte o haya intervenido, desagregado por tribunal \n de procedencia, fecha, materia y estado de cumplimiento de la resolución; \n e ) Los tratados internacionales celebrados y e n vigor para México y, en su caso, los informes de los \n mecanismos de revisión de su implementación; \n f ) Información estadística sobre candidaturas internacionales que el gobierno de México postule, \n una vez que el desarrollo del proceso de elección haya fina lizado y no actualice el supuesto a \n que se refiere la fracción II del artículo 112 de la presente Ley; \n g ) El informe sobre el desempeño de las personas representantes de México cuando presidan, \n encabecen o coordinen comisiones, consejos, comités, grupos de trabajo, asambleas, reuniones \n y conferencias de alto nivel, mecanismos ad hoc, o cualquier órgano dependiente y/o de carácter \n subsidiario de organismos internacionales y mecanismos multilaterales; \n h ) Los votos, posicionamientos e iniciativas de México emi tidos en el seno de organismos \n internacionales y mecanismos multilaterales, así como las declaraciones y resoluciones que \n hubieren propuesto o copatrocinado, una vez que el proceso de negociación haya finalizado; \n i ) Los acuerdos interinstitucionales regist rados ante la Secretaría de Relaciones Exteriores a los \n que hace referencia la Ley Sobre la Celebración de Tratados, y \n j ) Los acuerdos ejecutivos, memorandos de entendimiento, protocolos, cartas de intención y otros \n instrumentos que, sin adoptar la categor ía de Tratados, suscriben representantes del Gobierno \n Federal con representantes de otros gobiernos mediante los cuales se adquieren compromisos \n jurídicamente vinculantes; \n VI. En materia del medio ambiente y recursos naturales: \n a ) El listado de áreas natur ales protegidas, que contenga categoría, superficie, región y entidades \n federativas que las comprenden; \n b ) El listado de especies mexicanas en riesgo, por grupo taxonómico; \n c ) El listado de vegetación natural, por entidad federativa, por ecosistema y por s uperficie; \n d ) El listado estimado de residuos, por tipo, por volumen, por entidad federativa y por año; \n e ) La disponibilidad media anual de aguas superficiales y subterráneas por región hidrológica; \n f ) El Inventario nacional de plantas municipales de potab ilización y tratamiento de aguas residuales; \n g ) El listado de zonas contaminadas, por tipo de contaminante y localización; \n h ) Los tipos de vegetación forestal y de suelos, su localización, formaciones y clases, con \n tendencias y proyecciones que permitan cl asificar y delimitar el estado actual de la deforestación \n y degradación, así como las zonas de conservación, protección, restauración y producción \n forestal, en relación con las cuencas hidrológicas - forestales, las regiones ecológicas, las áreas \n forestales permanentes y las áreas naturales protegidas; \n i ) La dinámica de cambio de la vegetación forestal del país, que permita conocer y evaluar las tasas \n de deforestación y las tasas de degradación y disturbio, registrando sus causas principales; \n j ) Los criterios e indicadores de sustentabilidad, deforestación y degradación de los ecosistemas \n forestales; \n k ) El listado de plantaciones comerciales forestales, que contenga su ubicación, superficie, tipo de \n especie forestal, nivel de producción y su estatus; \n l ) Las ma nifestaciones y resoluciones en materia de impacto ambiental; \n m ) Información estadística sobre los árboles históricos y notables del país; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 24 de 64 \n n ) Información estadística sobre infracciones, identificando la causa que haya motivado la \n infracción, el precepto le gal infringido y la descripción de la infracción, y \n o ) El índice de participación ciudadana, que contenga la categoría, ponderación, unidad de medida \n y año; \n VII. En materia de economía: \n a ) La lista de los aranceles vigentes que contenga la fracción arancel aria, la descripción, la tasa \n base, la categoría y, en su caso, el instrumento al que atiende; \n b ) Los nombres de las personas a quienes se les habilitó para ejercer como corredores públicos, así \n como el domicilio de las corredurías públicas, los resultados del examen definitivo por los cuales \n se obtuvo la habilitación y las sanciones que se les hubieran aplicado; \n c ) Información estadística sobre controversias resueltas en arbitraje internacional en materia de \n comercio exterior, desglosado por árbitro, parte s, controversia y fecha de la resolución, y \n d ) La información relacionada con: \n 1. La información geológica, geofísica, geoquímica y yacimientos minerales del país; \n 2. Las coordenadas geográficas de la concesión con lados, rumbos y distancias; \n 3. Las region es y zonas asignadas para la exploración y explotación de los minerales; \n 4. Las bases y reglas que se hayan empleado para adjudicar las concesiones y asignaciones; \n 5. El padrón de concesiones mineras; \n 6. Las cifras globales de volumen y valor de minerales concesibles; producción minera por \n Entidad y Municipio, producción minerometalúrgica por forma de presentación, producción \n de Carbón y participación en el valor de producción por Entidad, y \n 7. Los informes sobre las visitas de inspección que incluyan, cuan do menos, los datos del \n título de concesión, fecha de ejecución de la visita, titular de la concesión y resolución de la \n misma; \n VIII. En materia de agricultura, ganadería, desarrollo rural, pesca y alimentación: \n a ) El listado de apoyos otorgados en materia de agricultura, ganadería, pesca o alimentación, que \n contenga municipio, población o localidad, descripción o monto del apoyo, y el número de \n beneficiarios distinguidos por género; \n b ) El listado de ingenios azucareros, que contenga producción, costo anual y entidad federativa; \n c ) El listado de activos y unidades económicas de pesca y acuacultura, que contenga entidad \n federativa, embarcaciones, granjas, laboratorios y tipo de actividad; \n d ) El listado de agronegocios, empresas rurales y productores que recib en incentivos de riesgo \n compartido, que contenga objetivo y tipo de incentivo, y \n e ) La lista de certificaciones emitidas para la importación o exportación de mercancías agrícolas, \n pecuarias, acuícolas y pesqueras, desagregada por tipo de mercancía, origen, punto de ingreso, \n tránsito y destino; y en caso de negativa, las medidas sanitarias o fitosanitarias pertinentes como \n el retorno, acondicionamiento, reacondicionamiento o destrucción de la mercancía; \n IX. En materia de comunicaciones y transportes: \n a ) Info rmación estadística sobre las aeronaves civiles mexicanas identificadas; \n b ) La incidencia de accidentes de aviación, desagregado por fecha, hora local, marca de \n nacionalidad, matrícula, tipo, marca, modelo, servicio destinado, operador aéreo, lugar del \n acc idente, entidad federativa, tipo de lesión de la tripulación y pasajeros, daños a la aeronave y \n causas probables; \n c ) Información estadística operativa correspondiente al número de vuelos, pasajeros y mercancía \n transportada por origen - destino en operación d oméstica e internacional en servicio regular y \n fletamento de manera acumulada; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 25 de 64 \n d ) Información estadística por operador aéreo respecto de número de vuelos, pasajeros y \n mercancía transportada en operación doméstica e internacional en servicio regular y fleta mento \n de manera acumulada; \n e ) El listado de regiones carreteras que contemple la zona, el tipo de red carretera, el tramo \n carretero y los puentes; \n f ) Información estadística portuaria de movimiento de carga, por mes, contenedor, puerto, tipo de \n carga, peso , importación, exportación, tipo de tráfico, origen y destino; \n g ) Información estadística de tránsito de buques y transbordadores por mes, puerto, origen y \n destino; \n h ) Información estadística de arribo de cruceros por mes, puerto, origen, destino y número de \n pasajeros; \n i ) Información estadística de embarcaciones mexicanas matriculadas, por año de matriculación, \n edad de la embarcación y tipo, y \n j ) La información financiera y tarifaria de las redes de telecomunicaciones alámbricas e \n inalámbricas que cuenten c on participación gubernamental; \n X. En materia del sector educación y cultura: \n a ) El Catálogo de los Centros de Trabajo de carácter educativo en la educación básica, media \n superior, superior, especial, inicial y formación para el trabajo incluyendo la infor mación relativa a \n su situación geográfica, tipo de servicio que proporciona y estatus de operación; \n b ) El listado del personal que presta sus servicios en los sistemas de educación pública básica, \n tecnológica y de adultos, cuyas remuneraciones se cubren co n cargo a recursos públicos \n federales; \n c ) El padrón de beneficiarios de las becas, así como los procedimientos y requisitos para \n obtenerlas, desagregado por nombre, tipo, fecha de inicio y término de la beca, área del \n conocimiento, así como el monto otorga do, y \n d ) El Catálogo de museos, que contenga el nombre, la entidad federativa, ubicación, horarios, \n temática tratada, servicios disponibles y cuota de acceso; \n XI. En materia de salud: \n a ) El listado de los institutos o centros de salud, desagregados por nom bre, especialidad, dirección y \n teléfono, y \n b ) El listado de las instituciones de beneficencia privada, que tengan por objeto la asistencia pública, \n desagregada por nombre, ubicación, datos de contacto y tipo; \n XII. En materia del trabajo y previsión social: \n a ) El nombre y objeto de las asociaciones obreras y patronales de jurisdicción federal registradas; \n b ) El número de trabajadores asegurados en el Instituto Mexicano del Seguro Social, desagregado \n por mes, por actividad económica, entidad federativa, perma nentes y eventuales; y respecto de \n estos últimos, distinguidos por urbanos y de campo, y \n c ) El número de personas beneficiadas por las actividades de capacitación, promoción al empleo, \n colocación de trabajadores y vinculación laboral del Servicio Nacional de Empleo, por año, \n entidad federativa, oficio o profesión, género, rango de edad, ramo o industria y mecanismo de \n vinculación; \n XIII. En materia de desarrollo agrario, territorial y urbano: \n a ) El listado de núcleos agrarios identificando los datos técnicos generales y la síntesis diagnóstica \n de los mismos, y \n XIV. En materia de turismo: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 26 de 64 \n a ) Información estadística sobre las actividades económicas vinculadas al turismo, como número de \n visitantes internacionales, flujos aéreos, flujos de cruceros y flujos carre teros; \n b ) Información correspondiente a destinos turísticos por entidad federativa, con estadísticas sobre \n actividades turísticas; \n c ) Información estadística sobre ocupación hotelera, y \n d ) El listado de prestadores de servicios turísticos.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":66},{"id":"83d7bfc1-2fa0-49ea-a86c-d7ba1106cf8c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 68.","contenido":"Los sujetos obligados del Poder Legislativo Federal y de las entidades federativas, además de lo \n señalado en el artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información \n siguiente: \n I. Agenda legislativa; \n II. Gaceta Pa rlamentaria; \n III. Orden del Día; \n IV. El Diario de Debates; \n V. Las versiones estenográficas; \n VI. La asistencia de cada una de sus sesiones del Pleno y de las Comisiones y Comités; \n VII. Las iniciativas de ley o decretos, puntos de acuerdo, la fecha en que se recibió, las Comisiones a las \n que se turnaron, y los dictámenes que, en su caso, recaigan sobre las mismas; \n VIII. Las leyes, decretos y acuerdos aprobados por el órgano legislativo; \n IX. Las convocatorias, actas, acuerdos, listas de asistencia y votación d e las Comisiones y Comités y de \n las sesiones del Pleno, identificando el sentido del voto, en votación económica, y por cada legislador, \n en la votación nominal y el resultado de la votación por cédula, así como votos particulares y reservas \n de los dictámen es y acuerdos sometidos a consideración; \n X. Las resoluciones definitivas sobre juicios políticos y declaratorias de procedencia; \n XI. Las versiones públicas de la información entregada en las audiencias públicas, comparecencias y en \n los procedimientos de de signación, ratificación, elección, reelección o cualquier otro; \n XII. Las contrataciones de servicios personales señalando el nombre del prestador del servicio, objeto, \n monto y vigencia del contrato de los órganos de gobierno, Comisiones, Comités, Grupos \n Pa rlamentarios y centros de estudio u órganos de investigación; \n XIII. El informe semestral del ejercicio presupuestal del uso y destino de los recursos financieros de los \n órganos de gobierno, Comisiones, Comités, Grupos Parlamentarios y centros de estudio u órganos de \n investigación; \n XIV. Los resultados de los estudios o investigaciones de naturaleza económica, política y social que \n realicen los centros de estudio o investigación legislativa, y \n XV. El padrón de cabilderos, de acuerdo a las disposiciones jurídi cas aplicables.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":67},{"id":"3ee6b255-e90c-4956-b593-75a6fc809f4d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 69.","contenido":"Los sujetos obligados de los Poderes Judiciales Federal y de las entidades federativas, además de \n lo señalado en el artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información \n siguiente: \n I. Las tesis y ejecutorias publicadas en el Semanario Judicial de la Federación o en la Gaceta respectiva \n de cada tribunal administrativo, incluyendo, tesis jurisprudenciales y aisladas; \n II. Las versiones públicas de todas las sentencias y laudos emitidas; \n III. Las versiones estenográficas, los audios y las videograbaciones de las sesiones públicas, según \n corresponda; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 27 de 64 \n IV. La relacionada con los procesos por medio de los cuales fueron designados los jueces y magistrados; \n V. La lista de acuerdos que diariamen te se publiquen; \n VI. Sobre los procedimientos de designación de jueces y magistrados: la convocatoria, el registro de \n aspirantes, la lista de aspirantes aceptados, la lista de los aspirantes que avanzan cada una de las \n etapas, el resultado de las evaluacio nes de cada etapa protegiendo, en su caso, los datos personales \n de los aspirantes y la lista de vencedores; \n VII. Sobre los procedimientos de ratificación: la resolución definitiva donde se plasmen las razones de esa \n determinación; \n VIII. Las resoluciones qu e impongan sanciones disciplinarias a los integrantes del Poder Judicial de la \n Federación, de conformidad a lo establecido en las disposiciones jurídicas aplicables; \n IX. Los indicadores relacionados con el desempeño jurisdiccional que, conforme a sus funci ones, deban \n establecer, publicitando por lo menos los números de ingresos de asuntos nuevos por mes y por año, \n números de resoluciones emitidas por mes y por año, sentido general del fallo de acuerdo con la \n materia, tiempo promedio de resolución de asuntos , número de impugnaciones recibidas por mes y por \n año, número de impugnaciones declaradas procedentes por mes y por año; \n X. Las disposiciones de observancia general emitidas por los Plenos o sus presidentes, para el adecuado \n ejercicio de sus atribuciones; \n XI. Los votos concurrentes, minoritarios, aclaratorios, particulares o de cualquier otro tipo, que emitan los \n integrantes de los Plenos, y \n XII. Las resoluciones recaídas a los asuntos de contradicciones de criterios.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":68},{"id":"24e18c46-5f24-476e-8031-72078445e000","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 70.","contenido":"Los órganos autónomos, ade más de lo señalado en el artículo 65 de la presente Ley, deberán poner \n a disposición del público y actualizar la información siguiente: \n I. Instituto Nacional Electoral y organismos públicos locales electorales de las entidades federativas: \n a ) Los listados de partidos políticos, asociaciones y agrupaciones políticas o de ciudadanos \n registrados ante la autoridad electoral; \n b ) Los informes que presenten los partidos políticos, asociaciones y agrupaciones políticas o de \n ciudadanos; \n c ) La geografía y cartografía electoral; \n d ) El registro de candidatos a cargos de elección popular; \n e ) El Catálogo de estaciones de radio y canales de televisión, pautas de transmisión, versiones de \n spots de los institutos electorales y de los partidos políticos; \n f ) Los montos de fina nciamiento público por actividades ordinarias, de campaña y específicas \n otorgadas a los partidos políticos, asociaciones y agrupaciones políticas o de ciudadanos y \n demás asociaciones políticas, así como los montos autorizados de financiamiento privado y lo s \n topes de los gastos de campañas; \n g ) La metodología e informes sobre la publicación de encuestas por muestreo, encuestas de salida \n y conteos rápidos financiados por las autoridades electorales competentes; \n h ) La metodología e informe del Programa de Resul tados Preliminares Electorales; \n i ) Los cómputos totales de las elecciones y procesos de participación ciudadana; \n j ) Los resultados y declaraciones de validez de las elecciones; \n k ) Las franquicias postales y telegráficas asignadas al partido político para e l cumplimiento de sus \n funciones; \n l ) La información sobre votos de mexicanos residentes en el extranjero; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 28 de 64 \n m ) Los dictámenes, informes y resoluciones sobre pérdida de registro y liquidación del patrimonio de \n los partidos políticos nacionales y locales, y \n n ) El monitoreo de medios; \n II. Organismos de protección de los derechos humanos Nacional y de las entidades federativas: \n a ) El listado y las versiones públicas de las recomendaciones emitidas, su destinatario o autoridad a \n la que se recomienda y el estado que guarda su atención, incluyendo, en su caso, las minutas de \n comparecencias de los titulares que se negaron a aceptar las recomendaciones; \n b ) Las quejas y denuncias presentadas ante las autoridades administrativas y penales respectivas, \n señalando el estado procesal en que se encuentran y, en su caso, el sentido en el que se \n resolvieron; \n c ) Las versiones públicas del acuerdo de conciliación, previo consentimiento del quejoso; \n d ) Listado de medidas precautorias, cautelares o equivalentes, giradas una vez concl uido el \n Expediente; \n e ) Toda la información con que cuente, relacionada con hechos constitutivos de violaciones graves \n de derechos humanos o delitos de lesa humanidad, una vez determinados así por la autoridad \n competente, incluyendo, en su caso, las accione s de reparación del daño, atención a víctimas y \n de no repetición; \n f ) La información relacionada con las acciones y resultados de defensa, promoción y protección de \n los derechos humanos; \n g ) Las actas y versiones estenográficas de las sesiones del consejo co nsultivo, así como las \n opiniones que emite; \n h ) Los resultados de los estudios, publicaciones o investigaciones que realicen; \n i ) Los programas de prevención y promoción en materia de derechos humanos; \n j ) El estado que guardan los derechos humanos en el sist ema penitenciario y de readaptación \n social del país; \n k ) El seguimiento, evaluación y monitoreo, en materia de igualdad entre mujeres y hombres; \n l ) Los programas y las acciones de coordinación con las dependencias competentes para impulsar \n el cumplimiento d e tratados de los que el Estado mexicano sea parte, en materia de derechos \n humanos, y \n m ) Los lineamientos generales de la actuación de la Comisión Nacional de los Derechos Humanos; \n III. El Banco de México: \n a ) La estadística de la emisión de billetes y acuñ ación de moneda metálica; \n b ) El informe del crédito que, en su caso, otorgue al Gobierno Federal de conformidad con la Ley del \n Banco de México; \n c ) El listado de las aportaciones realizadas por el Banco de México a organismos financieros \n internacionales de conformidad con la Ley del Banco de México; \n d ) El listado de los financiamientos otorgados a las instituciones de crédito, en forma agregada; \n e ) El importe de la reserva de activos internacionales; \n f ) La relación de sanciones impuestas por infracciones a l as disposiciones emitidas por el propio \n Banco, que regulan las entidades y personas sujetas a su supervisión, excepto por aquellas \n relacionadas con operaciones realizadas como parte de política monetaria, para lo cual deberán \n señalar: \n 1. El nombre, denomin ación o razón social de la persona infractora; \n 2. El precepto legal infringido, el tipo de sanción impuesta, el monto o plazo, según \n corresponda, así como la conducta infractora, y \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 29 de 64 \n 3. El estado que guarda la resolución, indicando si se encuentra firme o bi en, si es susceptible \n de ser impugnada y, en este último caso, si se ha interpuesto algún medio de defensa y su \n tipo, cuando se tenga conocimiento de tal circunstancia por haber sido debidamente \n notificada por autoridad competente. \n En todo caso, si la san ción impuesta se deja sin efectos por alguna autoridad competente, deberá \n igualmente publicarse tal circunstancia, y \n g ) La exposición sobre la política monetaria a seguir por el propio Banco, así como los informes \n trimestrales sobre la inflación, la evoluc ión económica y el comportamiento de los indicadores \n económicos del país y la ejecución de la política monetaria y, en general, las actividades del \n Banco, que este deba enviar al Ejecutivo Federal y al Congreso de la Unión de conformidad con \n la Ley del Ban co de México; \n IV. La Fiscalía General de la República publicará la información estadística en las siguientes materias: \n a ) Incidencia delictiva; \n b ) Indicadores de la procuración de justicia. En materia de carpetas de investigación y \n averiguaciones previas, deberá publicarse el número de aquéllas en las que se ejerció acción \n penal; en cuántas se decretó el no ejercicio de la acción penal; cuántas se archivaron; en cuántas \n se ejerció la facultad de atracción en materia de delitos cometidos contra la libertad d e expresión; \n en cuántas se ejerció el criterio de oportunidad, y en cuántas ejerció la facultad de no investigar \n los hechos de su conocimiento. Dicha información deberá incluir el número de denuncias o \n querellas que le fueron interpuestas, y \n c ) Número de ó rdenes de presentación, aprehensión y de cateo emitidas, y \n V. El Instituto Nacional de Estadística y Geografía: \n a ) El Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y el \n resultado de su evaluación sexenal; \n b ) El Programa Nacional de Estadística y Geografía; \n c ) El Programa Anual de Estadística y Geografía; \n d ) Las inspecciones realizadas para verificar la autenticidad de la información de interés nacional, \n así como el seguimiento que se dé a las mismas; \n e ) El Catálogo Nacion al de Indicadores; \n f ) El anuario estadístico geográfico; \n g ) El Catálogo de claves de áreas geo estadísticas estatales, municipales y localidades; \n h ) Los documentos que den cuenta de la realidad demográfica y social, económica, del medio \n ambiente, de gobier no, seguridad pública e impartición de justicia del país; \n i ) Las variables utilizadas para su cálculo, metadatos, comportamiento en el tiempo, a través de \n tabulados y elementos gráficos; \n j ) Las clasificaciones, catálogos, cuestionarios; \n k ) Las metodologías , documentos técnicos y proyectos estadísticos; \n l ) Los censos, encuestas, conteos de población, micro datos y macro datos, estadísticas \n experimentales y muestras representativas de los operativos censales realizados; \n m ) La información nacional, por entidad federativa y municipios, cartografía, recursos naturales, \n topografía, sistemas de consulta, bancos de datos, fuente, normas técnicas; \n n ) Los resultados de la ejecución del Programa Anual de Información Estadística y Geográfica \n correspondiente al año inmed iato anterior; \n o ) Un informe de las actividades de los Comités de los Subsistemas; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 30 de 64 \n p ) El informe anual de actividades y sobre el ejercicio del gasto correspondiente al ejercicio \n inmediato anterior, y \n q ) El calendario anual de publicación aprobado por la Ju nta de Gobierno.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":69},{"id":"8adff3ce-718f-4f79-a624-b19a923355be","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 71.","contenido":"El sujeto obligado con facultades en materia de competencia económica, además de lo señalado en \n el artículo 65 de la presente Ley, deberá poner a disposición del público y actualizar la información siguiente: \n I. El registro de las entrevistas que lleve a cabo con personas que representen los intereses de los \n agentes económicos para tratar asuntos de su competencia, en términos de la ley de la materia; \n II. Las versiones públicas de las resoluciones que califiquen las excusas o r ecusaciones; \n III. El listado de los asuntos por resolver; \n IV. Las notificaciones que deban realizarse por lista en los términos que señale las disposiciones \n aplicables; \n V. El listado de las sanciones que determine; \n VI. Las directrices, guías, lineamientos y criterios técnicos que emita previa consulta pública; \n VII. Los comentarios presentados por terceros en un procedimiento de consulta pública para la elaboración \n y expedición de las disposiciones regulatorias a que se refiere la Ley Federal de Competencia \n Económica; \n VIII. La versión pública de las evaluaciones cuantitativa y cualitativa de las aportaciones netas al bienestar \n del consumidor que haya generado su actuación en el periodo respectivo, y \n IX. La versión pública de los estudios, trabajos de investig ación e informes generales en materia de \n competencia económica sobre sectores, en su caso, con las propuestas respectivas de liberalización, \n desregulación o modificación normativa.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":70},{"id":"934c46e2-7cd0-4d80-863c-4727636410b4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 72.","contenido":"El sujeto obligado con facultades en materia de telecomunicaci ones, además de lo señalado en el \n artículo 65 de la presente Ley, deberá poner a disposición del público y actualizar la información siguiente: \n I. El registro de las entrevistas que lleve a cabo con personas que representen los intereses de los \n agentes eco nómicos para tratar asuntos de su competencia, en términos de la ley de la materia; \n II. Los procesos de consultas públicas, el calendario de consultas a realizar y las respuestas o \n propuestas recibidas; \n III. Los programas sobre bandas de frecuencias del es pectro radioeléctrico para usos determinados, con \n sus correspondientes modalidades de uso y coberturas geográficas que sean materia de licitación \n pública, y \n IV. Respecto del Registro Público de Concesiones, la información pública y no clasificada de: \n a ) Lo s títulos de concesión y las autorizaciones otorgadas, así como sus modificaciones o \n terminación de los mismos; \n b ) El Cuadro Nacional de Atribución de Frecuencias actualizado; \n c ) Los servicios asociados; \n d ) Los gravámenes impuestos a las concesiones; \n e ) La s cesiones de derechos y obligaciones de las concesiones; \n f ) Las bandas de frecuencias otorgadas en las distintas zonas del país; \n g ) Los convenios de interconexión, los de compartición de infraestructura y desagregación de la red \n local que realicen los con cesionarios; \n h ) Las ofertas públicas que realicen los concesionarios declarados como agentes económicos \n preponderantes en los sectores de telecomunicaciones y radiodifusión o con poder sustancial; \n i ) Las tarifas al público de los servicios de telecomunicac iones ofrecidos por los concesionarios y \n los autorizados; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 31 de 64 \n j ) Los contratos de adhesión de los concesionarios; \n k ) La estructura accionaria de los concesionarios; \n l ) Los criterios adoptados; \n m ) Los programas anuales de trabajo, los informes trimestrales de a ctividades, así como los estudios \n y consultas que genere; \n n ) Los lineamientos, modelos y resoluciones en materia de interconexión, así como los planes \n técnicos fundamentales que expida; \n o ) Las medidas y obligaciones específicas impuestas al o a los concesi onarios que se determinen \n como agentes económicos con poder sustancial o preponderantes; \n p ) Los resultados de las acciones de supervisión, respecto del cumplimiento de las obligaciones de \n los concesionarios; \n q ) Las estadísticas de participación de los conc esionarios, autorizados y grupo de interés \n económico en cada mercado que determine el sujeto obligado; \n r ) Los procedimientos sancionatorios iniciados y las sanciones impuestas que hubieren quedado \n firmes, y \n s ) Las sanciones impuestas por la Procuraduría Fe deral del Consumidor que hubieren quedado \n firmes.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":71},{"id":"4d3b039f-8d89-40c6-968d-7e881399aae1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 73.","contenido":"Además de lo señalado en el artículo 65, las Autoridades garantes deberán poner a disposición del \n público y actualizar: \n I. La relación de observaciones y resoluciones emitidas y el seguimiento a cada una de ellas, incluyendo \n las respuestas entregadas por los sujetos obligados a las personas solicitantes en cumplimiento de las \n resoluciones; \n II. Los criterios orientadores que deriven de sus resoluciones; \n III. Los resultados de la evaluación que, e n su caso, se realice al cumplimiento de la presente Ley por \n parte de los sujetos obligados; \n IV. En su caso, las sentencias, ejecutorias o suspensiones judiciales que existan en contra de sus \n resoluciones, y \n V. El número de quejas, denuncias y recursos de revisión dirigidos a cada uno de los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":72},{"id":"33064c92-6931-499d-a2b3-3fe9002184ce","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 74.","contenido":"Las instituciones de educación superior públicas dotadas de autonomía, además de lo señalado en \n el artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información siguiente: \n I. Los planes y programas de estudio según el sistema que ofrecen, ya sea escolarizado o abierto, con \n las áreas de conocimiento, el perfil profesional de quien cursa el plan de estudios, la duración del \n programa con las asignaturas, su valor en créditos, formas y costos de titulación; \n II. La información relacionada con sus procedimientos administrativos; \n III. La remuneración de los profesores, incluyendo los estímulos, prestaciones, gratificaciones, primas, \n comisiones, dietas, bonos, ingresos y sistemas de compensación, señalando la periodicidad de dicha \n remuneración, nivel y monto; \n IV. La lista con los profesores con licencia o en año sabático; \n V. El listado de las becas y apoyos que otorgan, así como los procedimientos y requisitos p ara \n obtenerlos; \n VI. Las convocatorias de los concursos de oposición; \n VII. La información relativa a los procesos de selección de los consejos; \n VIII. El resultado de las evaluaciones del cuerpo docente; \n IX. El listado de instituciones incorporadas y requisi tos de incorporación; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 32 de 64 \n X. El número de personas estudiantes inscritas, desglosado por área de conocimiento, tipo de sistema de \n estudios, modalidad de estudio, grado académico y denominación o título del grado, y \n XI. El número de personas egresadas y titulad as, desglosado por área de conocimiento, tipo de sistema \n de estudios, modalidad de estudio, grado académico y denominación o título del grado.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":73},{"id":"559e5a4e-8b15-4e8f-bb25-777d8b06a96f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 75.","contenido":"Los partidos políticos nacionales y locales, las agrupaciones políticas nacionales y las personas \n mo rales constituidas en asociación civil creadas por los ciudadanos que pretendan postular su candidatura \n independiente, según corresponda, además de lo señalado en el artículo 65 de la presente Ley, deberán poner a \n disposición del público y actualizar la in formación siguiente: \n I. El padrón de afiliados o militantes de los partidos políticos, que contendrá, exclusivamente: apellidos, \n nombre o nombres, fecha de afiliación y entidad de residencia; \n II. Los acuerdos y resoluciones de los órganos de dirección de l os partidos políticos; \n III. Los convenios de participación entre partidos políticos con organizaciones de la sociedad civil; \n IV. Los contratos y convenios para la adquisición o arrendamiento de bienes y servicios; \n V. Las minutas de las sesiones de los part idos políticos; \n VI. Los responsables de los órganos internos de finanzas de los partidos políticos; \n VII. Las organizaciones sociales adherentes o similares a algún partido político; \n VIII. Los montos de las cuotas ordinarias y extraordinarias aportadas por sus militantes; \n IX. Los montos autorizados de financiamiento privado, así como una relación de los nombres de los \n aportantes vinculados con los montos aportados; \n X. El listado de aportantes a las precampañas y campañas políticas; \n XI. El acta de la asamblea constitutiva; \n XII. Las demarcaciones electorales en las que participen; \n XIII. Los tiempos que les corresponden en canales de radio y televisión; \n XIV. Los documentos básicos, plataformas electorales y programas de gobierno y los mecanismos de \n designación d e los órganos de dirección en sus respectivos ámbitos; \n XV. El directorio de sus órganos de dirección nacionales, estatales, municipales, de las demarcaciones \n territoriales y, en su caso, regionales, delegacionales y distritales; \n XVI. El tabulador de remune raciones que perciben los integrantes de los órganos a que se refiere la \n fracción anterior y de los demás funcionarios partidistas, que deberá vincularse con el directorio y \n estructura orgánica, así como cualquier persona que reciba ingresos por parte del partido político, \n independientemente de la función que desempeñe dentro o fuera del partido; \n XVII. El currículo con fotografía reciente de todos los precandidatos y candidatos a cargos de elección \n popular, con el cargo al que se postula, el distrito electo ral y la entidad federativa; \n XVIII. El currículo de los dirigentes a nivel nacional, estatal y municipal; \n XIX. Los convenios de frente, coalición o fusión que celebren o de participación electoral que realicen con \n agrupaciones políticas nacionales; \n XX. Las convocatorias que emitan para la elección de sus dirigentes o la postulación de sus candidatos a \n cargos de elección popular y, en su caso, el registro correspondiente; \n XXI. Los responsables de los procesos internos de evaluación y selección de candidatos a cargos de \n elección popular, conforme a su normatividad interna; \n XXII. Informes sobre el gasto del financiamiento público ordinario recibido para la capacitación, promoción y \n desarrollo del liderazgo político de las mujeres; \n XXIII. Las resoluciones dictad as por los órganos de control; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 33 de 64 \n XXIV. Los montos de financiamiento público otorgados mensualmente, en cualquier modalidad, a sus \n órganos nacionales, estatales, municipales y demarcaciones territoriales, así como los descuentos \n correspondientes a sanciones; \n XXV. El estado de situación financiera y patrimonial; el inventario de los bienes inmuebles de los que sean \n propietarios, así como los anexos que formen parte integrante de los documentos anteriores; \n XXVI. Las resoluciones que emitan sus órganos disciplina rios de cualquier nivel, una vez que hayan causado \n estado; \n XXVII. Los nombres de sus representantes ante la autoridad electoral competente; \n XXVIII. Los mecanismos de control y supervisión aplicados a los procesos internos de selección de \n candidatos; \n XXIX. El listado de fundaciones, asociaciones, centros o institutos de investigación o capacitación o cualquier \n otro que reciban apoyo económico de los partidos políticos, así como los montos destinados para tal \n efecto, y \n XXX. Las resoluciones que dicte la autor idad electoral competente respecto de los informes de ingresos y \n gastos.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":74},{"id":"dc2c4841-92b2-46dd-85e9-1fcf503ce809","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 76.","contenido":"Los fideicomisos, fondos públicos, mandatos o cualquier contrato análogo, además de lo señalado \n en el artículo 65 de la presente Ley, deberán poner a disposición del públ ico y mantener actualizada y accesible, en \n lo que resulte aplicable a cada contrato, la información siguiente: \n I. El nombre de la persona servidora pública y de la persona física o moral que represente al \n fideicomitente, al fiduciario y al fideicomisario; \n II. La unidad administrativa responsable del fideicomiso; \n III. El monto total, el uso y destino del patrimonio fideicomitido, distinguiendo las aportaciones públicas y \n fuente de los recursos, los subsidios, donaciones, transferencias, excedentes, inversion es realizadas y \n aportaciones o subvenciones que reciban; \n IV. El saldo total al cierre del ejercicio fiscal, sin perjuicio de los demás informes que deban presentarse en \n los términos de las disposiciones aplicables; \n V. Las modificaciones que, en su caso, su fran los contratos o decretos de constitución del fideicomiso o \n del fondo público; \n VI. El padrón de beneficiarios, en su caso; \n VII. Causas por las que, en su caso, se inicie el proceso de constitución o extinción del fideicomiso o fondo \n público, especifica ndo, de manera detallada, los recursos financieros destinados para tal efecto, y \n VIII. Los contratos de obras, adquisiciones y servicios que involucren recursos públicos del fideicomiso, así \n como los honorarios derivados de los servicios y operaciones que realice la institución de crédito o la \n fiduciaria.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":75},{"id":"57f99495-a9f7-45f0-8df6-5e3735d39837","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 77.","contenido":"Las autoridades administrativas y jurisdiccionales en materia laboral deberán poner a disposición del \n público y mantener actualizada y accesible, la información de los sindicatos siguiente: \n I. Los documentos del registro de los sindicatos, que deberán contener, entre otros: \n a ) El domicilio; \n b ) Número de registro; \n c ) Nombre del sindicato; \n d ) Nombre de los integrantes del comité ejecutivo y comisiones que ejerzan funciones de vigilancia; \n e ) Fecha de vigencia del comité ejecutivo; \n f ) Número de socios; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 34 de 64 \n g ) Centro de trabajo al que pertenezcan, y \n h ) Central a la que pertenezcan, en su caso; \n II. Las tomas de nota; \n III. El estatuto; \n IV. Las actas de asamblea; \n V. Los reglamentos interiores de trabajo; \n VI . Los contratos colectivos, incluyendo el tabulador, convenios y las condiciones generales de trabajo, y \n VII. Todos los documentos contenidos en el Expediente de registro sindical y de contratos colectivos de \n trabajo. \n Las autoridades administrativas y juri sdiccionales en materia laboral deberán expedir copias de los documentos \n que obren en los expedientes de los registros a las personas solicitantes que los requieran, de conformidad con el \n procedimiento de acceso a la información. \n Por lo que se refiere a lo s documentos que obran en el expediente de registro de las asociaciones, únicamente \n estará clasificada como información confidencial, los domicilios de los trabajadores señalados en los padrones de \n socios.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":76},{"id":"20301ca3-ec9e-43b2-a69b-4511cdd879dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 78.","contenido":"Los sindicatos que reciban y ejerzan recursos públicos deberán mantener actualizada y accesible, de \n forma impresa para consulta directa y en los respectivos sitios de Internet, la información aplicable del artículo 65 de \n esta Ley, la señalada en el artículo anterior y la siguiente: \n I. Contrat os y convenios entre sindicatos y autoridades; \n II. El directorio del Comité Ejecutivo, y \n III. La relación detallada de los recursos públicos económicos, en especie, bienes o donativos que reciban \n y el informe detallado del ejercicio y destino final de los recursos públicos que ejerzan. \n Los sujetos obligados que asignen recursos públicos a los sindicatos, deberán habilitar un espacio en sus páginas \n de Internet para que estos cumplan con sus obligaciones de transparencia y dispongan de la infraestructura \n tecn ológica para el uso y acceso a la Plataforma Nacional. En todo momento el sindicato será el responsable de la \n publicación, actualización y accesibilidad de la información.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":77},{"id":"fcb8a1d7-e8e8-40b5-8fff-5f9dd9a0f401","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 79.","contenido":"Para determinar la información adicional que publicarán todos los sujet os obligados de manera \n obligatoria, las Autoridades garantes deberán: \n I. Solicitar a los sujetos obligados que, atendiendo a los lineamientos emitidos por el Sistema Nacional, \n remitan el listado de información que consideren de interés público; \n II. Revisar el listado que remitió el sujeto obligado con base en las funciones, atribuciones y \n competencias que las disposiciones jurídicas aplicables le otorguen, y \n III. Determinar el catálogo de información que el sujeto obligado deberá publicar como obligación de \n transparencia. \n Capítulo IV \n De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos \n o Ejercen Actos de Autoridad","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas","seccion_nombre":null,"orden":78},{"id":"05039906-df3f-449f-95ea-da0b8452f108","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 80.","contenido":"Las Autoridades garantes, determinarán los casos en que las personas físicas o m orales que reciban \n y ejerzan recursos públicos o realicen actos de autoridad, cumplirán con las obligaciones de transparencia y acceso a \n la información directamente o a través de los sujetos obligados que les asignen dichos recursos o, en los términos de \n l as disposiciones aplicables, realicen actos de autoridad. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 35 de 64 \n Los sujetos obligados correspondientes deberán enviar a las Autoridades garantes un listado de las personas \n físicas o morales a los que, por cualquier motivo, asignaron recursos públicos o, en los t érminos que establezcan las \n disposiciones aplicables, ejercen actos de autoridad. \n Para resolver sobre el cumplimento de lo señalado en el párrafo anterior, las Autoridades garantes tomarán en \n cuenta si realiza una función gubernamental, el nivel de financi amiento público, el nivel de regulación e \n involucramiento gubernamental y si el gobierno participó en su creación.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","seccion_nombre":null,"orden":79},{"id":"c037e2eb-3fdc-402e-802b-36890ac53d09","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 81.","contenido":"Para determinar la información que deberán hacer pública las personas físicas o morales que \n reciben y ejercen recursos públicos o realizan actos de autoridad, las Autoridades garantes deberán: \n I. Solicitar a las personas físicas o morales que, atendiendo a los lineamientos emitidos por el Sistema \n Nacional, remitan el listado de información que consideren de interés público; \n II. Rev isar el listado que remitió la persona física o moral en la medida en que reciban y ejerzan recursos \n o realicen actos de autoridad que las disposiciones jurídicas aplicables le otorguen, y \n III. Determinar las obligaciones de transparencia que deben cumpli r y los plazos para ello. \n Capítulo V \n De las Obligaciones Específicas en Materia Energética","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","seccion_nombre":null,"orden":80},{"id":"0bed4857-5e6f-4a34-88f7-21959d199e4f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 82.","contenido":"Los sujetos obligados del sector energético, además de la información señalada en el artículo 65 de \n esta Ley, deberán poner a disposición del público y, en su caso, mantener actualizada la siguiente información: \n I. La Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector \n Hidrocarburos: \n a ) Los Sistemas de Administración de Seguridad Industrial, Seguridad Operativa y Protecci ón al \n Medio Ambiente establecidos en la Ley de la Agencia Nacional de Seguridad Industrial y de \n Protección al Medio Ambiente del Sector Hidrocarburos; \n b ) El código de conducta de su personal; \n c ) Los planes, lineamientos y procedimientos para prevenir y ate nder situaciones de emergencia; \n d ) Las autorizaciones en materia de impacto y riesgo ambiental del sector hidrocarburos, incluyendo \n los anexos; \n e ) Las autorizaciones para emitir olores, gases o partículas sólidas o líquidas a la atmósfera por las \n Instalaci ones del sector hidrocarburos; \n f ) Las autorizaciones en materia de residuos peligrosos en el sector hidrocarburos; \n g ) Las autorizaciones de las propuestas de remediación de sitios contaminados y la liberación de los \n mismos al término de la ejecución del pr ograma de remediación correspondiente; \n h ) Las autorizaciones en materia de residuos de manejo especial; \n i ) El registro de planes de manejo de residuos y programas para la instalación de sistemas \n destinados a su recolección, acopio, almacenamiento, transpor te, tratamiento, valorización y \n disposición final; \n j ) Las autorizaciones de cambio de uso del suelo en terrenos forestales; \n k ) Los permisos para la realización de actividades de liberación al ambiente de organismos \n genéticamente modificados para bio r remedi ación de sitios contaminados con hidrocarburos; \n l ) Las disposiciones, emitidas en el ámbito de sus atribuciones, para los asignatarios, \n permisionarios y contratistas; \n m ) Los procedimientos para el registro, investigación y análisis de incidentes y accident es; \n n ) Los estándares técnicos nacionales e internacionales en materia de protección al medio \n ambiente; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 36 de 64 \n o ) Las coberturas financieras contingentes frente a daños o perjuicios que se pudieran generar; \n p ) Las previsiones a que deberá sujetarse la operación d e fuentes fijas donde se desarrollen \n actividades del sector que emitan contaminantes atmosféricos; \n q ) Las especificaciones y los requisitos del control de emisiones de contaminantes procedentes de \n las fuentes fijas del sector hidrocarburos; \n r ) El pago de v iáticos y pasajes, viajes, servicios, financiamiento o aportaciones económicas que se \n relacionen directa o indirectamente con el ejercicio de sus atribuciones o funciones; \n s ) Los recursos depositados en los fideicomisos que se generen derivado del saldo re manente de \n los ingresos propios excedentes, así como el uso y destino de los mismos; \n t ) Los registros de las audiencias celebradas, que deberán contener el lugar, fecha y hora de inicio \n y conclusión de las mismas, así como los nombres completos de las pers onas que estuvieron \n presentes y los temas tratados; \n u ) Los volúmenes de uso de agua, la situación geográfica y todos los productos químicos utilizados \n en el fluido de fracturación por pozo, del sector hidrocarburos; \n v ) Los volúmenes de agua de desecho recu perada por pozo, los volúmenes de agua inyectados en \n los pozos de aguas residuales y las emisiones de metano a la atmósfera por pozo, del sector \n hidrocarburos; \n w ) Los programas de manejo de agua utilizada en la fracturación hidráulica, y \n x ) Las acciones de seguridad industrial y de seguridad operativa para el control de residuos, y la \n instalación de sistemas destinados a su recolección, acopio, almacenamiento, transporte, \n tratamiento, valorización y disposición final; \n II. La dependencia encargada de conduci r y supervisar la política energética del país: \n a ) Información estadística sobre la producción de hidrocarburos y el total de las reservas, \n incluyendo reportes de estimación y estudios de evaluación o cuantificación y certificación; \n b ) Los criterios utiliz ados para la contratación y términos contractuales del comercializador de \n hidrocarburos del Estado; \n c ) La relación entre producción de hidrocarburos y reservas totales, así como la información sobre \n los recursos contingentes y prospectivos; \n d ) La informaci ón geológica, geofísica, petrofísica, petroquímica y demás, que se obtenga de las \n actividades de reconocimiento y exploración superficial, así como de la exploración y extracción \n de hidrocarburos en todo el territorio nacional, terrestre y marino, siempre y cuando no tenga el \n carácter de confidencial en términos de la Ley del Sector Hidrocarburos; \n e ) La información relativa a los contratos para la exploración y extracción incluyendo las cláusulas, \n los resultados y estadísticas de los procesos de licitación, las bases y reglas de los procesos de \n licitación que se hayan empleado para adjudicar dichos contratos y el número de los contratos \n que se encuentran; \n f ) La información relacionada con la administración técnica, costos y supervisión de los contratos y \n el volumen de producción de hidrocarburos por Contrato o asignación; \n g ) Los criterios utilizados para la selección del socio de Petróleos Mexicanos u otra empresa pública \n del Estado, tratándose de la migración de una asignación a un contrato de exploración y \n extracción de hidrocarburos, en términos de la Ley del Sector Hidrocarburos; \n h ) Los volúmenes de producción por tipo de hidrocarburo, desagregados por activo, área contractual \n y asignación, y campo; \n i ) El volumen y las especificaciones de calidad del petró leo, gas natural, petrolíferos y \n petroquímicos transportados y almacenados en los sistemas permisionados, incluido el Sistema \n de Transporte y Almacenamiento Nacional Integrado de Gas Natural; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 37 de 64 \n j ) Lista de los permisionarios que importen petróleo, gas natura l y petrolíferos, el volumen y \n especificaciones de calidad de los mismos, el permisionario encargado de la importación y el \n destino de su comercialización; \n k ) Los resultados y estadísticas de las actividades de los gestores de sistemas integrados; \n l ) La ca pacidad utilizada y disponible en las instalaciones de almacenamiento y sistemas de ductos \n de los permisionarios; \n m ) Las estadísticas relacionadas con el transporte, el almacenamiento, la distribución y el expendio \n al público de gas natural, petrolíferos y petroquímicos, a nivel nacional; \n n ) El número de permisos y autorizaciones que haya otorgado y se encuentren vigentes, así como \n sus términos y condiciones, en su caso; \n o ) La energía eléctrica transportada y distribuida en la Red Nacional de Transmisión y en las Redes \n Generales de Distribución; \n p ) Los contratos que versen sobre el uso, goce o afectación de terrenos, bienes o derechos \n necesarios para realizar el Servicio Público de Transmisión y Distribución de Energía Eléctrica y \n para la construcción de pla ntas de generación de energía eléctrica; \n q ) Los niveles de generación de energía eléctrica; \n r ) La información de permisos en materia de importación y exportación de energía eléctrica, y \n s ) Las bases del mercado eléctrico; \n III. Las empresas públicas del Est ado y sus empresas públicas subsidiarias: \n a ) La información relacionada con el procedimiento y la designación de los consejeros y directivos \n de las filiales y subsidiarias; \n b ) Las donaciones o cualquier aportación que realice la Comisión Federal de Electri cidad o \n Petróleos Mexicanos, así como sus empresas subsidiarias, a personas físicas o morales, \n cualquiera que sea su naturaleza jurídica o su objeto, con excepción de aquellas cuya divulgación \n pueda afectar una ventaja competitiva de la empresa pública del Estado, sus empresas públicas \n subsidiarias o sus empresas filiales; \n c ) La versión pública de su Plan de Negocios; \n d ) El contrato colectivo de trabajo y el reglamento del personal de confianza; \n e ) Los tabuladores aprobados, desglosando todos los conceptos y montos de las percepciones \n ordinarias y extraordinarias; \n f ) Las erogaciones globales que realicen por concepto de jubilaciones y pensiones, así como las \n actualizaciones del costo actuarial de su pasivo laboral; \n g ) Los préstamos o créditos, así como las t asas aplicables, que en su caso otorguen a sus \n trabajadores, jubilados y pensionados; \n h ) Los apoyos para el desempeño de la función y las demás erogaciones que, en su caso, se \n otorguen a los trabajadores, que no forman parte de su remuneración; \n i ) Los mont os mensuales erogados por contrataciones temporales o eventuales; \n j ) Los lineamientos aprobados por los Consejos de Administración de la Comisión Federal de \n Electricidad y de Petróleos Mexicanos, con base en los cuales se otorgan y cubran los conceptos \n des critos en los incisos anteriores; \n k ) Los montos erogados en el trimestre que corresponda por cada uno de los conceptos descritos \n en los incisos e) a i) anteriores; \n l ) Las garantías o cualquier otro instrumento financiero necesario para contar con cobertura s \n financieras contingentes frente a daños o perjuicios que se pudieran generar por sus actividades; \n m ) Los estándares, funciones y responsabilidades de los encargados de los Sistemas de \n Administración de Seguridad Industrial, Seguridad Operativa y Protecci ón al Medio Ambiente, así \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 38 de 64 \n como la información que comprende el artículo 13 de la Ley de la Agencia Nacional de Seguridad \n Industrial y de Protección al Medio Ambiente del Sector Hidrocarburos; \n n ) Respecto a sus filiales: \n 1. Las inversiones realizadas por pa rte de la empresa pública o sus subsidiarias; \n 2. El monto de las utilidades y dividendos recibidos, y \n 3. Las actas constitutivas y actas de las reuniones de consejo en las que participan, sin \n importar su participación accionaria; \n o ) La deuda que adquieran las empresas públicas del Estado, y \n p ) Las bases, reglas, ingresos, costos, límites de costos, contraprestaciones, contribuciones y pagos \n realizados y de los procedimientos que lleve a cabo cuando celebren con las personas \n particulares o entre ellas, contr atos, asignaciones, permisos, alianzas, sociedades y demás actos \n en materia de las actividades de planeación y control del sistema eléctrico nacional; del servicio \n público de transmisión y distribución de energía eléctrica; y de exploración y extracción de \n hidrocarburos. Lo anterior, siempre y cuando no se trate de información que implique secreto \n comercial o cuya divulgación pudiera representarles una desventaja competitiva frente a sus \n competidores; \n IV. El Fondo Mexicano del Petróleo para la Estabilizació n y el Desarrollo: \n a ) Las transferencias realizadas a la Tesorería de la Federación y a los fondos señalados en el \n Capítulo III de la Ley del Fondo Mexicano del Petróleo para la Estabilización y el Desarrollo; \n b ) El monto de los honorarios fiduciarios paga dos por el Fondo, así como los conceptos y pagos \n realizados por el fiduciario con cargo a dichos honorarios; \n c ) El monto de los pagos realizados al comercializador del Estado de cada contrato de extracción de \n hidrocarburos a que se refiere la Ley de Ingres os sobre Hidrocarburos, y \n d ) El total de los ingresos derivados de asignaciones y contratos para la exploración y extracción de \n hidrocarburos, y \n V. La Secretaría de Energía: \n a ) Los lineamientos a que deberá sujetarse la adquisición, uso, goce o afectación de terrenos, \n bienes o derechos que se pacten entre propietarios o titulares y los asignatarios o contratistas, \n para realizar las actividades de exploración y extracción de hidrocarburos; \n b ) Los dictámenes técnicos que sustenten el establecimiento de zonas de salvaguarda en términos \n de la Ley del Sector Hidrocarburos; \n c ) Los dictámenes que sustenten la instrucción para unificar campos o yacimientos nacionales de \n extracción de hidrocarburos; \n d ) La información relativa a los procedimientos de consulta previa, libre e informada necesarios para \n tomar en cuenta los intereses y derechos de los pueblos y comunidades indígenas y \n afromexicanas en los que se desarrollen proyectos de la industria eléctrica y de los \n hidrocarburos, así como en materia de energía geotérmic a; \n e ) Los lineamientos técnicos conforme a los cuales se deberán realizar las licitaciones para \n seleccionar al socio de las empresas públicas del Estado en los casos de asignaciones que \n migren a contratos para la exploración y extracción de hidrocarburos; \n f ) Los permisos de exploración y las concesiones de explotación de recursos geotérmicos, y \n g ) La meta de generación limpia de electricidad. \n Capítulo VI \n De la Verificación de las Obligaciones de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De las Obligaciones Específicas en Materia Energética","seccion_nombre":null,"orden":81},{"id":"d8c2da33-425d-49a3-b27d-13f575f876ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   83.","contenido":"Las Autoridades garantes, en su ámb ito de competencia, vigilarán que las obligaciones de \n transparencia que publiquen los sujetos obligados cumplan con lo dispuesto en esta Ley. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 39 de 64","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"orden":82},{"id":"0a946132-85ae-49e1-b956-099a596203bb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 84.","contenido":"Las determinaciones que emitan las Autoridades garantes deberán establecer los requerimientos, \n recome ndaciones u observaciones que formulen y los términos y plazos en los que los sujetos obligados deberán \n atenderlas. El incumplimiento a los requerimientos formulados, será motivo para aplicar las medidas de apremio, sin \n perjuicio de las sanciones a que hay a lugar.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"orden":83},{"id":"15de49c0-3c48-467e-a72d-6fb446296955","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 85.","contenido":"Las Autoridades garantes vigilarán el debido cumplimiento a las obligaciones de transparencia que \n publiquen los sujetos obligados con lo dispuesto en los artículos 63 a 80 de esta Ley y demás disposiciones jurídicas \n aplicables. \n Artícu lo 86. Las acciones de vigilancia a que se refiere este Capítulo se realizarán de manera oficiosa por las \n Autoridades garantes, a través de la revisión aleatoria o muestral y periódica al portal de Internet de los sujetos \n obligados o a la Plataforma Nacion al.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"orden":84},{"id":"38c70ed4-52d2-4bc8-98de-fb5ea0be5499","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 87.","contenido":"La verificación que realice las Autoridades garantes se sujetará a lo siguiente: \n I. Constatar que la información esté completa, publicada y actualizada en tiempo y forma; \n II. Emitir un dictamen en el que podrá determinar que el sujeto obli gado cumple o no con lo establecido \n por esta Ley y demás disposiciones. En el supuesto de que determine que no da cumplimiento \n formulará los requerimientos que procedan a efecto de que el sujeto obligado subsane las \n inconsistencias detectadas e informe la atención a los requerimientos dentro de un plazo no mayor a \n veinte días, y \n III. Verificar el cumplimiento a la resolución una vez transcurrido el plazo y si considera que fueron \n atendidos los requerimientos del dictamen, emitirá un acuerdo de cumplimiento. \n Las Autoridades garantes podrán solicitar los informes complementarios al sujeto obligado que requiera para \n allegarse de los elementos de juicio que consideren necesarios para llevar a cabo la verificación. \n Cuando las Autoridades garantes consideren que e xiste un incumplimiento total o parcial de la determinación, le \n notificará, por conducto de la Unidad de Transparencia, al superior jerárquico de la persona servidora pública \n responsable de dar cumplimiento, para el efecto de que, en un plazo no mayor a di ez días, dé cumplimiento a los \n requerimientos del dictamen. \n En caso de que las Autoridades garantes consideren que subsiste el incumplimiento total o parcial de la \n resolución, en un plazo no mayor a cinco días impondrán las medidas de apremio o sanciones, conforme a lo \n establecido por esta Ley. \n Adicionalmente, las Autoridades garantes podrán emitir recomendaciones a los sujetos obligados, a fin de \n procurar que los formatos en que se publique la información, sea de mayor utilidad. \n Capítulo VII \n De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"orden":85},{"id":"0099e4bb-3397-4e76-bd8a-e73374459f7e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 88.","contenido":"Cualquier persona podrá denunciar ante las Autoridades garantes la falta de publicación de las \n obligaciones de transparencia previstas en los artículos 63 a 80 de esta Ley y demás disposi ciones jurídicas \n aplicables, en sus respectivos ámbitos de competencia.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":86},{"id":"3c6f6682-8977-4650-b1f1-f2bdf0ed32f9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 89.","contenido":"El procedimiento de la denuncia se integra por las siguientes etapas: \n I. Presentación de la denuncia ante las Autoridades garantes; \n II. Solicitud por parte de las Autorida des garantes de un informe al sujeto obligado; \n III. Resolución de la denuncia, y \n IV. Ejecución de la resolución de la denuncia.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":87},{"id":"09589150-7cd4-4c82-9697-ddc0d0e05364","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 90.","contenido":"La denuncia por incumplimiento a las obligaciones de transparencia deberá cumplir, al menos, los \n siguientes requisi tos: \n I. Nombre del sujeto obligado denunciado; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 40 de 64 \n II. Descripción clara y precisa del incumplimiento denunciado; \n III. La persona denunciante podrá adjuntar los medios de prueba que estime necesarios para respaldar el \n incumplimiento denunciado; \n IV. En caso de que la denuncia se presente: \n a ) Por escrito, la persona denunciante deberá señalar el domicilio en la jurisdicción que corresponda \n o la dirección de correo electrónico para recibir notificaciones, y \n b ) Por medios electrónicos, se entenderá que se acepta qu e las notificaciones se efectúen por el \n mismo medio en el que la presento. En caso de que no se señale domicilio o dirección de correo \n electrónico o se señale un domicilio fuera de la jurisdicción respectiva, las notificaciones, aún las \n de carácter persona l, se practicarán a través de los estrados físicos de la Autoridad garante \n competente, y \n V. Opcionalmente el nombre de la persona denunciante.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":88},{"id":"f6e463f2-caff-4569-8e42-87d67fb0acb2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 91.","contenido":"La denuncia podrá presentarse de la forma siguiente: \n I. Por medio electrónico: \n a ) A través de la Pla taforma Nacional, o \n b ) Por correo electrónico, dirigido a la dirección electrónica que al efecto se establezca, o \n II. Por escrito libre, presentado físicamente, ante la Unidad de Transparencia de las Autoridades \n garantes, según corresponda.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":89},{"id":"3c50426b-d511-4c0a-8284-ff4092a37811","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 92.","contenido":"La s Autoridades garantes pondrán a disposición de las personas particulares el formato de denuncia \n correspondiente, a efecto de que estos, si así lo deciden, puedan utilizarlos. Asimismo, las personas particulares \n podrán optar por un escrito libre, conforme a lo previsto en esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":90},{"id":"b1f35da0-2cbf-400b-940f-ad2ce756daa1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 93.","contenido":"Las Autoridades garantes, en el ámbito de sus competencias, deben resolver sobre la admisión de la \n denuncia, dentro de los tres días siguientes a su recepción.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":91},{"id":"902470b6-cf90-4e5d-acd9-e3f23e3bca90","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 94.","contenido":"Las Autoridades garantes podrán prevenir a la persona denunciante dentro del plazo de tres días \n contados a partir del día hábil siguiente al de su recepción, para que en el plazo de tres días subsane lo siguiente: \n I. En su caso, exhiba ante la Autoridad garante los documentos con los que acredite l a personalidad del \n representante de una persona física o moral, en caso de aplicar, o \n II. Aclare o precise alguno de los requisitos o motivos de la denuncia. \n En el caso de que no se desahogue la prevención en el periodo establecido para tal efecto en este artículo, \n deberá desecharse la denuncia, dejando a salvo los derechos de la persona denunciante para volver a presentar la \n misma.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":92},{"id":"1a527205-6c03-43a1-a978-d038c7687ee9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   95.","contenido":"Las Autoridades garantes podrán determinar la improcedencia de la denuncia cuando el \n incumplimiento hubiera sido objeto de una denuncia anterior en la que se resolvió instruir la publicación de las \n obligaciones de transparencia previstas en la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":93},{"id":"19eb45d4-3910-49a2-b5b7-1e8b86050fa1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 96.","contenido":"Si la denuncia no versa sobre presuntos incumplimientos a las obligaciones de transparencia \n establ ecidas en la presente Ley, o se refiere al ejercicio del derecho de acceso a la información o al trámite del \n recurso de revisión, la Autoridad garante dictará un acuerdo de desechamiento y, en su caso, dejará a salvo los \n derechos de la persona promovente p ara que los haga valer por la vía y forma correspondientes. \n Las Autoridades garantes, en el ámbito de sus competencias, deben notificar al sujeto obligado la denuncia \n dentro de los siete días siguientes a su admisión. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 41 de 64","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":94},{"id":"1c9978bf-764b-4a27-a391-0337f808ad37","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 97.","contenido":"El sujeto obligado debe e nviar a las Autoridades garantes correspondientes, un informe con \n justificación respecto de los hechos o motivos de la denuncia dentro de los cinco días siguientes a la notificación \n anterior. \n Las Autoridades garantes, pueden realizar las verificaciones vir tuales que procedan, así como solicitar los \n informes complementarios al sujeto obligado que requiera, para allegarse de los elementos de juicio que considere \n necesarios para resolver la denuncia. \n En el caso de informes complementarios, el sujeto obligado d eberá responder a los mismos, en el término de tres \n días siguientes a la notificación correspondiente.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":95},{"id":"4d64a9f3-499a-4151-88b0-cbcdb201094e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 98.","contenido":"Las Autoridades garantes, en el ámbito de sus competencias deben resolver la denuncia, dentro de \n los veinte días siguientes al término del p lazo en que el sujeto obligado debe presentar su informe o, en su caso, los \n informes complementarios. \n La resolución debe ser fundada y motivada e invariablemente debe pronunciarse sobre el cumplimiento de la \n publicación de la información por parte del suje to obligado. \n De existir incumplimiento, se deberá señalar el artículo y fracción de la presente Ley, así como los preceptos \n contenidos en las disposiciones jurídicas aplicables que se incumplen, especificar los criterios y metodología del \n estudio y las raz ones por las cuales se considera que hay un incumplimiento, y establecer las medidas necesarias \n para garantizar la publicidad de la información respecto de la cual exista un incumplimiento, determinando así un \n plazo para que el sujeto obligado cumpla e inf orme sobre ello.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":96},{"id":"223ec517-42d5-46c7-afda-c399cf0195b8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 99.","contenido":"Las Autoridades garantes, en el ámbito de sus competencias, deben notificar la resolución a la \n persona denunciante y al sujeto obligado, dentro de los tres días siguientes a su emisión. \n Las resoluciones que emitan las Autorida des garantes, a que se refiere este Capítulo, son definitivas e \n inatacables para los sujetos obligados. \n El particular podrá impugnar la resolución por la vía del juicio de amparo que corresponda, en los términos de la \n legislación aplicable. Los juicios de amparo serán sustanciados por jueces y tribunales especializados que para el \n efecto determine el Órgano de Administración Judicial en los términos del artículo 94 de la Constitución Política de \n los Estados Unidos Mexicanos. \n El sujeto obligado deberá cumpli r con la resolución en un plazo de quince días, a partir del día siguiente al en que \n se le notifique la misma.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":97},{"id":"d5f99988-ca39-402c-9522-427d60642db1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 100.","contenido":"Transcurrido el plazo señalado en el artículo anterior, el sujeto obligado deberá informar a la \n Autoridad garante correspondiente s obre el cumplimento de la resolución. \n Las Autoridades garantes verificarán el cumplimiento a la resolución; si fuera procedente se emitirá un acuerdo de \n cumplimiento y se ordenará el cierre del Expediente. \n Cuando las Autoridades garantes consideren que exi ste un incumplimiento total o parcial de la resolución, le \n notificarán, por conducto de la Unidad de Transparencia del sujeto obligado, al superior jerárquico de la persona \n servidora pública responsable de dar cumplimiento, para el efecto de que, en un pla zo no mayor a siete días, se dé \n cumplimiento a la resolución.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":98},{"id":"3e2d9e8b-a17e-43e3-9fda-5601c8819a3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 101.","contenido":"En caso de que las Autoridades garantes consideren que subsiste el incumplimiento total o parcial \n de la resolución, en un plazo no mayor a cinco días posteriores al aviso de incump limiento al superior jerárquico de la \n persona servidora pública responsable del mismo, se emitirá un acuerdo de incumplimiento y, en su caso, se \n impondrán las medidas de apremio o determinaciones que resulten procedentes. \n TÍTULO SEXTO \n INFORMACIÓN CLASIFICA DA \n Capítulo I \n De las Disposiciones Generales de la Clasificación y Desclasificación de la Información \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 42 de 64","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"orden":99},{"id":"f0f851a1-7f13-4c8e-b757-670d4dbbe4dc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 102.","contenido":"La clasificación es el proceso mediante el cual el sujeto obligado determina que la información en \n su poder, actualiza alguno de los supuest os de reserva o confidencialidad, de conformidad con lo dispuesto en el \n presente Título. \n Los supuestos de reserva o confidencialidad previstos en las leyes deberán ser acordes con las bases, principios \n y disposiciones establecidos en esta Ley y, en ningún caso, podrán contravenirla. \n Las personas titulares de las áreas de los sujetos obligados serán los responsables de clasificar la información, \n de conformidad con lo dispuesto en la presente Ley y leyes de las entidades federativas. \n Los sujetos obligados deb erán aplicar, de manera restrictiva y limitada, las excepciones al derecho de acceso a la \n información previstas en el presente Título y deberán acreditar su procedencia, sin ampliar las excepciones o \n supuestos de reserva o confidencialidad previstos en las leyes, de conformidad con lo establecido en esta Ley. \n Los sujetos obligados no podrán emitir acuerdos de carácter general ni particular que clasifiquen documentos o \n expedientes como reservados, ni clasificar documentos antes de dar respuesta a una solicit ud de acceso a la \n información. La clasificación podrá establecerse de manera parcial o total de acuerdo al contenido de la información \n del Documento y deberá estar acorde con la actualización de los supuestos definidos en el presente Título como \n informació n clasificada. \n La clasificación de información reservada se realizará conforme a un análisis caso por caso, mediante la \n aplicación de la prueba de daño.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":100},{"id":"99092ec8-2303-408d-b85f-22ea46006149","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 103.","contenido":"La clasificación de la información se llevará a cabo en el momento en que: \n I. Se reciba u na solicitud de acceso a la información; \n II. Se determine mediante resolución de autoridad competente, o \n III. Se generen versiones públicas para dar cumplimiento a las obligaciones de transparencia previstas en \n esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":101},{"id":"835cbfae-ac55-4f11-b1e6-eb8bbdfd8ade","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 104.","contenido":"Los Documentos clasif icados como reservados serán públicos cuando: \n I. Se extingan las causas que dieron origen a su clasificación; \n II. Expire el plazo de clasificación; \n III. Exista resolución de una autoridad competente que determine que existe una causa de interés público \n que prevalece sobre la reserva de la información; \n IV. El Comité de Transparencia considere pertinente la desclasificación, de conformidad con lo señalado \n en el presente Título, y \n V. Se trate de información que esté relacionada con violaciones graves a derecho s humanos o delitos de \n lesa humanidad. \n La información clasificada como reservada de conformidad con el artículo 112 de esta Ley podrá permanecer con \n tal carácter hasta por un periodo de cinco años. El periodo de reserva correrá a partir de la fecha en que se clasifica \n el documento. \n Excepcionalmente, los sujetos obligados, con la aprobación de su Comité de Transparencia, podrán ampliar el \n periodo de reserva hasta por un plazo de cinco años adicionales, siempre y cuando justifiquen que subsisten las \n causas qu e dieron origen a su clasificación, mediante la aplicación de una prueba de daño. \n Para los casos previstos por la fracción II de este artículo, cuando se trate de información cuya publicación pueda \n ocasionar la destrucción o inhabilitación de la infraestru ctura de carácter estratégico para la provisión de bienes o \n servicios públicos, o bien se refiera a las circunstancias expuestas en la fracción IV del artículo 112 de esta Ley y que \n a juicio de un sujeto obligado sea necesario ampliar nuevamente el periodo de reserva de la información, el Comité \n de Transparencia respectivo deberá hacer la solicitud correspondiente a la Autoridad garante, debidamente fundada \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 43 de 64 \n y motivada, aplicando la prueba de daño y señalando el plazo de reserva, por lo menos con tres meses de \n anticipación al vencimiento del periodo.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":102},{"id":"8a17ec89-d891-4b24-b420-26970d432f34","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   105.","contenido":"Cada área del sujeto obligado elaborará un índice de los expedientes clasificados como \n reservados, por Área responsable de la información y tema. \n El índice deberá elaborarse semestralmente y publica rse en Formatos Abiertos al día siguiente de su elaboración. \n Dicho índice deberá indicar el Área que generó la información, el nombre del Documento, si se trata de una reserva \n completa o parcial, la fecha en que inicia y finaliza la reserva, su justificaci ón, el plazo de reserva y, en su caso, las \n partes del Documento que se reservan y si se encuentra en prórroga. \n En ningún caso el índice será considerado como información reservada.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":103},{"id":"295358b8-b004-4b6f-a5dd-05239035ff08","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 106.","contenido":"En los casos en que se niegue el acceso a la información, por actualizarse alguno de los supuestos \n de clasificación, el Comité de Transparencia deberá confirmar, modificar o revocar la decisión. \n Para motivar la clasificación de la información y la ampliación del plazo de reserva, se deberán señalar las \n razones, moti vos o circunstancias especiales que llevaron al sujeto obligado a concluir que el caso particular se \n ajusta al supuesto previsto por la norma legal invocada como fundamento. Además, el sujeto obligado deberá, en \n todo momento, aplicar una prueba de daño. \n Tr atándose de aquella información que actualice los supuestos de clasificación, deberá señalarse el plazo al que \n estará sujeto la reserva.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":104},{"id":"26a2525c-e30c-48da-bafa-9248840684df","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 107.","contenido":"En la aplicación de la prueba de daño, el sujeto obligado deberá justificar que: \n I. La divulgación de la información representa un riesgo real, demostrable e identificable de perjuicio \n significativo al interés público o a la seguridad nacional; \n II. El riesgo de perjuicio que supondría la divulgación supera el interés público general de que se difunda, \n y \n III. La limitación se adecua al principio de proporcionalidad y representa el medio menos restrictivo \n disponible para evitar el perjuicio.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":105},{"id":"b81170f0-422b-439e-abb3-3dee1171c48c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 108.","contenido":"Los sujetos obligados deberán aplicar, de manera restrictiva y limitada, las excepciones al derecho \n de acces o a la información prevista en el presente Título y deberán acreditar su procedencia. \n La carga de la prueba para justificar toda negativa de acceso a la información, por actualizarse cualquiera de los \n supuestos de reserva previstos, corresponderá a los suj etos obligados.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":106},{"id":"2c860f87-ccbd-4f67-b122-9eaabb569140","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 109.","contenido":"Los Documentos clasificados parcial o totalmente deberán llevar una leyenda que indique tal \n carácter, la fecha de la clasificación, el fundamento legal y, en su caso, el periodo de reserva.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":107},{"id":"2f0359de-e818-4129-b5f0-e8894f795a65","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 110.","contenido":"Los lineamientos gener ales que emita el Sistema Nacional en materia de clasificación de la \n información reservada y confidencial y, para la elaboración de versiones públicas, serán de observancia obligatoria \n para los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":108},{"id":"5d35a148-81a9-415b-8dda-378cfaf6d9cb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 111.","contenido":"Los Documentos clasificados s erán debidamente custodiados y conservados, conforme a las \n disposiciones aplicables y, en su caso, a los lineamientos que expida el Sistema Nacional. \n Capítulo II \n De la Información Reservada","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":109},{"id":"31493012-65cb-4fcd-8aa8-21526c29ae47","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 112.","contenido":"Como información reservada podrá clasificarse aquell a cuya publicación: \n I. Comprometa la seguridad nacional, la seguridad pública, la defensa nacional o la paz social; \n II. Pueda menoscabar la conducción de las negociaciones y relaciones internacionales; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 44 de 64 \n III. Se entregue al Estado mexicano expresamente con e se carácter o el de confidencial por otro u otros \n sujetos de derecho internacional, excepto cuando se trate de violaciones graves de derechos humanos \n o delitos de lesa humanidad de conformidad con el derecho internacional; \n IV. Pueda afectar la efectividad de las medidas adoptadas en relación con las políticas en materia \n monetaria, cambiaria o del sistema financiero del país; pueda poner en riesgo la estabilidad de las \n instituciones financieras susceptibles de ser consideradas de riesgo sistémico o del siste ma financiero \n del país, pueda comprometer la seguridad en la provisión de moneda nacional al país, o pueda \n incrementar el costo de operaciones financieras que realicen los sujetos obligados del sector público \n federal; \n V. Pueda poner en riesgo la vida, segu ridad o salud de una persona física; \n VI. Obstruya las actividades de verificación, inspección y auditoría relativas al cumplimiento de las leyes o \n afecte la recaudación de contribuciones; \n VII. Pueda causar daño u obstruya la prevención o persecución de los delitos, altere el proceso de \n investigación de las carpetas de investigación, afecte o vulnere la conducción o los derechos del \n debido proceso en tanto no hayan quedado firmes o afecte la administración de justicia o la seguridad \n de una persona denunciant e, querellante o testigo, así como sus familias, en los términos de las \n disposiciones jurídicas aplicables; \n VIII. La que contenga las opiniones, recomendaciones o puntos de vista que formen parte del proceso \n deliberativo de las personas servidoras públicas , hasta en tanto no sea adoptada la decisión definitiva, \n la cual deberá estar documentada; \n IX. Obstruya los procedimientos para fincar responsabilidad a las personas servidoras públicas, en tanto la \n resolución administrativa no haya causado estado; \n X. Afec te los derechos del debido proceso; \n XI. Afecte o vulnere la conducción de los expedientes judiciales o de los procedimientos administrativos \n seguidos en forma de juicio, incluidos los de denuncias, inconformidades, responsabilidades \n administrativas y resar citorias o afecte la administración de justicia o la seguridad de una persona \n denunciante, querellante o testigo, así como sus familias, en los términos de las disposiciones jurídicas \n aplicables en tanto no hayan causado estado; \n XII. Se encuentre contenida dentro de las investigaciones de hechos que la ley señale como delitos y se \n tramiten ante el Ministerio Público; \n XIII. El daño que pueda producirse con la publicación de la información sea mayor que el interés público de \n conocer la información de referenc ia, siempre que esté directamente relacionado con procesos o \n procedimientos administrativos o judiciales que no hayan quedado firmes; \n XIV. Cuando se trate de información sobre estudios y proyectos cuya divulgación pueda causar daños al \n interés del Estado o suponga un riesgo para su realización, siempre que esté directamente relacionado \n con procesos o procedimientos administrativos o judiciales que no hayan quedado firmes; \n XV. Se refiera a programas del Gobierno Federal para salvaguardar materiales o instala ciones nucleares; \n XVI. Ponga en riesgo el funcionamiento o integridad de los sistemas tecnológicos, energéticos, espaciales, \n satelitales, de telecomunicaciones o de defensa desarrollados, adquiridos u operados por el Gobierno \n Federal de forma directa o ind irecta, así como instalaciones, infraestructuras, proyectos, planes o \n servicios de protección estratégicos, prioritarios o de defensa, y \n XVII. Las que por disposición expresa de una ley tengan tal carácter, siempre que sean acordes con las \n bases, principio s y disposiciones establecidos en esta Ley y no la contravengan; así como las previstas \n en tratados internacionales.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Reservada","seccion_nombre":null,"orden":110},{"id":"75823113-bf62-44c7-9aeb-c1d0b2e4e40e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 113.","contenido":"Las causales de reserva previstas en el artículo anterior se deberán fundar y motivar, a través de la \n aplicación de la prueba de daño a la que se hace referencia en el presente Título.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Reservada","seccion_nombre":null,"orden":111},{"id":"2ef2dc4f-9019-4595-89a2-6a282c9f0b59","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 114.","contenido":"No podrá invocarse el carácter de reservado cuando: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 45 de 64 \n I. Se trate de violaciones graves de derechos humanos o delitos de lesa humanidad, o \n II. Se trate de información relacionada con a ctos de corrupción acreditados de acuerdo con las leyes \n aplicables. \n Capítulo III \n De la Información Confidencial","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Reservada","seccion_nombre":null,"orden":112},{"id":"2e58f1cf-436a-4288-99a7-d090bea60b79","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 115.","contenido":"Se considera información confidencial la que contiene datos personales concernientes a una \n persona física identificada o identific able. \n La información confidencial no estará sujeta a temporalidad alguna y sólo podrán tener acceso a ella los titulares \n de la misma, sus representantes y las personas servidoras públicas facultadas para ello. \n Se considera como información confidencial de personas físicas o morales: los secretos bancario, fiduciario, \n industrial, comercial, fiscal, bursátil y postal, cuya titularidad corresponda a las personas particulares, sujetos de \n derecho internacional o a sujetos obligados cuando no involucren el ejerci cio de recursos públicos. \n Asimismo, será información confidencial aquella que presenten las personas particulares a los sujetos obligados, \n siempre que tengan el derecho a ello, de conformidad con lo dispuesto por las leyes o los tratados internacionales. \n S e considera confidencial el pronunciamiento sobre la existencia o inexistencia de quejas, denuncias y/o \n procedimientos administrativos seguidos en contra de personas servidoras públicas y particulares que se encuentren \n en trámite o no hayan concluido con u na sanción firme.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":113},{"id":"bddf3c10-f247-4e85-9ad8-9098d9f029a3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 116.","contenido":"Los sujetos obligados que se constituyan como fideicomitentes, fideicomisarios o fiduciarios en \n fideicomisos que involucren recursos públicos, no podrán clasificar, por ese solo supuesto, la información relativa al \n ejercicio de estos, como secreto bancario o fiduciario, sin perjuicio de las demás causales de clasificación que prevé \n la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":114},{"id":"4b8491df-fb2c-497e-b130-0b4b985666c3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 117.","contenido":"Los sujetos obligados que se constituyan como personas usuarias o como institución bancaria en \n operaciones que invo lucren recursos públicos, no podrán clasificar, por ese solo supuesto, la información relativa al \n ejercicio de estos, como secreto bancario, sin perjuicio de las demás causales de clasificación que prevé la presente \n Ley.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":115},{"id":"96569f33-bf2e-43e8-9723-6bed033ed38f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 118.","contenido":"Los sujetos obligados que se constituyan como contribuyentes o como autoridades en materia \n tributaria, no podrán clasificar la información relativa al ejercicio de recursos públicos como secreto fiscal.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":116},{"id":"886f3487-8b0e-4b92-85b7-79e9c72c1ff3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 119.","contenido":"Para que los sujetos obligados puedan permitir el acceso a i nformación confidencial requieren \n obtener el consentimiento de las personas particulares titulares de la información. \n No se requerirá el consentimiento del titular de la información confidencial cuando: \n I. La información se encuentre en registros públicos o fuentes de acceso público; \n II. Por ley tenga el carácter de pública; \n III. Exista una orden judicial; \n IV. Por razones de seguridad nacional y salubridad general, o para proteger los derechos de terceros, se \n requiera su publicación, o \n V. Cuando se transmit a entre sujetos obligados y entre estos y los sujetos de derecho internacional, en \n términos de los tratados y los acuerdos interinstitucionales, siempre y cuando la información se utilice \n para el ejercicio de facultades propias de los mismos. \n Para efectos de la fracción IV del presente artículo, la Autoridad garante, debidamente fundada y motivada, \n deberá aplicar la prueba de interés público. Además, se deberá corroborar una conexión patente entre la información \n confidencial y un tema de interés público y l a proporcionalidad entre la invasión a la intimidad ocasionada por la \n divulgación de la información confidencial y el interés público de la información. \n Capítulo IV \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 46 de 64 \n De las Versiones Públicas","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":117},{"id":"dfbf695e-9ed2-4a1f-8780-e7804b299dcb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 120.","contenido":"Cuando un documento o expediente contenga partes o secciones reservadas o confidenciales, los \n sujetos obligados a través de sus áreas, para efectos de atender una solicitud de información, deberán elaborar una \n versión pública en la que se testen las partes o secciones clasificadas, indicando su contenido d e manera genérica, \n fundando y motivando su clasificación, en términos de lo que determine el Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":118},{"id":"b4da8fe8-9a9d-4499-af38-099d75e921f0","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 121.","contenido":"Los sujetos obligados deberán procurar que los sistemas o medios empleados para eliminar la \n información en las versiones públicas n o permitan la recuperación o visualización de la misma.","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":119},{"id":"7d8a77f1-53e6-481f-99ba-5664ee71351c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   122.","contenido":"En las versiones públicas no podrá omitirse la información que constituya obligaciones de \n transparencia previstas en la presente Ley. \n TÍTULO SÉPTIMO \n PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA \n Capítulo I \n Del Procedimiento de Acceso a la Información","tipo_articulo":"ordinario","titulo_nombre":"INFORMACIÓN CLASIFICA DA","capitulo_nombre":"De la Información Confidencial","seccion_nombre":null,"orden":120},{"id":"712f46ce-96e2-4737-9b53-51133a43fae8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 123.","contenido":"Las Unidades de Transparencia de los sujetos obligados deberán garantizar las medidas y \n condiciones de accesibilidad para que toda persona pueda ejercer el derecho de acceso a la información, mediante \n solicitudes de información y deberá apoyar a la persona solicitante en la elaboración de las mismas, de conformidad \n con las bases establecidas en el presente Título.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":121},{"id":"58f60d33-639e-4530-9695-3bcc0054febf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 124.","contenido":"Cualquier persona por sí misma o a través de su representante, podrá presentar solicitud de acceso \n a información ante la Unidad de Transparencia, a través de la Plataforma Nacional, en la oficina u oficinas \n designadas para ello, vía correo electrónico, correo postal, mensajería, telégrafo, verbalmente o cualquier medio \n aprobado por el Sistema Nacional.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":122},{"id":"f28536b8-0830-4374-bdbd-e61dfae2799d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 125.","contenido":"Tratándose de solicitudes de acceso a información formuladas mediante la Plataforma Nacional, se \n asignará automáticamente un número de folio, con el que las personas solicitantes podrán dar s eguimiento a sus \n requerimientos. En los demás casos, la Unidad de Transparencia tendrá que registrar y capturar la solicitud de \n acceso en la Plataforma Nacional dentro de los cinco días posteriores a su recepción, y deberá enviar el acuse de \n recibo a la pe rsona solicitante, en el que se indique la fecha de recepción, el folio que corresponda y los plazos de \n respuesta aplicables.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":123},{"id":"c73db6c4-e7fe-4bd6-9ff4-04a883d9578e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 126.","contenido":"Para presentar una solicitud no se podrán exigir mayores requisitos que los siguientes: \n I. Medio para recibir notifi caciones; \n II. La descripción de la información solicitada, y \n III. La modalidad en la que prefiere se otorgue el acceso a la información, la cual podrá ser verbal, \n siempre y cuando sea para fines de orientación, mediante consulta directa, mediante la expedi ción de \n copias simples o certificadas o la reproducción en cualquier otro medio, incluidos los electrónicos. \n En su caso, la persona solicitante señalará el formato accesible o la lengua indígena en la que se requiera la \n información de acuerdo a lo señalado en la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":124},{"id":"9f635bb4-df65-4696-b460-e01c7b1c3b59","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 127.","contenido":"Cuando el particular presente su solicitud por medios electrónicos a través de la Plataforma \n Nacional, se entenderá que acepta que las notificaciones le sean efectuadas por dicho sistema, salvo que señale un \n medio distint o para efectos de las notificaciones. \n Las respuestas que otorguen las Unidades de Transparencia a través de la Plataforma Nacional, se consideran \n válidas, aun cuando no cuenten con firma autógrafa. \n En el caso de solicitudes recibidas en otros medios, en la s que las personas solicitantes no proporcionen un \n domicilio o medio para recibir la información o, en su defecto, no haya sido posible practicar la notificación, se \n notificará por estrados en la oficina de la Unidad de Transparencia.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":125},{"id":"474ce9e5-3ad9-434d-b65d-87bc9589ad42","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 128.","contenido":"Los tér minos de todas las notificaciones previstas en esta Ley, empezarán a correr al día siguiente \n al que se practiquen. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 47 de 64 \n Cuando los plazos fijados por esta Ley sean en días, estos se entenderán como hábiles.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":126},{"id":"9abccbac-8fb7-454e-9cb2-6a161cc2c38b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 129.","contenido":"De manera excepcional, cuando, de forma fundada y motivada, así lo determine el sujeto obligado, \n en aquellos casos en que la información solicitada que ya se encuentre en su posesión implique análisis, estudio o \n procesamiento de documentos cuya entrega o reproducción sobrepase las capacidades té cnicas del sujeto obligado \n para cumplir con la solicitud, en los plazos establecidos para dichos efectos, se podrán poner a disposición de la \n persona solicitante los documentos en consulta directa, salvo la información clasificada. \n En todo caso se facilita rá su copia simple o certificada, así como su reproducción por cualquier medio disponible \n en las instalaciones del sujeto obligado previo pago de derechos o que, en su caso, aporte la persona solicitante.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":127},{"id":"ace51420-05d4-49c6-865f-4713fb793617","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 130.","contenido":"Cuando los detalles proporcionados en la solicitud de acceso a información resulten insuficientes, \n incompletos o sean erróneos, para localizar la información solicitada, la Unidad de Transparencia podrá requerir a la \n persona solicitante, por una sola vez y dentro de un plazo que no podrá exce der de cinco días, contados a partir de la \n presentación de la solicitud, para que, en un término de hasta diez días, indique otros elementos o corrija los datos \n proporcionados. \n Este requerimiento interrumpirá el plazo de respuesta establecido en el artícul o 134 de la presente Ley, por lo que \n comenzará a computarse nuevamente al día siguiente del desahogo por parte del particular. En este caso, el sujeto \n obligado atenderá la solicitud en los términos en que fue desahogado el requerimiento de información adic ional. \n La solicitud se tendrá por no presentada cuando las personas solicitantes no atiendan el requerimiento de \n información adicional. En el caso de requerimientos parciales no desahogados, se tendrá por presentada la solicitud \n por lo que respecta a los c ontenidos de información que no formaron parte del requerimiento.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":128},{"id":"b921237f-e535-4877-a2b2-4b276bab8c57","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 131.","contenido":"Los sujetos obligados deberán otorgar los documentos que se encuentren en sus archivos o que \n estén obligados a documentar de acuerdo con sus facultades, competencias o funcione s, conforme a las \n características físicas o electrónicas de la información con la que cuenten o del lugar donde se encuentre, sin \n necesidad de elaborar documentos adicionales para atender las solicitudes de acceso a información. \n Tratándose de solicitudes d e acceso a información cuyo contenido constituya una consulta, el sujeto obligado \n podrá dar una interpretación para verificar si dentro de los documentos con los que cuentan atendiendo a las \n características señaladas en el párrafo anterior puede darse aten ción, sin que se entienda que debe emitir \n pronunciamientos específicos, explicaciones y/o argumentaciones sobre supuestos hipotéticos. \n En el caso de que la información solicitada consista en bases de datos se deberá privilegiar la entrega de la \n misma en fo rmatos abiertos.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":129},{"id":"fe616ea3-4941-4a88-ac72-125df6d65110","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 132.","contenido":"Cuando la información requerida por la persona solicitante ya esté disponible al público en medios \n impresos, tales como libros, compendios, trípticos, registros públicos, en formatos electrónicos disponibles en \n Internet o en cualquier otro medio, se le hará saber por el medio requerido por la persona solicitante la fuente, el \n lugar y la forma en que puede consultar, reproducir o adquirir dicha información en un plazo no mayor a cinco días.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":130},{"id":"ce2d4d54-1047-483b-88dd-1d289e23f931","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 133.","contenido":"Las Unidades de Transpa rencia deberán garantizar que las solicitudes se turnen a todas las áreas \n competentes que cuenten con la información o deban tenerla de acuerdo a sus facultades, competencias y \n funciones, con el objeto de que realicen una búsqueda exhaustiva y razonable de la información solicitada.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":131},{"id":"04dfdf13-0386-49d1-9c9e-6e9ebe54d625","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 134.","contenido":"La respuesta a la solicitud deberá ser notificada a la persona interesada en el menor tiempo \n posible, que no podrá exceder de veinte días, contados a partir del día siguiente a la presentación de aquélla. \n Excepcion almente, el plazo referido en el párrafo anterior podrá ampliarse hasta por diez días más, siempre y \n cuando se justifiquen de manera fundada y motivada las razones ante el Comité de Transparencia, y este emita la \n resolución respectiva, la cual deberá notif icarse a la persona solicitante antes de su vencimiento.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":132},{"id":"b0b98b1a-9f10-4cf8-aa57-7589f7f39773","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 135.","contenido":"El acceso se dará en la modalidad de entrega y, en su caso, de envío elegidos por la persona \n solicitante. Cuando la información no pueda entregarse o enviarse en la modalidad elegida, e l sujeto obligado deberá \n justificar el impedimento, y notificar al particular la disposición de la información en todas las modalidades que \n permita el documento de que se trate, procurando reducir, en todo momento, los costos de entrega. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 48 de 64","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":133},{"id":"ba066c3c-4433-4bf0-9bf0-3e427b50a98d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 136.","contenido":"Los sujetos obligados establecerán la forma y términos en que darán trámite interno a las \n solicitudes en materia de acceso a la información. \n La elaboración de versiones públicas, cuya modalidad de reproducción o envío tenga un costo, procederá una \n vez que se a credite el pago respectivo. \n Ante la falta de respuesta a una solicitud en el plazo previsto y en caso de que proceda el acceso, los costos de \n reproducción y envío correrán a cargo del sujeto obligado.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":134},{"id":"d4f9e2ba-4e4f-41b1-a232-bc8e9c544ce7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 137.","contenido":"La Unidad de Transparencia tendrá disponi ble la información solicitada, durante un plazo mínimo \n de sesenta días, contado a partir de que la persona solicitante hubiere realizado, en su caso, el pago respectivo, el \n cual deberá efectuarse en un plazo no mayor a treinta días. \n Transcurridos dichos pl azos, los sujetos obligados darán por concluida la solicitud y procederán, de ser el caso, a \n la destrucción del material en el que se reprodujo la información. Serán aplicables estas mismas disposiciones, en el \n cumplimiento a los recursos de revisión. \n Artí culo 138. Cuando las Unidades de Transparencia determinen la notoria incompetencia por parte de los \n sujetos obligados, dentro del ámbito de su aplicación, para atender la solicitud de acceso a la información, deberán \n comunicarlo a la persona solicitante, d entro de los tres días posteriores a la recepción de la solicitud y, en caso de \n poderlo determinar, señalar a la persona solicitante el o los sujetos obligados competentes. \n Si los sujetos obligados son competentes para atender parcialmente la solicitud de acceso a la información, \n deberán dar respuesta respecto de dicha parte.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":135},{"id":"1c437d71-b3d3-45cd-b22c-3b51db9294bd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 139.","contenido":"En caso de que los sujetos obligados consideren que la información deba ser clasificada, se \n sujetará a lo siguiente: \n El área deberá remitir la solicitud, así como un escr ito en el que funde y motive la clasificación al Comité de \n Transparencia, mismo que deberá resolver para: \n I. Confirmar la clasificación; \n II. Modificar la clasificación y otorgar total o parcialmente el acceso a la información, y \n III. Revocar la clasificaci ón y conceder el acceso a la información. \n El Comité de Transparencia podrá tener acceso a la información que esté en poder del área correspondiente, de \n la cual se haya solicitado su clasificación. \n La resolución del Comité de Transparencia será notificada a la persona interesada en el plazo de respuesta a la \n solicitud que establece el artículo 134 de la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":136},{"id":"36537898-df23-49e4-8660-25aac42219cd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   140.","contenido":"Cuando la información no se encuentre en los archivos del sujeto obligado, el Comité de \n Transparencia: \n I. Analizará el caso y tom ará las medidas necesarias para localizar la información; \n II. Expedirá una resolución que confirme la inexistencia del Documento; \n III. Ordenará, a través de la Unidad de Transparencia, se exponga de forma fundada y motivada, las \n razones por las cuales en e l caso particular no cuenta con la información, lo cual notificará a la \n persona solicitante, y \n IV. En su caso, notificará al órgano interno de control o equivalente del sujeto obligado.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":137},{"id":"1243824f-fc03-4ee1-85c4-abb3b1bf8c3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 141.","contenido":"La resolución del Comité de Transparencia que confirme l a inexistencia de la información solicitada \n contendrá los elementos mínimos que permitan a la persona solicitante tener la certeza de que se utilizó un criterio \n de búsqueda exhaustivo, además de señalar las circunstancias de tiempo, modo y lugar que genera ron la \n inexistencia. \n En aquellos casos en que no se advierta obligación o competencia alguna de los sujetos obligados para contar \n con la información, derivado del análisis a las disposiciones jurídicas aplicables a la materia de la solicitud, además \n no se tengan elementos de convicción que permitan suponer que esta debe obrar en sus archivos, o bien, se cuente \n con atribuciones, pero no se ha generado la información no será necesario que el Comité de Transparencia emita \n una resolución que confirme la inexist encia de la misma. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 49 de 64 \n Cuando se requiera un dato estadístico o numérico, y el resultado de la búsqueda de la información sea cero, \n este deberá entenderse como un dato que constituye un elemento numérico que atiende la solicitud, y no como la \n inexistencia de l a información solicitada.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":138},{"id":"0838650a-c7ff-4207-ad25-c604b76dd7a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 142.","contenido":"Las personas físicas y morales que reciban y ejerzan recursos públicos o realicen actos de \n autoridad, serán responsables del cumplimiento de los plazos y términos para otorgar acceso a la información. \n Capítulo II \n De las Cuotas de Acceso","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Procedimiento de Acceso a la Información","seccion_nombre":null,"orden":139},{"id":"39e05b5c-8eee-4d4c-822a-653af32a49c2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 143.","contenido":"En caso de existir costos para obtener la información, deberán cubrirse de manera previa a la \n entrega y no podrán ser superiores a la suma de: \n I. El costo de los materiales utilizados en la reproducción de la información; \n II. El costo de envío, en su caso, y \n III. El pago de la certificación de los documentos, cuando proceda. \n Las cuotas de los derechos aplicables deberán establecerse en la Ley Federal de Derechos, los cuales se \n publicarán en los sitios de Internet de los su jetos obligados. En su determinación se deberá considerar que los \n montos permitan o faciliten el ejercicio del derecho de acceso a la información, asimismo, se establecerá la \n obligación de fijar una cuenta bancaria única y exclusivamente para que la person a solicitante realice el pago íntegro \n del costo de la información que solicitó. \n Los sujetos obligados a los que no les sea aplicable la Ley Federal de Derechos deberán establecer cuotas que \n no deberán ser mayores a las dispuestas en dicha ley. \n La informaci ón deberá ser entregada sin costo, cuando implique la entrega de no más de veinte hojas simples. \n Las Unidades de Transparencia podrán exceptuar el pago de reproducción y envío atendiendo a las circunstancias \n socioeconómicas de la persona solicitante. \n TÍTUL O OCTAVO \n DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN \n Capítulo I \n Del Recurso de Revisión","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"De las Cuotas de Acceso","seccion_nombre":null,"orden":140},{"id":"2ab962d3-4e0f-4ce6-a6e7-6ff21a7f9157","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 144.","contenido":"La persona solicitante podrá interponer, por sí mismo o por conducto de su representante, de \n manera física o por medios electrónicos, recurso de revisión ante la Autoridad garante que corresponda, o ante la \n Unidad de Transparencia que haya conocido de la solicitud dentro de los quince días siguientes a la fecha de la \n notificación de la respuesta, o del vencimiento del plazo para su notificación. \n En el caso de que se interponga ante la Unidad de Transparencia, esta deberá remitir el recurso de revisión a la \n Autoridad garante que corresponda a más tardar al día siguiente de haberlo recibido. \n Para el caso de personas que posean algún tipo de discapacidad que les dific ulte una comunicación clara y \n precisa o de personas que sean hablantes de lengua indígena, se procurará proporcionarles gratuitamente un \n traductor o intérprete. \n Asimismo, cuando el recurso sea presentado por una persona con discapacidad ante la Unidad de T ransparencia, \n dicha circunstancia deberá ser notificada a la Autoridad garante, para que determine mediante acuerdo los ajustes \n razonables que garanticen la tutela efectiva del derecho de acceso a la información.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":141},{"id":"83897723-69e7-4fc1-b5bd-be85696ea912","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 145.","contenido":"El recurso de revisión proced e en contra de: \n I. La clasificación de la información; \n II. La declaración de inexistencia de información; \n III. La declaración de incompetencia por el sujeto obligado; \n IV. La entrega de información incompleta; \n V. La entrega de información que no corresponda con lo solicitado; \n VI. La falta de respuesta a una solicitud de acceso a la información dentro de los plazos establecidos en la \n ley; \n VII. La notificación, entrega o puesta a disposición de información en una modalidad o formato distinto al \n solicitado; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 50 de 64 \n VII I. La entrega o puesta a disposición de información en un formato incomprensible y/o no accesible para \n la persona solicitante; \n IX. Los costos o tiempos de entrega de la información; \n X. La falta de trámite a una solicitud; \n XI. La negativa a permitir la cons ulta directa de la información; \n XII. La falta, deficiencia o insuficiencia de la fundamentación y/o motivación en la respuesta, o \n XIII. La orientación a un trámite específico. \n La respuesta que den los sujetos obligados derivada de la resolución al recurso de revisión que proceda por las \n causales señaladas en las fracciones III, VI, VIII, IX, X y XI de este artículo, es susceptible de ser impugnada de \n nueva cuenta, mediante recurso de revisión, ante la Autoridad garante correspondiente.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":142},{"id":"64391472-1858-4109-9c9a-39e73c3977bd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 146.","contenido":"El recu rso de revisión debe contener: \n I. El sujeto obligado ante el cual se presentó la solicitud; \n II. El nombre de la persona solicitante que recurre o de su representante y, en su caso, de la persona \n tercera interesada, así como la dirección o medio que señale para recibir notificaciones; \n III. El número de folio de respuesta de la solicitud de acceso; \n IV. La fecha en que fue notificada la respuesta a la persona solicitante o tuvo conocimiento del acto \n reclamado, o de presentación de la solicitud, en caso de falt a de respuesta; \n V. El acto que se recurre; \n VI. Las razones o motivos de inconformidad, y \n VII. La copia de la respuesta que se impugna y, en su caso, de la notificación correspondiente, salvo en el \n caso de respuesta de la solicitud. \n Adicionalmente, se podrá n anexar las pruebas y demás elementos que considere procedentes someter a juicio de \n la Autoridad garante. \n En ningún caso será necesario que el particular ratifique el recurso de revisión interpuesto.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":143},{"id":"b97073a6-86e1-49ea-a867-2511a48a81e8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 147.","contenido":"Si el escrito de interposición del recurs o no cumple con alguno de los requisitos establecidos en el \n artículo anterior y la Autoridad garante no cuentan con elementos para subsanarlos, se prevendrá al recurrente, por \n una sola ocasión y a través del medio que haya elegido para recibir notificacion es, con el objeto de que subsane las \n omisiones dentro de un plazo que no podrá exceder de cinco días, contados a partir del día siguiente de la \n notificación de la prevención, con el apercibimiento de que, de no cumplir, se desechará el recurso de revisión. \n La prevención tendrá el efecto de interrumpir el plazo que tienen las Autoridades garantes para resolver el \n recurso, por lo que comenzará a computarse a partir del día siguiente a su desahogo. \n En los casos que no se proporcione un domicilio o medio para r ecibir notificaciones o, en su defecto, no haya sido \n posible practicar la notificación, se realizará por estrados en el domicilio de la Autoridad garante. \n No podrá prevenirse por el nombre o los datos que proporcione la persona solicitante.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":144},{"id":"dc8e7c07-996e-4563-a3df-733dc5d497c9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 148.","contenido":"L a Autoridad garante resolverá el recurso de revisión en un plazo que no podrá exceder de \n cuarenta días, contados a partir de la admisión del mismo, plazo que podrá ampliarse por una sola vez y hasta por un \n periodo de veinte días. Durante el procedimiento d ebe aplicarse la suplencia de la queja a favor del recurrente, sin \n cambiar los hechos expuestos, asegurándose de que las partes puedan presentar, de manera oral o escrita, los \n argumentos que funden y motiven sus pretensiones.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":145},{"id":"7754261d-4100-414f-84cc-933d6bf77741","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 149.","contenido":"Cuando en el rec urso de revisión se señale como agravio la omisión por parte del sujeto obligado \n de responder a una solicitud de acceso, y el recurso se resuelva de manera favorable para el recurrente, el sujeto \n obligado deberá darle acceso a la información en un periodo no mayor a los diez días hábiles; en cuyo caso se hará \n sin que se requiera del pago correspondiente de derechos por su reproducción, siempre que la resolución esté firme, \n la entrega sea en el formato requerido originalmente y no se trate de copias certific adas. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 51 de 64","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":146},{"id":"8732c69f-a376-4181-87f6-144880cc5c03","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 150.","contenido":"En todo momento las Autoridades garantes deben tener acceso a la información clasificada para \n determinar su naturaleza según se requiera. El acceso se dará de conformidad con las disposiciones jurídicas \n establecidas por los sujetos obli gados para el resguardo o salvaguarda de la información. \n Tratándose de la información a que se refiere el último párrafo del artículo 104 de esta Ley, los sujetos obligados \n deberán dar acceso a las Autoridades garantes a dicha información mediante la exhib ición de la documentación \n relacionada, en las oficinas de los propios sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":147},{"id":"7e73410e-470b-4b10-a806-f19a665a5f18","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 151.","contenido":"La información reservada o confidencial que, en su caso, sea consultada por las Autoridades \n garantes por resultar indispensable para resolver el asunto, debe ser mantenida con ese carácter y no debe estar \n disponible en el Expediente, salvo en los casos en los que sobreviniera la desclasificación de dicha información y \n continuara bajo el resguardo del sujeto obligado en el que originalmente se encontraba o cuando se requiera, por ser \n violaciones graves a derechos humanos o delitos de lesa humanidad, de conformidad con el derecho nacional y los \n tratados internacionales de los que el Estado mexicano sea parte.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":148},{"id":"d5ffab04-c371-45ac-b485-19d81f20458c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 152.","contenido":"La Autoridad garante al resolver el recurso de revisión, debe aplicar una prueba de interés público \n con base en elementos de idoneidad, necesidad y proporcionalidad, cuando exista una colisión de derechos. \n Para estos efectos, se entiende por: \n I. Idoneidad: La legitimidad del derecho adoptado como preferente, que sea el adecuado para el logro de \n un fin constitucionalmente válido o apto para conseguir el fin pretendido; \n II. Necesidad: La falta de un medio alternativo menos lesivo a la apertura de la información, para \n satisfacer el interés públi co, y \n III. Proporcionalidad: El equilibrio entre perjuicio y beneficio a favor del interés público, a fin de que la \n decisión tomada represente un beneficio mayor al perjuicio que podría causar a la población.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":149},{"id":"c0658438-c194-4b5b-bda4-85fb8f13c470","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 153.","contenido":"Las Autoridades garantes resolver án el recurso de revisión conforme a lo siguiente: \n I. Interpuesto el recurso de revisión deberán proceder a su análisis para que decrete su admisión o su \n desechamiento; \n II. Admitido el recurso de revisión deberán integrar un Expediente y ponerlo a disposic ión de las partes, \n para que, en un plazo máximo de siete días, manifiesten lo que a su derecho convenga. De \n considerarse improcedente el recurso, deberá desecharse mediante acuerdo fundado y motivado, \n dentro de un plazo máximo de cinco días contados a part ir de la conclusión del plazo otorgado a las \n partes para que manifiesten lo que a sus intereses convenga, debiendo notificarle dentro de los tres \n días siguientes a la emisión del acuerdo; \n III. En caso de existir persona tercera interesada, se le hará la no tificación para que en el plazo \n mencionado en la fracción anterior acredite su carácter, alegue lo que a su derecho convenga y aporte \n las pruebas que estime pertinentes; \n IV. Dentro del plazo mencionado en la fracción II del presente artículo, las partes po drán ofrecer todo tipo \n de pruebas o alegatos excepto la confesional por parte de los sujetos obligados y aquéllas que sean \n contrarias a derecho. Se recibirán aquellas pruebas que resulten supervinientes por las partes, mismas \n que serán tomadas en cuenta, s iempre y cuando no se haya dictado la resolución; \n V. Podrán determinar la celebración de audiencias con las partes durante la sustanciación del recurso de \n revisión; \n VI. Concluido el plazo señalado en la fracción II del presente artículo, procederán a decre tar el cierre de \n instrucción. Asimismo, a solicitud de los sujetos obligados o los recurrentes, los recibirán en audiencia, \n a efecto de allegarse de mayores elementos de convicción que le permitan valorar los puntos \n controvertidos objeto del recurso de rev isión; \n VII. No estarán obligadas a atender la información remitida por el sujeto obligado una vez decretado el \n cierre de instrucción, y \n VIII. Decretado el cierre de instrucción, el expediente pasará a resolución, en un plazo que no podrá \n exceder de veinte días.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":150},{"id":"c2592b7c-03f2-4e9a-b895-6833611afc6a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 154.","contenido":"Las resoluciones de las Autoridades garantes podrán: \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 52 de 64 \n I. Desechar o sobreseer el recurso; \n II. Confirmar la respuesta del sujeto obligado, o \n III. Revocar o modificar la respuesta del sujeto obligado. \n Las resoluciones establecerán, en su c aso, los plazos y términos para su cumplimiento y los procedimientos para \n asegurar su ejecución, los cuales no podrán exceder de diez días para la entrega de información. Excepcionalmente, \n las Autoridades garantes previa fundamentación y motivación, podrán ampliar estos plazos cuando el asunto así lo \n requiera.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":151},{"id":"5fa6ebc8-86f4-412e-8620-c72c6b94495d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 155.","contenido":"En las resoluciones las Autoridades garantes podrán señalarles a los sujetos obligados que la \n información que deben proporcionar sea considerada como obligación de transparencia de confo rmidad con el \n Capítulo II del Título Quinto, denominado “De las Obligaciones de Transparencia Comunes” de la presente Ley, \n atendiendo a la relevancia de la información, la incidencia de las solicitudes sobre la misma y el sentido reiterativo de \n las resoluc iones.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":152},{"id":"2dff1aad-e9fc-4509-b457-47a4bf23ded1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 156.","contenido":"Las Autoridades garantes deben notificar a las partes y publicar las resoluciones, a más tardar, al \n tercer día siguiente de su aprobación. \n Los sujetos obligados deben informar a las Autoridades garantes de que se trate, el cumplimiento de sus \n resoluciones en un plazo no mayor a tres días.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":153},{"id":"734a77d6-af4c-47c4-bdde-4f3a0f967d34","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 157.","contenido":"Cuando las Autoridades garantes determinen durante la sustanciación del recurso de revisión que \n pudo haberse incurrido en una probable responsabilidad por el incumplimiento a las obligaci ones previstas en esta \n Ley y las demás disposiciones aplicables en la materia, debe hacerlo del conocimiento del órgano interno de control \n o de la instancia competente para que esta inicie, en su caso, el procedimiento de responsabilidad respectivo. \n Artícu lo 158. El recurso será desechado por improcedente cuando: \n I. Sea extemporáneo por haber transcurrido el plazo establecido en el artículo 144 de la presente Ley; \n II. Se esté tramitando ante el Poder Judicial algún recurso o medio de defensa interpuesto por el \n recurrente; \n III. No actualice alguno de los supuestos previstos en el artículo 145 de la presente Ley; \n IV. No se haya desahogado la prevención en los términos establecidos en el artículo 147 de la presente \n Ley; \n V. Se impugne la veracidad de la informac ión proporcionada; \n VI. Se trate de una consulta, o \n VII. El recurrente amplíe su solicitud en el recurso de revisión, únicamente respecto de los nuevos \n contenidos.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":154},{"id":"5f62bf96-a12b-4eb8-a371-d5019b5396bc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 159.","contenido":"El recurso será sobreseído, en todo o en parte, cuando, una vez admitido, se ac tualicen alguno de \n los siguientes supuestos: \n I. El recurrente se desista; \n II. El recurrente fallezca o tratándose de personas morales que se disuelvan; \n III. El sujeto obligado responsable del acto lo modifique o revoque de tal manera que el recurso de \n revi sión quede sin materia, o \n IV. Admitido el recurso de revisión, aparezca alguna causal de improcedencia en los términos del presente \n Capítulo.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":155},{"id":"6181aa80-c590-4110-8091-c46143097564","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 160.","contenido":"Las resoluciones de las Autoridades garantes son vinculatorias, definitivas e inatacables para los \n s ujetos obligados. \n Únicamente la persona titular de la Consejería Jurídica del Ejecutivo Federal podrá interponer recurso de revisión \n ante la Suprema Corte de Justicia de la Nación, en los términos que se establecen en el Capítulo III denominado “Del \n Recurs o de Revisión en Materia de Seguridad Nacional”, del presente Título, sólo en el caso que dichas resoluciones \n puedan poner en peligro la seguridad nacional. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 53 de 64 \n Los jueces y tribunales especializados en materia de transparencia tendrán acceso a la información clasificada \n cuando resulte indispensable para resolver el asunto y hubiera sido ofrecida en juicio. Dicha información deberá ser \n mantenida con ese carácter y no estará disponible en el expediente judicial. El acceso se dará de conformidad con \n los protocolo s previamente establecidos para la protección y resguardo de la información por parte de los sujetos \n obligados.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":156},{"id":"81716219-8287-4ef4-b4eb-f5bf97c42b57","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 161.","contenido":"Las personas particulares podrán impugnar las determinaciones o resoluciones de las Autoridades \n garantes por la vía del recurso de inconformidad, en los casos previstos en la presente Ley, o ante los jueces y \n tribunales especializados en materia de transparencia establecidos por el Poder Judicial de la Federación mediante \n el juicio de amparo. \n Los juicios de amparo serán sustanciados por jueces y tribunales especializados en los términos del artículo 94 \n de la Constitución Política de los Estados Unidos Mexicanos. \n Capítulo II \n Del Recurso de Inconformidad","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":157},{"id":"6a8b23ce-14fc-4ba0-8244-acdcc4f42183","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 162.","contenido":"Tratándose de las resoluciones a los recursos de revisión de las Auto ridades garantes locales \n cuando las mismas se encuentren vinculadas con solicitudes de información concernientes a recursos públicos \n federales, las personas particulares podrán acudir ante la Autoridad garante federal o ante los tribunales \n especializados e n materia de transparencia del Poder Judicial de la Federación. \n En el supuesto de que el Sistema Nacional adopte los acuerdos previstos en el artículo 25, fracción XIV de la \n presente Ley, la Autoridad garante federal deberá de aplicar las disposiciones pre vistas en este Capítulo.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":158},{"id":"9b3ded8a-cf31-4201-b81b-e7bc9d840df9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 163.","contenido":"El recurso de inconformidad procede contra las resoluciones emitidas por las Autoridades garantes \n locales cuando se encuentren vinculadas con solicitudes de información concernientes a recursos públicos federales \n que: \n I. Confirmen o modifiquen la clasificación de la información vinculada con recursos públicos federales, o \n II. Confirmen la inexistencia o negativa de información vinculadas con recursos públicos federales. \n Se entenderá como negativa de acceso a la informa ción, la falta de resolución de las Autoridades garantes \n locales dentro del plazo previsto para ello.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":159},{"id":"3d73d6f1-6f2d-4c80-867e-9c37f1200e61","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 164.","contenido":"El recurso de inconformidad debe presentarse dentro de los quince días posteriores a que se tuvo \n conocimiento de la resolución o que se venz a el plazo para que fuera emitido, mediante el sistema electrónico o por \n escrito, ante la Autoridad garante federal o ante la Autoridad garante local que hubiere emitido la resolución. \n En caso de presentarse recurso de inconformidad por escrito ante la Aut oridad garante local, esta deberá hacerlo \n del conocimiento a la Autoridad garante federal al día siguiente de su recepción, acompañándolo con la resolución \n impugnada, a través de la Plataforma Nacional. \n Independientemente de la vía a través de la cual sea interpuesto el recurso de inconformidad, el Expediente \n respectivo deberá obrar en la Plataforma Nacional.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":160},{"id":"ac4c59c6-128d-4085-bf74-169b9f4a0554","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 165.","contenido":"El recurso de inconformidad debe contener: \n I. El sujeto obligado ante el cual se presentó la solicitud; \n II. El número de la resolución d el recurso de revisión de la resolución impugnada; \n III. La Autoridad garante local que emitió la resolución que se impugna; \n IV. El nombre del inconforme y, en su caso, de la persona tercera interesada, así como las \n correspondientes direcciones o medios par a recibir notificaciones; \n V. La fecha en que fue notificada la resolución impugnada; \n VI. El acto que se recurre; \n VII. Las razones o motivos de la inconformidad, y \n VIII. La copia de la resolución que se impugna y, en su caso, de la notificación correspondie nte. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 54 de 64 \n El recurrente podrá anexar las pruebas y demás elementos que considere procedentes someter a consideración \n de la Autoridad garante.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":161},{"id":"b8043e13-72c5-43c9-9fe3-d9b1990f7ad3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 166.","contenido":"Una vez que la Autoridad garante federal reciba el recurso de inconformidad examinará su \n procedencia y, e n su caso, requerirá los elementos que considere necesarios a la Autoridad garante local \n responsable.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":162},{"id":"3ba0dc20-3248-42dd-b494-1873c076b9ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 167.","contenido":"Si el escrito de interposición del recurso de inconformidad no cumple con alguno de los requisitos \n establecidos en el artículo 165 de esta L ey y la Autoridad garante federal no cuenta con elementos para subsanarlos, \n se prevendrá al inconforme en un plazo que no excederá de cinco días, por una sola ocasión y a través del medio \n que haya elegido para recibir notificaciones, para que subsane las o misiones dentro de un plazo que no podrá \n exceder de quince días, contados a partir del día siguiente al de la notificación de la prevención, con el \n apercibimiento de que, de no desahogar la prevención en tiempo y forma, se tendrá por no presentado el recur so de \n inconformidad. \n La prevención tendrá el efecto de interrumpir el plazo que tiene la Autoridad garante federal para resolver el \n recurso de inconformidad, por lo que este comenzará a computarse nuevamente a partir del día siguiente a su \n desahogo. \n No pod rá prevenirse por el nombre que proporcione el inconforme.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":163},{"id":"34558ce2-cdf9-464a-8d93-4f4b23857a13","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 168.","contenido":"La Autoridad garante federal resolverá el recurso de inconformidad en un plazo que no podrá \n exceder de treinta días, plazo que podrá ampliarse por una sola vez y hasta por un periodo igual. \n Interpuesto el recurso de inconformidad por falta de resolución, en términos del segundo párrafo del artículo 163 \n de esta Ley, la Autoridad garante federal dará vista, en el término de tres días siguientes, contados a partir del día en \n que fue recib ido el recurso, a la Autoridad garante local, para que alegue lo que a su derecho convenga en un plazo \n de cinco días. \n Recibida la contestación, la Autoridad garante federal debe emitir su resolución en un plazo no mayor a quince \n días. En caso de no recibir la contestación por parte de la Autoridad garante local o que esta no pruebe \n fehacientemente que dictó resolución o no exponga de manera fundada y motivada, a criterio de la Autoridad garante \n federal, que se trata de información reservada o confidencial, esta resolverá a favor de la persona solicitante.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":164},{"id":"333633a5-990e-4ff6-baa2-9cf358b08cfc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 169.","contenido":"Durante el procedimiento debe aplicarse la suplencia de la deficiencia de la queja, sin cambiar los \n hechos, a favor del recurrente y se deberá asegurar que las partes puedan presentar los argu mentos y constancias \n que funden y motiven sus pretensiones y formular sus alegatos.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":165},{"id":"bc38441d-4bc7-4d38-882b-3c59011cf93c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 170.","contenido":"En todo caso, la Autoridad garante federal tendrá acceso a la información clasificada para \n determinar su naturaleza. \n La información reservada o confidencial q ue, en su caso, sea consultada por la persona Titular o la persona \n servidora pública que se designe para tal efecto de la Autoridad garante federal por resultar indispensable para \n resolver el asunto, debe ser mantenida con ese carácter y no debe estar disp onible en el Expediente, salvo en los \n casos en los que sobreviniera la desclasificación de dicha información, continuando bajo el resguardo del sujeto \n obligado en el que originalmente se encontraba.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":166},{"id":"5282598b-024f-47a4-ac32-38c814584ac8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 171.","contenido":"Admitido el recurso de inconformidad, se co rrerá traslado del mismo a la Autoridad garante local, a \n fin de que en un plazo máximo de diez días rinda su informe justificado. \n El recurrente podrá manifestar lo que a su derecho convenga y aportar los elementos que considere pertinentes, \n dentro de los d iez días siguientes a la notificación de la admisión del recurso de inconformidad. Concluido este plazo, \n se decretará el cierre de instrucción y el Expediente pasará a resolución. \n El recurrente podrá solicitar la ampliación del plazo, antes del cierre de i nstrucción, hasta por un periodo de diez \n días adicionales para manifestar lo que a su derecho convenga.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":167},{"id":"c5c86132-2a6a-4d8a-8501-ebbb2619acac","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 172.","contenido":"Después del cierre de instrucción y hasta antes de dictada la resolución, sólo serán admisibles las \n pruebas supervenientes y la petición d e ampliación de informes a las Autoridades garantes locales. \n En caso de existir persona tercera interesada, se le notificará la admisión del recurso de inconformidad para que, \n en un plazo no mayor a cinco días, acredite su carácter y alegue lo que a su der echo convenga. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 55 de 64","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":168},{"id":"72517e4b-59dd-4337-893a-cf18aa9d4d7e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 173.","contenido":"Las resoluciones de la unidad correspondiente de la Autoridad garante federal podrán: \n I. Desechar o sobreseer el recurso de inconformidad; \n II. Confirmar la resolución de la Autoridad garante local, o \n III. Revocar o modificar la resolución de la Autoridad garante local. \n La resolución será notificada al inconforme, al sujeto obligado, a la Autoridad garante local, y, en su caso, a la \n persona tercera interesada, a través de la Plataforma Nacional.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":169},{"id":"a17740a3-a45e-4207-959e-1ff5177af613","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   174.","contenido":"Cuando la Autoridad garante federal determine durante la sustanciación del recurso de \n inconformidad que pudo haberse incurrido en una probable responsabilidad por el incumplimiento a las obligaciones \n previstas en la presente Ley y demás disposiciones aplicables en la materia, deberá hacerlo del conocimiento de la \n autoridad competente para que esta inicie, en su caso, el procedimiento de responsabilidad respectivo.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":170},{"id":"dc9c9b15-e8ba-4e64-8305-164cd5ba7a70","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 175.","contenido":"En los casos en que por conducto del recurso de inconformidad se modifique o revoque lo decidido \n en el recurso de revisión, la Autoridad garante local, señalada como responsable y que fuera la que dictó la \n resolución recurrida, procederá a emitir un nuevo fallo, atendiendo los lineamientos que se fijaron al resolver la \n inconformidad, dentro del plazo de quince días, contados a partir del día siguiente al en que se hubiere notificado o \n se tenga conocimiento de la resolución dictada en la inconformidad. \n Excepcionalmente, considerando las circunstancias especiales de cada caso en concreto, las Autoridades \n ga rantes locales, de manera fundada y motivada, podrán solicitar a la Autoridad garante federal una ampliación de \n plazo para la emisión de la nueva resolución, la cual debe realizarse a más tardar cinco días antes de que venza el \n plazo otorgado para el cumpl imiento de la resolución, a efecto de que dicha Autoridad garante federal resuelva sobre \n la procedencia de la misma dentro de los tres días siguientes de realizada la petición.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":171},{"id":"68484c52-7ec8-4d7a-aaaa-5e0b79d42b25","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 176.","contenido":"Una vez emitida la nueva resolución por la Autoridad garante loca l responsable de la entidad \n federativa, según corresponda, en cumplimiento al fallo del recurso de inconformidad, la notificará sin demora, a \n través de la Plataforma Nacional a la Autoridad garante federal, así como al sujeto obligado que corresponda, a \n tr avés de su Unidad de Transparencia para efecto del cumplimiento.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":172},{"id":"d617dc72-e650-434f-a0e5-ebaa14fec52a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 177.","contenido":"El sujeto obligado, a través de la Unidad de Transparencia debe cumplir con la nueva resolución \n que le hubiere notificado la Autoridad garante local en cumplimiento al fallo del recurso de inconformidad, en un plazo \n no mayor a diez días, a menos de que en la misma se hubiere determinado un plazo mayor para su cumplimiento. En \n el propio acto en que se haga la notificación al sujeto obligado, se le requerirá para que informe sobre el \n cumplimiento que se dé a la resolución de referencia.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":173},{"id":"9239e2a3-c173-4736-b316-d6a983605bf8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 178.","contenido":"Una vez cumplimentada la resolución a que se refiere el artículo anterior por parte del sujeto \n obligado, este debe informar a la Autoridad garante local respecto de su cumplimiento, lo cual debe hacer dentro del \n plazo previsto en el artículo anterior.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":174},{"id":"6cc8d93e-749f-46df-8edc-9468733bcd30","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 179.","contenido":"Corresponderá a las Autoridades garantes locales, en el ámbito de su competencia, realizar el \n seguimiento y vigilancia del debido cumplimiento por parte del sujeto obligado re spectivo de la nueva resolución \n emitida como consecuencia de la inconformidad, en términos del Capítulo II del presente Título.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":175},{"id":"822a85ec-45ca-480d-8d01-770388e3b8a4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 180.","contenido":"Las medidas de apremio previstas en esta Ley resultarán aplicables para efectos del cumplimiento \n de las resolucion es que recaigan a los recursos de inconformidad. Estas medidas de apremio deben establecerse en \n la propia resolución.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":176},{"id":"ac319387-98af-4bd6-a239-0b9d3f478f7d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 181.","contenido":"El recurso de inconformidad será desechado por improcedente cuando: \n I. Sea extemporáneo por haber transcurrido el plazo esta blecido en el artículo 164 de la presente Ley; \n II. Se esté tramitando ante el tribunal especializado en materia de transparencia del Poder Judicial algún \n recurso o medio de defensa interpuesto por el inconforme o, en su caso, por la persona tercera \n interes ada, en contra del acto recurrido ante la Autoridad garante federal; \n III. No se actualice alguno de los supuestos previstos en el artículo 163 de la presente Ley; \n IV. Cuando la pretensión del recurrente vaya más allá de los agravios planteados inicialmente ante la \n Autoridad garante local correspondiente; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 56 de 64 \n V. La Autoridad garante federal no sea competente, o \n VI. Se actualice cualquier otra hipótesis de improcedencia prevista en la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":177},{"id":"b3ae1e1f-209a-474f-9752-da6dd5a1bdbc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 182.","contenido":"El recurso de inconformidad será sobreseído cuando, una vez admitido, se actualicen alguno de los \n siguientes supuestos: \n I. El inconforme se desista expresamente del recurso; \n II. El recurrente fallezca; \n III. El sujeto obligado responsable del acto lo modifique o revoque de tal manera que el recurso de \n incon formidad quede sin materia, o \n IV. Admitido el recurso de inconformidad, aparezca alguna causal de improcedencia en los términos del \n presente Capítulo.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":178},{"id":"1040bd77-59fc-4e66-84ec-b532fbecb883","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 183.","contenido":"La resolución de la Autoridad garante federal será definitiva e inatacable para la Autorida d garante \n local y el sujeto obligado de que se trate. \n Las personas particulares podrán impugnar las resoluciones de la Autoridad garante federal ante los jueces y \n tribunales especializados en materia de transparencia establecidos por el Poder Judicial de l a Federación. \n Capítulo III \n Del Recurso de Revisión en Materia de Seguridad Nacional","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Inconformidad","seccion_nombre":null,"orden":179},{"id":"6d95f26f-b187-494e-97f6-5559d994728d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 184.","contenido":"La persona titular de la Consejería Jurídica del Ejecutivo Federal podrá interponer recurso de \n revisión en materia de seguridad nacional directamente ante la Suprema Corte de Justicia de la Nación, cuando \n considere que las resoluciones emitidas por la Autoridad garante federal ponen en peligro la seguridad nacional. \n El recurso debe interponerse durante los siete días siguientes a aquél en el que la Autoridad ga rante notifique la \n resolución al sujeto obligado. La Suprema Corte de Justicia de la Nación determinará, de inmediato, en su caso, la \n suspensión de la ejecución de la resolución y dentro de los cinco días siguientes a la interposición del recurso \n resolverá sobre su admisión o improcedencia.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"orden":180},{"id":"92aea394-7140-454d-86ee-4355651ee5d9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 185.","contenido":"En el escrito del recurso, la persona titular de la Consejería Jurídica del Ejecutivo Federal debe \n señalar la resolución que se impugna, los fundamentos y motivos por los cuales considera que vulnera la seg uridad \n nacional, así como los elementos de prueba necesarios.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"orden":181},{"id":"4bbde2f1-b3e0-430e-97e7-6d6abaf7f782","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 186.","contenido":"La información reservada o confidencial que, en su caso, sea solicitada por la Suprema Corte de \n Justicia de la Nación por resultar indispensable para resolver el asunto, debe mante nerse con ese carácter y no \n estará disponible en el Expediente, salvo en las excepciones previstas en el artículo 119 de la presente Ley. \n En todo momento, las Ministras y los Ministros deben tener acceso a la información clasificada para determinar su \n natu raleza, según se requiera. El acceso se dará de conformidad con las disposiciones jurídicas aplicables al \n resguardo o salvaguarda de la información por parte de los sujetos obligados.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión","seccion_nombre":null,"orden":182},{"id":"5a8d1d37-4520-4067-afd0-f4ed7adda9dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 187.","contenido":"La Suprema Corte de Justicia de la Nación resolverá con pl enitud de jurisdicción, y en ningún caso, \n procederá el reenvío.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"orden":183},{"id":"68da5d35-f944-41ef-8f6e-f01c9b3ccc9a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 188.","contenido":"Si la Suprema Corte de Justicia de la Nación confirma el sentido de la resolución recurrida, el sujeto \n obligado deberá dar cumplimiento y entregar la información en los términos que establece el artículo 191 de esta Ley. \n En caso de que se revoque la resolución, la Autoridad garante federal debe actuar en los términos que ordene la \n Suprema Corte de Justicia de la Nación. \n Capítulo IV \n Del Recurso de Revisión de Asuntos Jurisdiccional es de la Suprema Corte de Justicia de la Nación","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"orden":184},{"id":"a93f46c3-3599-4417-bef3-7550d4c60884","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 189.","contenido":"En la aplicación de las disposiciones de la presente Ley, relacionadas con la información de \n asuntos jurisdiccionales de la Suprema Corte de Justicia de la Nación, se debe crear un comité especi alizado en \n materia de acceso a la información integrado por tres ministros. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 57 de 64 \n Para resolver los recursos de revisión relacionados con la información de asuntos jurisdiccionales, dicho comité \n atenderá a los principios, reglas y procedimientos de resolución es tablecidos en la presente Ley y tendrá las \n atribuciones de las Autoridades garantes.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión de Asuntos Jurisdiccional es de la Suprema Corte de Justicia de la Nación","seccion_nombre":null,"orden":185},{"id":"3a2e8d6c-9fe9-4a40-b471-d0e869309305","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 190.","contenido":"Se entienden como asuntos jurisdiccionales, aquellos que estén relacionados con el ejercicio de la \n función constitucional de impartición de justicia competen cia de la Suprema Corte de Justicia de la Nación, en \n términos de lo previsto por la Ley Orgánica del Poder Judicial de la Federación. \n La Suprema Corte de Justicia de la Nación podrá emitir un Acuerdo para la integración, plazos, términos y \n procedimientos d el Comité referido, de conformidad con los principios, reglas y procedimientos de resolución \n establecidos en esta Ley. \n Capítulo V \n Del Cumplimiento de las Resoluciones","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Recurso de Revisión de Asuntos Jurisdiccional es de la Suprema Corte de Justicia de la Nación","seccion_nombre":null,"orden":186},{"id":"16f53e07-cb2a-484b-b548-47d2489cee6b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   191.","contenido":"Los sujetos obligados deben, por medio de sus Unidades de Transparencia, da r estricto \n cumplimiento a las resoluciones de las Autoridades garantes, y deberán informar a estos sobre su cumplimiento. \n Excepcionalmente, considerando las circunstancias especiales del caso, los sujetos obligados podrán solicitar a \n las Autoridades garant es, de manera fundada y motivada, una ampliación del plazo para el cumplimiento de la \n resolución. \n Dicha solicitud debe presentarse, a más tardar, dentro de los primeros tres días del plazo otorgado para el \n cumplimiento, a efecto de que las Autoridades gara ntes, resuelvan sobre la procedencia de la misma dentro de los \n cinco días siguientes.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Cumplimiento de las Resoluciones","seccion_nombre":null,"orden":187},{"id":"ccc04dd2-fa21-461f-8912-3f0788e668a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 192.","contenido":"Transcurrido el plazo señalado en el artículo anterior, el sujeto obligado debe informar a la \n Autoridad garante sobre el cumplimiento de la resolución y pub licar en la Plataforma Nacional la información con la \n que se atendió a la misma. \n La Autoridad garante verificará de oficio la calidad de la información y, a más tardar al día siguiente de recibir el \n informe, dará vista al recurrente para que, dentro de los cinco días siguientes, manifieste lo que a su derecho \n convenga. Si dentro del plazo señalado el recurrente manifiesta que el cumplimiento no corresponde a lo ordenado \n por la Autoridad garante, deberá expresar las causas específicas por las cuales así lo c onsidera.","tipo_articulo":"ordinario","titulo_nombre":"OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"orden":188},{"id":"c5a26c75-6078-42b6-aed7-229b022179ae","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 193.","contenido":"La Autoridad garante deberá pronunciarse, en un plazo no mayor a cinco días, sobre todas las \n causas que el recurrente manifieste, así como del resultado de la verificación realizada. Si la autoridad antes \n señalada considera que se d io cumplimiento a la resolución, emitirá un acuerdo de cumplimiento y se ordenará el \n archivo del Expediente. En caso contrario, dicha autoridad: \n I. Emitirá un acuerdo de incumplimiento; \n II. Notificará al superior jerárquico del responsable de dar cumplimie nto, para el efecto de que, en un \n plazo no mayor a cinco días, se dé cumplimiento a la resolución, y \n III. Determinarán las medidas de apremio o sanciones, según corresponda, que deberán imponerse o las \n acciones procedentes que deberán aplicarse, de conform idad con lo señalado en el siguiente Título. \n Capítulo VI \n De los Criterios de Interpretación","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"Del Cumplimiento de las Resoluciones","seccion_nombre":null,"orden":189},{"id":"70232c87-e490-4b1b-bca9-48344e2ab5ce","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 194.","contenido":"Una vez que hayan causado ejecutoria las resoluciones dictadas en los recursos que se sometan a \n su competencia, la Autoridad garante federal podrá emi tir los criterios de interpretación que estime pertinentes y que \n deriven de lo resuelto en dichos asuntos. \n La Autoridad garante federal podrá emitir criterios de carácter orientador para las Autoridades garantes, que se \n establecerán por reiteración al reso lver tres casos análogos de manera consecutiva en el mismo sentido, derivados \n de resoluciones que hayan causado estado.","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"De los Criterios de Interpretación","seccion_nombre":null,"orden":190},{"id":"d17148cb-8d07-42df-9a83-8c608f5a559d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 195.","contenido":"Los criterios se compondrán de un rubro, un texto y el precedente o precedentes que, en su caso, \n hayan originado su emisió n. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 58 de 64 \n Todo criterio que emita la Autoridad garante federal debe contener una clave de control para su debida \n identificación. \n TÍTULO NOVENO \n MEDIDAS DE APREMIO Y SANCIONES \n Capítulo I \n De las Medidas de Apremio","tipo_articulo":"ordinario","titulo_nombre":"PROCEDIMIENTOS DE ACCESO A LA INFORMA CIÓN PÚBLICA","capitulo_nombre":"De los Criterios de Interpretación","seccion_nombre":null,"orden":191},{"id":"89bb735b-eaf5-4f41-8954-ad6d7ddd5593","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 196.","contenido":"Las Autoridades garantes, en sus respe ctivos ámbitos de competencia, podrán imponer a la \n persona servidora pública encargada de cumplir con la resolución, o a las y los miembros de los sindicatos, partidos \n políticos o a la persona física o moral responsable, las siguientes medidas de apremio p ara asegurar el cumplimiento \n de sus determinaciones: \n I. Amonestación pública, o \n II. Multa, de ciento cincuenta hasta mil quinientas veces la Unidad de Medida y Actualización vigente al \n momento en que se cometa el incumplimiento.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":192},{"id":"cf519bef-b844-4885-a09c-f0c0c4bd0ed1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 197.","contenido":"Para califica r las medidas de apremio, las Autoridades garantes deberán considerar: \n I. La gravedad de la falta del sujeto obligado, determinada por elementos tales como el daño causado, \n los indicios de intencionalidad, la duración del incumplimiento de las determinacio nes de las \n Autoridades garantes, y la afectación al ejercicio de sus atribuciones; \n II. La condición económica de la persona infractora, y \n III. La reincidencia. \n El incumplimiento de los sujetos obligados será difundido en la Plataforma Nacional y en los por tales de \n obligaciones de transparencia de las Autoridades garantes y considerado en las evaluaciones que realicen estas.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":193},{"id":"10bc9647-a62c-4be5-8ece-05e7ee9e3a0a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 198.","contenido":"En caso de reincidencia, las Autoridades garantes podrán imponer una multa equivalente hasta el \n doble de la que se hubier a determinado por las mismas. \n Se considerará reincidente al que habiendo incurrido en una infracción que haya sido sancionada, cometa otra \n del mismo tipo o naturaleza. \n En caso de que el incumplimiento de las determinaciones de las Autoridades garantes impl ique la presunta \n comisión de un delito o una de las conductas señaladas en el artículo 204 de esta Ley, la Autoridad garante \n respectiva deberá denunciar los hechos ante la autoridad competente. \n Las medidas de apremio de carácter económico no podrán ser cub iertas con recursos públicos.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":194},{"id":"cf9cc1a3-22b2-4d37-a20f-39ea2154bf78","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 199.","contenido":"Si a pesar de la ejecución de las medidas de apremio previstas en el artículo anterior no se cumple \n con la determinación, se requerirá el cumplimiento al superior jerárquico para que en un plazo de cinco días lo \n instruya a cumplir sin demora. De persistir el incumplimiento, se aplicarán sobre el superior jerárquico las medidas de \n apremio establecidas en el artículo anterior. \n Transcurrido el plazo, sin que se haya dado cumplimiento, en su caso, determinará las sanc iones que \n correspondan.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":195},{"id":"e34d4a63-30e9-405e-a3b6-3f87e59589b8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 200.","contenido":"Las medidas de apremio a que se refiere el presente Capítulo, deberán ser impuestas por \n Autoridades garantes y ejecutadas por sí mismas o con el apoyo de la autoridad competente, de conformidad con los \n procedimientos q ue establezcan las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":196},{"id":"7e9c4bc3-22b7-41d3-be81-822e0b4f8477","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 201.","contenido":"Las medidas de apremio deberán aplicarse e implementarse en un plazo máximo de quince días, \n contados a partir de que sea notificada la medida de apremio a la persona infractora.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":197},{"id":"686079ab-cd48-40bf-a53f-cb3f1943d45f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   202.","contenido":"La amonestación pública será impuesta y ejecutada por las Autoridades garantes, a excepción de \n cuando se trate de personas servidoras públicas, en cuyo caso será ejecutada por el superior jerárquico inmediato de \n la persona infractora con el que se rel acione. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 59 de 64 \n Las multas que fijen las Autoridades garantes se harán efectivas ante el Servicio de Administración Tributaria o \n las Secretarías de Finanzas de las entidades federativas, según corresponda, a través de los procedimientos que las \n leyes establezcan.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":198},{"id":"61979a6b-2a19-45ca-8209-64d71c1a80f4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 203.","contenido":"Será supletorio a los mecanismos de notificación y ejecución de medidas de apremio, lo dispuesto \n en la Ley Federal de Procedimiento Administrativo y la equivalente en las entidades federativas. \n Capítulo II \n De las Sanciones","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Medidas de Apremio","seccion_nombre":null,"orden":199},{"id":"01e7c8c6-9dfd-4bfe-9b3a-b07082a42ecf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 204.","contenido":"Serán causas de sanción por incumplimiento de las obligaciones establecidas en la materia de la \n presente Ley, al menos las siguientes: \n I. La falta de respuesta a las solicitudes de información en los plazos señalados en las disposiciones \n jurídicas aplicables; \n I I. Actuar con negligencia, dolo o mala fe durante la sustanciación de las solicitudes en materia de acceso \n a la información o bien, al no difundir la información relativa a las obligaciones de transparencia \n previstas en la presente Ley; \n III. Incumplir los plazos de atención previstos en la presente Ley; \n IV. Usar, sustraer, divulgar, ocultar, alterar, mutilar, destruir o inutilizar, total o parcialmente, sin causa \n legítima, conforme a las facultades correspondientes, la información que se encuentre bajo la c ustodia \n de los sujetos obligados y de sus personas servidoras públicas o a la cual tengan acceso o \n conocimiento con motivo de su empleo, cargo o comisión; \n V. Entregar información incomprensible, incompleta, en un formato no accesible, una modalidad de enví o \n o de entrega diferente a la solicitada previamente por personas usuarias en su solicitud de acceso a la \n información, al responder sin la debida motivación y fundamentación establecidas en esta Ley; \n VI. No actualizar la información correspondiente a las o bligaciones de transparencia en los plazos \n previstos en la presente Ley; \n VII. Declarar con dolo o negligencia la inexistencia de información cuando el sujeto obligado deba \n generarla, derivado del ejercicio de sus facultades, competencias o funciones; \n VIII. Declarar la inexistencia de la información cuando exista total o parcialmente en sus archivos; \n IX. No documentar con dolo o negligencia, el ejercicio de sus facultades, competencias, funciones o actos \n de autoridad, de conformidad con las disposiciones jur ídicas aplicables; \n X. Realizar actos para intimidar a las personas solicitantes de información o inhibir el ejercicio del \n derecho; \n XI. Denegar intencionalmente información que no se encuentre clasificada como reservada o confidencial; \n XII. Clasificar como reservada, con dolo o negligencia, la información sin que se cumplan las \n características señaladas en la presente Ley. La sanción procederá cuando exista una resolución \n previa de las Autoridades garantes, que haya quedado firme; \n XIII. No desclasificar la i nformación como reservada cuando los motivos que le dieron origen ya no existan \n o haya fenecido el plazo, cuando Autoridades garantes, determinen que existe una causa de interés \n público que persiste o no se solicite la prórroga al Comité de Transparencia; \n XIV. No atender los requerimientos establecidos en la presente Ley, emitidos por las Autoridades garantes, \n o \n XV. No acatar las resoluciones emitidas por las Autoridades garantes, en ejercicio de sus funciones. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 60 de 64","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":200},{"id":"60b53040-0dbd-4462-b59c-4cc59e9e40c4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 205.","contenido":"Para determinar el monto de las multas y calificar las sanciones establecidas en el presente \n Capítulo, la Autoridad garante deberá considerar: \n I. La gravedad de la falta del sujeto obligado, determinada por elementos tales como el daño causado, \n los indicios de intencionalidad, la duració n del incumplimiento de las determinaciones de las \n Autoridades garantes, y la afectación al ejercicio de sus atribuciones; \n II. La condición económica de la persona infractora; \n III. La reincidencia, y \n IV. En su caso, el cumplimiento espontáneo de las obliga ciones que dieron origen al procedimiento \n sancionatorio, el cual podrá considerarse como atenuante de la sanción a imponerse.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":201},{"id":"e96ecd38-6651-4b8f-8fa8-341aa46c3abf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 206.","contenido":"Con independencia del carácter de las personas presuntas infractoras, las Autoridades garantes \n para conocer, investi gar, remitir documentación y, en su caso, sancionar, prescribirán en un plazo de cinco años a \n partir del día siguiente en que se hubieran cometido las infracciones o a partir del momento en que hubieren cesado, \n si fueren de carácter continuo. \n Las sanciones de carácter económico no podrán ser cubiertas con recursos públicos.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":202},{"id":"0b1ff391-1d78-4392-bfab-f15986fb453f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 207.","contenido":"Las conductas a que se refiere el artículo 204 serán sancionadas por las Autoridades garantes, \n según corresponda y, en su caso, conforme a su competencia darán vista a la a utoridad competente para que \n imponga o ejecute la sanción.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":203},{"id":"78e31f0d-4565-4a45-927e-1285bde9af2e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo   208.","contenido":"Las responsabilidades que resulten de los procedimientos administrativos correspondientes \n derivados de la violación a lo dispuesto por el artículo 204 de esta Ley, son independientes de las del orden civil, \n penal o de cualquier otro tipo que se puedan derivar de los mismos hechos. \n Dichas responsabilidades se determinarán, en forma autónoma, a través de los procedimientos previstos en las \n leyes aplicables y las sanciones que, en su caso , se impongan por las autoridades competentes, también se \n ejecutarán de manera independiente. \n Para tales efectos, las Autoridades garantes podrán denunciar ante las autoridades competentes cualquier acto u \n omisión violatoria de esta Ley y aportar las prueb as que consideren pertinentes, en los términos de las leyes \n aplicables.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":204},{"id":"59046737-40b0-48de-9a95-13f5a277da73","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 209.","contenido":"Ante incumplimientos en materia de transparencia y acceso a la información por parte de los \n partidos políticos, las Autoridades garantes darán vista, según corresponda, a l Instituto Nacional Electoral o a los \n organismos públicos locales electorales de las entidades federativas competentes, para que resuelvan lo \n conducente, sin perjuicio de las sanciones establecidas para los partidos políticos en las leyes aplicables. \n En e l caso de probables infracciones relacionadas con fideicomisos o fondos públicos, sindicatos o personas \n físicas o morales que reciban y ejerzan recursos públicos o realicen actos de autoridad, las Autoridades garantes \n deberán dar vista al órgano interno de control del sujeto obligado relacionado con estos, cuando sean personas \n servidoras públicas, con el fin de que instrumenten los procedimientos administrativos a que haya lugar.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":205},{"id":"19e4c33d-8ccd-4ddd-bcda-c821f0face81","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 210.","contenido":"En aquellos casos en que la persona presunta infractora tenga la calidad de persona servidora \n pública, las Autoridades garantes deberán remitir a la autoridad competente, junto con la denuncia correspondiente, \n un expediente en que se contengan todos los elementos que sustenten la presunta responsabilidad administrativa . \n La autoridad que conozca del asunto deberá informar de la conclusión del procedimiento y, en su caso, de la \n ejecución de la sanción a la autoridad denunciante.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":206},{"id":"b55753b5-470c-486c-9b0e-5dadc5c41744","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 211.","contenido":"Cuando se trate de personas presuntas infractoras que no cuenten con la calidad de personas \n servidoras públicas, las Autoridades garantes serán las autoridades facultadas para conocer y desahogar el \n procedimiento sancionatorio conforme a esta Ley, y llevar a cabo las acciones conducentes para la imposición y \n ejecución de las sanciones . \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 61 de 64","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":207},{"id":"905ec75f-860b-4a07-9a0b-1f282c8b0aa8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 212.","contenido":"El procedimiento a que se refiere el artículo anterior dará comienzo con la notificación que efectúe \n la Autoridad garante a la persona presunta infractora, sobre los hechos e imputaciones que motivaron el inicio del \n procedimiento y le otorg ará un término de quince días para que rinda pruebas y manifieste por escrito lo que a su \n derecho convenga. En caso de no hacerlo, la autoridad competente que conozca del procedimiento resolverá de \n inmediato con los elementos de convicción que disponga. \n La Autoridad garante admitirá las pruebas que estime pertinentes y procederá a su desahogo. Una vez \n desahogadas las pruebas, la Autoridad garante notificará a la persona presunta infractora el derecho que le asiste \n para que, de considerarlo necesario, presen te sus alegatos dentro de los cinco días siguientes a su notificación. \n Una vez analizadas las pruebas y demás elementos de convicción, la Autoridad garante resolverá, en definitiva, \n dentro de los treinta días siguientes a la fecha en que inició el procedim iento sancionador. Dicha resolución deberá \n ser notificada a la persona presunta infractora y, dentro de los diez días siguientes a la notificación, se hará pública la \n resolución correspondiente. \n Cuando haya causa justificada debidamente fundada y motivada, la autoridad que conozca del asunto podrá \n ampliar el plazo de resolución por una sola vez y hasta por un periodo igual.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":208},{"id":"c2c574ea-6301-4873-afc6-43f4af05018e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 213.","contenido":"En las normas respectivas de las Autoridades garantes se precisará toda circunstancia relativa a la \n forma, términos y cum plimiento de los plazos a que se refiere el procedimiento sancionatorio previsto en esta Ley, \n incluyendo la presentación de pruebas y alegatos, la celebración de audiencias, el cierre de instrucción y la ejecución \n de sanciones. En todo caso, será supletori o a este procedimiento sancionador lo dispuesto en las leyes en materia \n de procedimiento administrativo del orden jurídico que corresponda.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":209},{"id":"412f1184-8da6-4d74-aa58-9a09a1597439","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 214.","contenido":"Las infracciones a lo previsto en la presente Ley por parte de sujetos obligados que no cuenten con \n la calidad de persona servidora pública, serán sancionadas con: \n I. Apercibimiento, por única ocasión, para que el sujeto obligado cumpla su obligación de manera \n inmediata, en los términos previstos en esta Ley, tratándose de los supuestos previstos en las \n fr acciones I, III, V, VI y X del artículo 204 de esta Ley. \n Si una vez hecho el apercibimiento no se cumple de manera inmediata con la obligación en los \n términos previstos en esta Ley, tratándose de los supuestos mencionados en esta fracción, se aplicará \n mul ta de ciento cincuenta a doscientos cincuenta veces el valor diario de la Unidad de Medida y \n Actualización; \n II. Multa de doscientos cincuenta a ochocientas veces el valor diario de la Unidad de Medida y \n Actualización, en los casos previstos en las fraccion es II y IV del artículo 204 de esta Ley, y \n III. Multa de ochocientos a mil quinientas veces el valor diario de la Unidad de Medida y Actualización, en \n los casos previstos en las fracciones VII, VIII, IX, XI, XII, XIII, XIV y XV del artículo 204 de esta Ley . \n Se aplicará multa adicional de hasta cincuenta veces el valor diario de la Unidad de Medida y Actualización, por \n día, a quien persista en las infracciones citadas en los incisos anteriores.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":210},{"id":"98491028-bcc8-4403-98e6-27d1b06d1c00","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 215.","contenido":"En caso de que el incumplimiento de las determinac iones de las Autoridades garantes implique la \n presunta comisión de un delito, estos deberán denunciar los hechos ante la autoridad competente.","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":211},{"id":"8cf20cf8-73ca-4cb4-bca4-876d5ca59766","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Artículo 216.","contenido":"Las personas físicas o morales que reciban y ejerzan recursos públicos o ejerzan actos de \n autoridad deberán proporcionar la información que permita al sujeto obligado que corresponda, cumplir con sus \n obligaciones de transparencia y para atender las solicitudes de acceso correspondientes. \n Artículo Segundo a Artículo Cu arto. - … … .","tipo_articulo":"ordinario","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":212},{"id":"c8298e4a-12a8-49a7-b670-f338feb59def","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio PRIMERO.","contenido":"- El pres ente Decreto entrará en vigor al día siguiente de su publicación en el Diario Oficial de la \n Federación, con excepción de lo previsto en el transitorio Tercero de este instrumento.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":213},{"id":"468d8f0e-355e-4c33-a3e2-adf6ffb3ec4e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio SEGUNDO.","contenido":"- A la entrada en vigor del presente Decreto se abrogan las disposic iones siguientes: \n I. La Ley Federal de Protección de Datos Personales en Posesión de los Particulares, publicada en el \n Diario Oficial de la Federación el 5 de julio de 2010; \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 62 de 64 \n II. La Ley General de Transparencia y Acceso a la Información Pública, publicada e n el Diario Oficial de \n la Federación el 4 de mayo de 2015 y sus modificaciones posteriores; \n III. La Ley Federal de Transparencia y Acceso a la Información Pública, publicada en el Diario Oficial de la \n Federación el 9 de mayo de 2016 y sus modificaciones po steriores; \n IV. La Ley General de Protección de Datos Personales en Posesión de Sujetos Obligados, publicada en el \n Diario Oficial de la Federación el 26 de enero de 2017, y \n V. El Acuerdo mediante el cual se aprueba el Programa Anual de Verificación y Acompa ñamiento \n Institucional para el cumplimiento de las obligaciones en materia de acceso a la información y \n transparencia por parte de los sujetos obligados del ámbito federal, correspondiente al ejercicio 2025, \n publicado en el Diario Oficial de la Federación el 21 de enero de 2025.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":214},{"id":"5679e235-6e9e-4676-945e-5c0c8a942aa5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio TERCERO.","contenido":"- Los artículos 71 y 72 de la Ley General de Transparencia y Acceso a la Información Pública entrarán \n en vigor cuando se extingan la Comisión Federal de Competencia Económica y el Instituto Federal de \n Telecomunicaciones conf orme a lo previsto en los transitorios Décimo y Décimo Primero del “Decreto por el que se \n reforman, adicionan y derogan diversas disposiciones de la Constitución Política de los Estados Unidos Mexicanos, \n en materia de simplificación orgánica”, publicado en el Diario Oficial de la Federación el 20 de diciembre de 2024. \n Para efectos del párrafo anterior, la Comisión Federal de Competencia Económica y el Instituto Federal de \n Telecomunicaciones deberán poner a disposición del público y actualizar la información a que se refiere el artículo \n 72, fracciones II y V, respectivamente, de la Ley Federal de Transparencia y Acceso a la Información Pública que se \n abroga por virtud del presente Decreto.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":215},{"id":"6cbde3f7-fe92-45cc-bc19-ffef59dbbcb5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio CUARTO.","contenido":"- Las menciones, atribuciones o funciones contenidas en otras l eyes, reglamentos y, en general, en \n cualquier disposición normativa, respecto al Instituto Nacional de Transparencia, Acceso a la Información y \n Protección de Datos Personales se entenderán hechas o conferidas a los entes públicos que adquieren tales \n atribu ciones o funciones, según corresponda.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":216},{"id":"5c4d4813-0952-43e4-95c0-bfa64f2bcc78","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio QUINTO.","contenido":"- Los derechos laborales de las personas servidoras públicas del Instituto Nacional de Transparencia, \n Acceso a la Información y Protección de Datos Personales, serán respetados, en términos de la legislación ap licable. \n Los recursos humanos con que cuente el referido Instituto pasarán a formar parte de la Secretaría Anticorrupción y \n Buen Gobierno y Transparencia para el Pueblo. \n El Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales transferirá los \n recursos correspondientes al valor del inventario o plantilla de plazas a la Secretaría de Hacienda y Crédito Público, \n dentro de los veinte días hábiles siguientes contados a partir de la entrada en vigor del presente Decreto, a fin de que \n esa dependencia realice las acciones que correspondan, conforme a las disposiciones jurídicas aplicables. \n Las personas servidoras públicas del Instituto Nacional de Transparencia, Acceso a la Información y Protección \n de Datos Personales que deje n de prestar sus servicios en el mencionado Instituto y que estén obligadas a presentar \n declaración patrimonial y de intereses, de conformidad con las disposiciones jurídicas aplicables, lo realizarán en los \n sistemas de la Secretaría Anticorrupción y Buen Gobierno habilitados para tales efectos o en los medios que esta \n determine y conforme a la normativa aplicable a la Administración Pública Federal. Lo anterior también es aplicable a \n las personas que se hayan desempeñado como servidoras públicas en el menc ionado Instituto y que a la fecha de \n entrada en vigor del presente Decreto aún tengan pendiente cumplir con dicha obligación. \n Las personas que dentro de los diez días previos a la entrada en vigor del presente Decreto se hayan \n desempeñado como personas ser vidoras públicas del Instituto Nacional de Transparencia, Acceso a la Información y \n Protección de Datos Personales, incluyendo a las personas Comisionadas, deben presentar acta administrativa de \n entrega - recepción institucional e individual, según correspon da, a la persona servidora pública que la Secretaría \n Anticorrupción y Buen Gobierno designe y conforme a la normativa aplicable a la Administración Pública Federal, en \n los sistemas de la referida dependencia habilitados para tales efectos o en los medios q ue ésta determine, en el \n entendido que la entrega que se realice no implica liberación alguna de responsabilidades que pudieran llegarse a \n determinar por la autoridad competente con posterioridad.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":217},{"id":"2c0fc9d6-901d-4a1d-bb5d-6f849c5fb094","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio SEXTO.","contenido":"- Los recursos materiales con que cuente el Instituto Nacional de Transparencia, Acceso a la Información y \n Protección de Datos Personales serán transferidos a la Secretaría Anticorrupción y Buen Gobierno, dentro de los \n veinte días hábiles siguientes a la entrada en vigor del presente Decreto.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":218},{"id":"b2b7e9e3-13cc-47c9-a243-586269c3bb41","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio SÉPTIMO.","contenido":"- El In stituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales \n transferirá los recursos financieros a la Secretaría de Hacienda y Crédito Público, de conformidad con las \n disposiciones jurídicas aplicables. \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 63 de 64 \n Asimismo, el Institut o Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales \n deberá entregar a la citada dependencia la información y formatos necesarios para integrar la Cuenta Pública y \n demás informes correspondientes al primer trimestre, de con formidad con las disposiciones jurídicas aplicables, \n dentro de los diez días hábiles siguientes a la entrada en vigor del presente Decreto.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":219},{"id":"bf7f92e1-6d46-41c9-8804-78977e3cfc98","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio OCTAVO.","contenido":"- Los registros, padrones y sistemas, internos y externos, que integran la Plataforma Nacional de \n Transparenc ia con los que cuenta el Instituto Nacional de Transparencia, Acceso a la Información y Protección de \n Datos Personales, así como los sistemas informáticos utilizados por dicho Instituto, incluso los que ya no se utilicen \n pero contengan registros históricos , incluida su documentación y titularidad, serán transferidos a la Secretaría \n Anticorrupción y Buen Gobierno dentro de los quince días hábiles siguientes a la entrada en vigor del presente \n Decreto.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":220},{"id":"8c638c66-4740-4154-96b4-eb7274dc69d6","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio NOVENO.","contenido":"- Los procedimientos iniciados con anterioridad a l a entrada en vigor de este Decreto ante el Instituto \n Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales, en materia de acceso a la \n información pública, se sustanciarán ante Transparencia para el Pueblo conforme a las dispos iciones aplicables \n vigentes al momento de su inicio. \n La defensa legal ante autoridades administrativas, jurisdiccionales y judiciales de los actos administrativos y \n jurídicos emitidos por el Instituto Nacional de Transparencia, Acceso a la Información y Pr otección de Datos \n Personales, en materia de acceso a la información pública, se llevará a cabo por Transparencia para el Pueblo. \n Transparencia para el Pueblo podrá remitir a la Autoridad garante competente aquellos asuntos que se \n mencionan en los párrafos anteriores que le corresponda conforme al ámbito de sus atribuciones para su atención.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":221},{"id":"593efe8c-0d80-46e0-8523-d7a1179ecc9c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO.","contenido":"- Los procedimientos iniciados con anterioridad a la entrada en vigor de este Decreto ante el Instituto \n Nacional de Transparencia, Acceso a la Información y Prote cción de Datos Personales, en materia de datos \n personales o cualquier otra distinta a la mencionada en el transitorio anterior, se sustanciarán conforme a las \n disposiciones vigentes al momento de su inicio ante la Secretaría Anticorrupción y Buen Gobierno a que se refiere \n este Decreto. \n La defensa legal ante autoridades administrativas, jurisdiccionales o judiciales de los actos administrativos y \n jurídicos emitidos por el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos \n Pers onales, en materia de datos personales o cualquier otra distinta a la mencionada en el transitorio anterior, así \n como el seguimiento de los que se encuentren en trámite, incluso los procedimientos penales y laborales, se llevará \n a cabo por la Secretaría An ticorrupción y Buen Gobierno. \n La Secretaría Anticorrupción y Buen Gobierno podrá remitir a la Autoridad garante competente aquellos asuntos \n que se mencionan en los párrafos anteriores que le corresponda conforme al ámbito de sus atribuciones para su \n atenci ón.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":222},{"id":"252b71d8-5f9c-4e07-bc78-26fac9fd53d1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO PRIMERO.","contenido":"- Los municipios podrán cumplir con las obligaciones a su cargo en materia de transparencia y \n acceso a la información, en términos de lo previsto en el transitorio Décimo de la Ley General de Transparencia y \n Acceso a la Información Públi ca que se abroga por virtud de este Decreto.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":223},{"id":"9198e281-5235-4d1f-9478-aab24cc68160","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO SEGUNDO.","contenido":"- La persona titular del Ejecutivo Federal deberá expedir las adecuaciones correspondientes a \n los reglamentos y demás disposiciones aplicables, incluida la emisión del Reglamento Interior de Trans parencia para \n el Pueblo, dentro de los noventa días naturales siguientes a la entrada en vigor del presente Decreto, a fin de \n armonizarlos a lo previsto en el mismo.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":224},{"id":"5bda8869-09e0-4707-8813-3a1ec550723f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO TERCERO.","contenido":"- Los expedientes y archivos que a la entrada en vigor del presente Decreto estén a cargo del \n Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales para el ejercicio de \n sus facultades sustantivas, competencias o funciones, de conformidad con la Ley General de Archivos y demás \n disposiciones jurídicas aplicables, serán transferidos a la Secretaría Anticorrupción y Buen Gobierno dentro de los \n veinte días hábiles siguientes a la entrada en vigor del presente Decreto. \n La Secretaría Anticorrupción y Buen Gobierno, dentro de los treinta días natura les siguientes contados a partir de \n que se reciban los expedientes y archivos que se mencionan en el párrafo anterior, podrá transferirlos a la autoridad \n correspondiente.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":225},{"id":"4bcf91fb-ff03-499f-9fb1-605e4d04e8b3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO CUARTO.","contenido":"- El Órgano Interno de Control del Instituto Nacional de Transparencia, Acceso a la Información y \n Protección de Datos Personales queda extinto y sus asuntos y procedimientos que a la entrada en vigor del presente \n Decreto estén a su cargo, así como los expedientes y archivos, serán transferidos al Órgano Interno de Control de la \n Secretaría Anticorrupción y Buen Gobierno dentro de los veinte días hábiles siguientes a su entrada en vigor, y serán \n tramitados y resueltos por dicho órgano conforme a las disposiciones jurídicas vigentes al momento de su inicio.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":226},{"id":"ef6d3e97-6ad6-44e8-b657-52f4c54318e2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO QUINTO.","contenido":"- Para e fectos de lo dispuesto en los transitorios Quinto, Sexto, Séptimo, Octavo y Décimo","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":227},{"id":"d574ce36-1a91-48f5-8bfd-0ce28b0e8103","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio TERCERO","contenido":"del presente Decreto el Pleno del Instituto Nacional de Transparencia, Acceso a la Información y Protección \n de Datos Personales deberá integrar, en la fecha de publi cación de este instrumento, un Comité de Transferencia \n\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Secretaría General \n Secretaría de Servicios Parlamenta rios \n Nueva Ley DOF 20 - 03 - 2025 \n 64 de 64 \n conformado por los Comisionados del mencionado Instituto y once personas servidoras públicas del mismo con al \n menos el nivel de Dirección de área o equivalente, que tengan conocimiento o que se encuent ren a su cargo los \n asuntos que se mencionan en los propios transitorios. \n El Comité de Transferencia estará vigente por un periodo de 30 días naturales, en el que sus integrantes \n participarán con las diversas autoridades competentes para recibir los asuntos que se señalan en los transitorios \n antes citados y realizar las demás acciones que se consideren necesarias para dichos efectos.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":228},{"id":"bbce4d22-15fc-4afb-8544-38b3d00c865f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO SEXTO.","contenido":"- El Consejo del Sistema Nacional de Acceso a la Información Pública deberá instalarse a más \n tardar en sesenta dí as naturales, a partir de la entrada en vigor del presente Decreto, previa convocatoria que al \n efecto emita la Secretaría Anticorrupción y Buen Gobierno. \n Hasta en tanto las legislaturas de las entidades federativas que correspondan armonizan su marco juríd ico en \n materia de acceso a la información pública en términos de lo previsto en el transitorio Cuarto del Decreto por el que \n se reforman, adicionan y derogan diversas disposiciones de la Constitución Política de los Estados Unidos \n Mexicanos, en materia de simplificación orgánica, publicado en el Diario Oficial de la Federación el 20 de diciembre \n de 2024, la persona titular del poder ejecutivo local de que se trate será integrante del Consejo del Sistema Nacional \n de Acceso a la Información Pública.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":229},{"id":"aeb089ab-04ef-4c9c-860e-ce2cbf77c947","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO","contenido":"Sé ptimo. - La persona titular de la Secretaría Ejecutiva del Consejo del Sistema Nacional de Acceso a la \n Información Pública propondrá las reglas de operación y funcionamiento que se señalan en el artículo 25, fracción \n XV, de la Ley General de Transparencia y Acceso a la Información Pública, para que sean aprobadas en la \n instalación de dicho Consejo.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":230},{"id":"3c626412-3bcb-452d-a6bb-a5b6788060ef","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO OCTAVO.","contenido":"- El órgano de control y disciplina del Poder Judicial; los órganos internos de control de los \n órganos constitucionales autónomos; las contralorías internas del Congreso de la Unión; el Instituto Nacional \n Electoral; el Centro Federal de Conciliación y Registro Laboral y el Tribunal Federal de Conciliación y Arbitraje en un \n plazo máximo de treinta días naturales contados a partir de la entrada en vigor del presente Decreto deberán realizar \n las adecuaciones necesarias a su normativa interna para dar cumplimiento a lo dispuesto en este instrumento. \n Para efectos de lo previsto en este transitorio, se suspenden por un plazo de noventa días naturales contado s a \n partir de la entrada en vigor de este Decreto todos y cada uno de los trámites, procedimientos y demás medios de \n impugnación, establecidos en este instrumento y demás normativa aplicable, con excepción de la recepción y \n atención de las solicitudes de i nformación que se tramitan a través de la Plataforma Nacional de Transparencia por \n las autoridades que se mencionan en el párrafo anterior.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":231},{"id":"88e2a81e-a10a-4a97-99de-3941abccdd7f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO NOVENO.","contenido":"- Hasta en tanto las legislaturas de las entidades federativas, emitan legislación para armonizar \n su m arco jurídico conforme al presente Decreto, los organismos garantes de las mismas continuarán operando y \n realizarán las atribuciones que le son conferidas a las Autoridades garantes locales, así como a los órganos \n encargados de la contraloría interna u hom ólogos de los poderes legislativo y judicial, así como los órganos \n constitucionales autónomos de las propias entidades federativas en la presente Ley.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":232},{"id":"f10bb70f-0076-48ef-85e3-7f88d6b60ad5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio VIGÉSIMO.","contenido":"- El Poder Judicial de la Federación deberá habilitar juzgados de Distrito y tribunales Colegiad os de \n Circuito especializados en materia de acceso a la información pública y protección de datos personales, en un plazo \n no mayor a ciento veinte días naturales contados a partir de la entrada en vigor del presente Decreto, a los cuales se \n remitirán los j uicios de amparo en dichas materias que se encuentran en trámite para su resolución. \n Para efectos de lo previsto en este transitorio, se suspenden por un plazo de ciento ochenta días naturales \n contados a partir de la entrada en vigor de este Decreto los pl azos y términos procesales de los juicios de amparo en \n materia de acceso a la información pública y protección de datos personales que se encuentran en trámite ante \n juzgados de Distrito y tribunales Colegiados de Circuito. \n Ciudad de México, a 20 de marzo d e 2025. - Sen. Imelda Castro Castro, Vicepresidenta. - Dip. Sergio Carlos \n Gutiérrez Luna, Presidente. - Sen. Verónica Noemí Camino Farjat, Secretaria. - Dip. José Luis Montalvo Luna, \n Secretario. - Rúbricas. \" \n En cumplimiento de lo dispuesto por la fracción I del Artículo 89 de la Constitución Política de los Estados Unidos \n Mexicanos, y para su debida publicación y observancia, expido el presente Decreto en la Residencia del Poder \n Ejecutivo Federal, en la Ciudad de México, a 20 de marzo de 2025. - Claudia Sheinbaum Pardo , Presidenta de los \n Estados Unidos Mexicanos . - Rúbrica. - Lcda. Rosa Icela Rodríguez Velázquez , Secretaria de Gobernación . - \n Rúbrica.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":233}],"remove":["2ae64ea3-1f7d-589f-b18e-4cd56f9158cb","a4b94738-aa88-5e2d-be46-574a622d9b56","735e4645-e3a9-5bf5-b020-31389339132d","026c1a92-17c7-56e4-b296-00c044fcbb91","76a754ac-f657-5a89-82f0-475075494e93"],"themes_before":[{"nivel":"titulo","nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","orden":0},{"nivel":"capitulo","nombre":"Capítulo I Disposiciones Preliminares","orden":1},{"nivel":"capitulo","nombre":"Capítulo II De los Principios Generales","orden":2},{"nivel":"seccion","nombre":"Sección Primera De los principios rectores de las Autoridades garantes","orden":3},{"nivel":"seccion","nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","orden":4},{"nivel":"capitulo","nombre":"Capítulo III De los Sujetos Obligados","orden":5},{"nivel":"titulo","nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","orden":6},{"nivel":"capitulo","nombre":"Capítulo I Del Sistema Nacional","orden":7},{"nivel":"capitulo","nombre":"Capítulo II Del Consejo Nacional","orden":8},{"nivel":"capitulo","nombre":"Capítulo III De los Subsistemas de Transparencia","orden":9},{"nivel":"capitulo","nombre":"Capítulo IV De las Autoridades garantes","orden":10},{"nivel":"capitulo","nombre":"Capítulo V De los Comités de Transparencia","orden":11},{"nivel":"capitulo","nombre":"Capítulo VI De las Unidades de Transparencia","orden":12},{"nivel":"titulo","nombre":"TÍTULO TERCERO PLATAFORMA NACIONAL DE TRANSPARENCIA","orden":13},{"nivel":"capitulo","nombre":"Capítulo Único De la Plataforma Nacional de Transparencia","orden":14},{"nivel":"titulo","nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","orden":15},{"nivel":"capitulo","nombre":"Capítulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","orden":16},{"nivel":"capitulo","nombre":"Capítulo II De la Transparencia con Sentido Social","orden":17},{"nivel":"capitulo","nombre":"Capítulo III De la Apertura Institucional","orden":18},{"nivel":"titulo","nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","orden":19},{"nivel":"capitulo","nombre":"Capítulo I De las Obligaciones Generales","orden":20},{"nivel":"capitulo","nombre":"Capítulo II De las Obligaciones de Transparencia Comunes","orden":21},{"nivel":"capitulo","nombre":"Capítulo III De las Obligaciones Específicas","orden":22},{"nivel":"capitulo","nombre":"Capítulo IV De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","orden":23},{"nivel":"capitulo","nombre":"Capítulo V De las Obligaciones Específicas en Materia Energética","orden":24},{"nivel":"capitulo","nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","orden":25},{"nivel":"capitulo","nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","orden":26},{"nivel":"titulo","nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","orden":27},{"nivel":"capitulo","nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","orden":28},{"nivel":"capitulo","nombre":"Capítulo II De la Información Reservada","orden":29},{"nivel":"capitulo","nombre":"Capítulo III De la Información Confidencial","orden":30},{"nivel":"capitulo","nombre":"Capítulo IV De las Versiones Públicas","orden":31},{"nivel":"titulo","nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","orden":32},{"nivel":"capitulo","nombre":"Capítulo I Del Procedimiento de Acceso a la Información","orden":33},{"nivel":"capitulo","nombre":"Capítulo II De las Cuotas de Acceso","orden":34},{"nivel":"titulo","nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","orden":35},{"nivel":"capitulo","nombre":"Capítulo I Del Recurso de Revisión","orden":36},{"nivel":"capitulo","nombre":"Capítulo II Del Recurso de Inconformidad","orden":37},{"nivel":"capitulo","nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","orden":38},{"nivel":"capitulo","nombre":"Capítulo IV Del Recurso de Revisión de Asuntos Jurisdiccionales de la Suprema Corte de Justicia de la Nación","orden":39},{"nivel":"capitulo","nombre":"Capítulo V Del Cumplimiento de las Resoluciones","orden":40},{"nivel":"capitulo","nombre":"Capítulo VI De los Criterios de Interpretación","orden":41},{"nivel":"titulo","nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","orden":42},{"nivel":"capitulo","nombre":"Capítulo I De las Medidas de Apremio","orden":43},{"nivel":"capitulo","nombre":"Capítulo II De las Sanciones","orden":44}],"themes_after":[],"date_before":"2025-03-20","date_after":"2025-03-20"}$payload$::jsonb; lid uuid; n integer;
BEGIN
 lid := (p->>'ley_id')::uuid;
 LOCK TABLE public.articulos, public.temas, public.user_favorites, public.user_notes IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.leyes WHERE id=lid FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.leyes WHERE id=lid AND fecha_publicacion=(p->>'date_before')::date) THEN RAISE EXCEPTION 'Cambió la fecha o el instrumento'; END IF;
 SELECT count(*) INTO n FROM public.articulos WHERE ley_id=lid;
 IF n<>jsonb_array_length(p->'before') THEN RAISE EXCEPTION 'Cambió el conteo antes de aplicar'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'before') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR md5(a.contenido) IS DISTINCT FROM b->>'contenido_md5' OR (to_jsonb(a)-'contenido'-'fts'-'created_at') IS DISTINCT FROM (b-'contenido_md5')) THEN RAISE EXCEPTION 'El respaldo ya no coincide con los artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_before') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'themes_before') b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE t.ley_id=lid AND (to_jsonb(t)-'created_at'-'id'-'ley_id')=b)) THEN RAISE EXCEPTION 'Cambió el índice de temas'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_favorites f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) OR EXISTS(SELECT 1 FROM public.user_notes f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) THEN RAISE EXCEPTION 'Hay referencias nuevas a fragmentos que se unirán: revisar traslado'; END IF;
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden)
 SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'after')
 ON CONFLICT(id) DO UPDATE SET identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre,orden=excluded.orden;
 DELETE FROM public.articulos WHERE ley_id=lid AND id IN(SELECT jsonb_array_elements_text(p->'remove')::uuid);
 DELETE FROM public.temas WHERE ley_id=lid;
 insert into public.temas(id,ley_id,nivel,nombre,orden) overriding system value select (t->>'id')::bigint,lid,t->>'nivel',t->>'nombre',(t->>'orden')::int from jsonb_array_elements(p->'themes_after') t;
